import { useEffect, useState } from "react";

import { Button } from "@/ui";
import type { SettingsPaneProps } from "./index";
import { PaneBanner, PaneCard, PaneEmpty, PaneRow, PaneSection, PaneShell, PaneSwitch } from "./pane-kit";
import { usePaneState } from "./pane-state";

/**
 * 钩子（官方 slug hooks-settings，chunk hooks-settings-88e3beb5a5e5.js + 5 个子 chunk）。
 *
 * 页结构证据（官方 zh-CN）：
 *   settings.hooks.subtitle「通过配置和已启用的插件管理生命周期钩子。<a>了解更多</a>」
 *   settings.hooks.trustAll（工具栏「全部信任」）、settings.hooks.refresh（「重新加载钩子」）
 *   来源分组 = settings.hooks.source.*（来自配置 / 来自插件 / 来自项目配置文件 / 其他来源）
 *   settings.hooks.emptyHooks.label「未找到钩子」/ .description「已配置的钩子将显示在此处」
 *   settings.hooks.loading.label「正在加载钩子…」、settings.hooks.loadError.label「无法加载钩子」
 *   （SPEC §4.2.12：页面主体是按来源分组的列表，行数随配置动态 → 官方行数未实测）
 *
 * 此页无实测几何，按通用规格推导（SPEC §8.1）。
 * 钩子列表本身没有官方初值（§8.2），所以默认空列表 + 空态；点「重新加载钩子」装载本机演示钩子。
 */

interface HookRow {
  id: string;
  name: string;
  event: string;
  source: string;
  command: string;
  trusted: boolean;
}

interface HooksPaneState {
  hooks: HookRow[];
  showLoading: boolean;
  lastError: string;
}

const DEFAULTS: HooksPaneState = { hooks: [], showLoading: false, lastError: "" };

/** 官方来源分组（settings.hooks.source.*）：键 = 分组 id，值 = 中文标题 */
const SOURCES: { id: string; label: string }[] = [
  { id: "config", label: "来自配置" },
  { id: "plugin", label: "来自插件" },
  { id: "project", label: "来自项目配置文件" },
  { id: "other", label: "其他来源" },
];

/** 本机演示钩子（官方只确证分组与空态文案，条目内容官方未实测） */
const DEMO_HOOKS: HookRow[] = [
  {
    id: "demo-1",
    name: "格式化改动文件",
    event: "PostToolUse",
    source: "config",
    command: "prettier --write $FILES",
    trusted: true,
  },
  {
    id: "demo-2",
    name: "提交前跑类型检查",
    event: "PreCommit",
    source: "project",
    command: "npx tsc -b --noEmit",
    trusted: false,
  },
  {
    id: "demo-3",
    name: "会话开始注入上下文",
    event: "SessionStart",
    source: "plugin",
    command: "node .hooks/session-start.mjs",
    trusted: true,
  },
];

export function HooksPane({ section }: SettingsPaneProps) {
  const [state, patch] = usePaneState(section, DEFAULTS);
  const [_reloadToken, _setReloadToken] = useState(0);

  useEffect(() => {
    if (!state.showLoading) return;
    const timer = window.setTimeout(() => {
      patch((prev) => ({
        ...prev,
        showLoading: false,
        hooks: prev.hooks.length > 0 ? prev.hooks : DEMO_HOOKS,
        lastError: "",
      }));
    }, 480);
    return () => window.clearTimeout(timer);
  }, [state.showLoading, patch]);

  function setHook(id: string, update: Partial<HookRow>) {
    patch((prev) => ({
      ...prev,
      hooks: prev.hooks.map((hook) => (hook.id === id ? { ...hook, ...update } : hook)),
    }));
  }

  function validate(hook: HookRow) {
    if (hook.command.trim().length === 0) {
      patch({ lastError: `钩子「${hook.name}」的命令不能为空，保存已跳过。` });
      return;
    }
    patch({ lastError: "" });
  }

  const trustedCount = state.hooks.filter((hook) => hook.trusted).length;

  return (
    <PaneShell
      section={section}
      title="钩子"
      lede="通过配置和已启用的插件管理生命周期钩子。钩子在工具调用、提交与会话事件上执行命令，请只信任你读得懂的脚本。"
      actions={
        <>
          <Button
            size="sm"
            variant="soft"
            color="secondary"
            onClick={() =>
              patch((prev) => ({
                ...prev,
                hooks: prev.hooks.map((hook) => ({ ...hook, trusted: true })),
              }))
            }
          >
            全部信任
          </Button>
          <Button
            size="sm"
            variant="soft"
            color="secondary"
            onClick={() => patch({ showLoading: true, lastError: "" })}
          >
            重新加载钩子
          </Button>
        </>
      }
    >
      {state.lastError ? (
        <PaneBanner tone="danger" title="无法加载钩子" description={state.lastError} />
      ) : null}

      <PaneSection
        title="已配置的钩子"
        description={
          state.hooks.length === 0
            ? "未找到钩子"
            : `${String(state.hooks.length)} 个钩子，其中 ${String(trustedCount)} 个已信任`
        }
      >
        <PaneCard>
          {state.showLoading ? (
            <PaneEmpty title="正在加载钩子…" description="正在从配置、插件与项目配置文件读取钩子定义。" />
          ) : state.hooks.length === 0 ? (
            <PaneEmpty
              title="未找到钩子"
              description="已配置的钩子将显示在此处。"
              action={
                <Button
                  size="sm"
                  variant="soft"
                  color="secondary"
                  onClick={() => patch({ showLoading: true })}
                >
                  重新加载钩子
                </Button>
              }
            />
          ) : (
            SOURCES.map((source) => {
              const rows = state.hooks.filter((hook) => hook.source === source.id);
              if (rows.length === 0) return null;
              return (
                <div key={source.id} className="cx-pane__list">
                  {rows.map((hook) => (
                    <PaneRow
                      key={hook.id}
                      label={hook.name}
                      description={
                        <span>
                          <code>{hook.command}</code> · {hook.event} · {source.label}
                        </span>
                      }
                      control={
                        <PaneSwitch
                          label={`${hook.name} 信任`}
                          checked={hook.trusted}
                          onChange={(checked) => {
                            setHook(hook.id, { trusted: checked });
                            validate({ ...hook, trusted: checked });
                          }}
                        />
                      }
                    />
                  ))}
                </div>
              );
            })
          )}
        </PaneCard>
      </PaneSection>
    </PaneShell>
  );
}
