import { useDeferredValue, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";

import {
  CodexChatBubble,
  CodexGear,
  type CodexIconProps,
  CodexKeyboard,
  CodexNewChat,
  CodexPlus,
  CodexSearch,
  CodexSettingsAppearance,
  CodexSettingsConfig,
  CodexSettingsConnections,
  CodexSettingsEnvironment,
  CodexSettingsGit,
  CodexSettingsHooks,
  CodexSettingsImport,
  CodexSettingsPersonalization,
  CodexSettingsPlugins,
  CodexSettingsReview,
  CodexSettingsShortcuts,
  CodexSettingsSkills,
  CodexSettingsVoice,
  CodexSettingsWorktrees,
  CodexSidebar,
} from "@/icons";
import { useConversations } from "@/lib/conversations";
import { closeSearchDialog, useSearchDialog } from "./use-search-dialog";
import { toggleSidebar } from "./use-sidebar";
import "./search-dialog.css";

/**
 * 搜索对话层（⇧ 命令面板）。
 *
 * ⚠️ 数值口径：SPEC §13/§15 明确「command palette（Ctrl+K / Ctrl+\`/\`）未实测」，
 * 所以这里的**结构**照 dsh-codex-ui 的 CodexSidebar 搜索层（scrim + 顶置 dialog +
 * 分组结果 + 键盘导航），**尺寸不是参考端实测值**，属于「官方缺测 → 用可复用的
 * 社区实现兜底」。等参考端补测后替换 .codex-search-dialog 的几何即可，组件契约不变。
 *
 *  - scrim：color-mix(in srgb, #000 48%, transparent)，140ms 淡入
 *  - dialog：水平居中、top 72px、width min(560px, 100%)、radius 16px、padding 10px
 *  - 结果按 会话 / 设置 / 操作 三类分组，取前 12 条
 *  - 键盘：Esc 关闭、↑↓ 移动、Enter 执行；点 scrim 空白处关闭
 */

interface SearchEntry {
  id: string;
  label: string;
  hint?: string;
  group: "会话" | "设置" | "操作";
  icon: (props: CodexIconProps) => React.ReactElement;
  run: () => void;
}

interface SettingsEntry {
  id: string;
  label: string;
  icon: (props: CodexIconProps) => React.ReactElement;
}

/** 设置分节（名称取自 evidence/assets/runtime-icon-names.json 里参考端设置导航的实测条目） */
const SETTINGS_SECTIONS: SettingsEntry[] = [
  { id: "import", label: "导入", icon: CodexSettingsImport },
  { id: "appearance", label: "外观", icon: CodexSettingsAppearance },
  { id: "voice", label: "语音", icon: CodexSettingsVoice },
  { id: "config", label: "配置", icon: CodexSettingsConfig },
  { id: "personalization", label: "个性化", icon: CodexSettingsPersonalization },
  { id: "shortcuts", label: "键盘快捷键", icon: CodexSettingsShortcuts },
  { id: "plugins", label: "插件", icon: CodexSettingsPlugins },
  { id: "skills", label: "技能", icon: CodexSettingsSkills },
  { id: "hooks", label: "钩子", icon: CodexSettingsHooks },
  { id: "connections", label: "连接", icon: CodexSettingsConnections },
  { id: "review", label: "代码审查", icon: CodexSettingsReview },
  { id: "git", label: "Git", icon: CodexSettingsGit },
  { id: "environment", label: "环境", icon: CodexSettingsEnvironment },
  { id: "worktrees", label: "Worktrees", icon: CodexSettingsWorktrees },
];

export function SearchDialog() {
  const open = useSearchDialog();
  const navigate = useNavigate();
  const conversations = useConversations();
  const [query, setQuery] = useState("");
  const [activeIndex, setActiveIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement | null>(null);
  /** 对话框根：焦点锁要在它内部循环（行为测试 kb.dialog.tab-focus-trap 报过「第 13 次 Tab 逃出」）。 */
  const dialogRef = useRef<HTMLDivElement | null>(null);
  /** 打开前的焦点位置，关闭时归还 —— 官方模态的语义是「Esc 后焦点回到触发者」。 */
  const restoreRef = useRef<HTMLElement | null>(null);
  const deferredQuery = useDeferredValue(query);

  useEffect(() => {
    if (!open) {
      setQuery("");
      setActiveIndex(0);
      return;
    }
    // 打开前记下是谁打开的这一层，关闭时还回去
    restoreRef.current = document.activeElement as HTMLElement | null;
    // 打开后把焦点交给输入框（首帧之后再聚焦，避免 scrim 动画抢焦）
    const raf = window.requestAnimationFrame(() => inputRef.current?.focus());
    return () => window.cancelAnimationFrame(raf);
  }, [open]);

  /** 统一的关闭入口：先关，再把焦点还给触发者（否则焦点落到 body，键盘用户会丢失位置）。 */
  const close = () => {
    closeSearchDialog();
    const target = restoreRef.current;
    // 触发者可能已经不在文档里（例如路由切换后），聚焦前先确认
    if (target != null && document.contains(target)) target.focus();
  };

  const entries = useMemo<SearchEntry[]>(() => {
    const q = deferredQuery.trim().toLowerCase();
    const match = (text: string) => (q ? text.toLowerCase().includes(q) : true);

    const sessions: SearchEntry[] = conversations
      .filter((c) => match(c.title))
      .map((c) => ({
        id: `session-${c.id}`,
        label: c.title,
        hint: "会话",
        group: "会话" as const,
        icon: CodexChatBubble,
        run: () => navigate(`/c/${c.id}`),
      }));

    const settings: SearchEntry[] = SETTINGS_SECTIONS.filter((s) => match(s.label)).map((s) => ({
      id: `setting-${s.id}`,
      label: s.label,
      hint: "设置",
      group: "设置" as const,
      icon: s.icon,
      run: () => navigate(`/settings/${s.id}`),
    }));

    const actions: SearchEntry[] = [
      {
        id: "action-new-chat",
        label: "新聊天",
        hint: "Ctrl+N",
        group: "操作" as const,
        icon: CodexNewChat,
        run: () => navigate("/new"),
      },
      {
        id: "action-settings",
        label: "打开设置",
        hint: "Ctrl+,",
        group: "操作" as const,
        icon: CodexGear,
        run: () => navigate("/settings/general"),
      },
      {
        id: "action-sidebar",
        label: "显示/隐藏侧边栏",
        hint: "Ctrl+Shift+S",
        group: "操作" as const,
        icon: CodexSidebar,
        run: toggleSidebar,
      },
      {
        id: "action-shortcuts",
        label: "显示键盘快捷键",
        hint: "Ctrl+/",
        group: "操作" as const,
        icon: CodexKeyboard,
        run: () => {},
      },
      {
        id: "action-new-window",
        label: "新建窗口",
        group: "操作" as const,
        icon: CodexPlus,
        run: () => window.dispatchEvent(new CustomEvent("codex:new-window")),
      },
    ].filter((a) => match(a.label));

    return [...sessions, ...settings, ...actions].slice(0, 12);
  }, [conversations, deferredQuery, navigate]);

  if (!open) return null;

  // 结果集变化时高亮自动夹回范围内（不需要额外的复位 effect）
  const activeEntryIndex = entries.length ? Math.min(activeIndex, entries.length - 1) : 0;

  const runEntry = (entry: SearchEntry) => {
    entry.run();
    closeSearchDialog();
  };

  const onKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape") {
      event.preventDefault();
      close();
      return;
    }
    if (event.key === "Tab") {
      // 焦点锁：`aria-modal="true"` 必须名副其实 —— 否则 Tab 会跑到浮层背后的页面上。
      // 语义与官方模态一致（SPEC-OVERLAYS 的 bundle 原文）：Shift+Tab 在首元素回卷到末位，
      // Tab 在末位回卷到首位；焦点若已跑到容器外（比如刚打开时），先拉回首位。
      const root = dialogRef.current;
      if (root == null) return;
      const focusables = Array.from(
        root.querySelectorAll<HTMLElement>(
          'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
        ),
      ).filter((el) => el.offsetParent !== null || el === document.activeElement);
      if (focusables.length === 0) return;
      const first = focusables[0];
      const last = focusables[focusables.length - 1];
      const active = document.activeElement as HTMLElement | null;
      const inside = active != null && root.contains(active);
      if (event.shiftKey && (!inside || active === first)) {
        event.preventDefault();
        last.focus();
        return;
      }
      if (!event.shiftKey && (!inside || active === last)) {
        event.preventDefault();
        first.focus();
        return;
      }
      return;
    }
    if (event.key === "ArrowDown") {
      event.preventDefault();
      setActiveIndex((i) => (entries.length ? (i + 1) % entries.length : 0));
      return;
    }
    if (event.key === "ArrowUp") {
      event.preventDefault();
      setActiveIndex((i) => (entries.length ? (i - 1 + entries.length) % entries.length : 0));
      return;
    }
    if (event.key === "Enter") {
      event.preventDefault();
      const entry = entries[activeEntryIndex];
      if (entry) runEntry(entry);
    }
  };

  let renderedGroup = "";

  return (
    <div
      className="codex-search-scrim"
      onClick={(event) => {
        if (event.target === event.currentTarget) close();
      }}
      role="presentation"
    >
      <div
        aria-label="搜索"
        aria-modal="true"
        className="codex-search-dialog"
        onKeyDown={onKeyDown}
        ref={dialogRef}
        role="dialog"
      >
        <div className="codex-search-dialog__field">
          <CodexSearch size={16} />
          <input
            aria-label="搜索会话、设置与操作"
            className="codex-search-dialog__input"
            onChange={(event) => {
              setQuery(event.target.value);
              setActiveIndex(0);
            }}
            placeholder="搜索会话、设置与操作"
            ref={inputRef}
            value={query}
          />
          <kbd className="codex-search-dialog__kbd">Esc</kbd>
        </div>

        <div className="codex-search-dialog__results">
          {entries.length === 0 ? (
            <div className="codex-search-dialog__empty">没有匹配结果</div>
          ) : (
            entries.map((entry, index) => {
              const Icon = entry.icon;
              const showGroup = entry.group !== renderedGroup;
              renderedGroup = entry.group;
              return (
                <div key={entry.id}>
                  {showGroup ? <div className="codex-search-dialog__group">{entry.group}</div> : null}
                  <button
                    className="codex-search-dialog__item"
                    data-active={index === activeEntryIndex}
                    onClick={() => runEntry(entry)}
                    onMouseEnter={() => setActiveIndex(index)}
                    type="button"
                  >
                    <Icon size={16} />
                    <span className="codex-search-dialog__label">{entry.label}</span>
                    {entry.hint ? <span className="codex-search-dialog__hint">{entry.hint}</span> : null}
                  </button>
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>
  );
}
