import { useMemo } from "react";

import { useArtexQuery } from "@/api/artex";
import { CodexRefresh, CodexTranslate } from "@/icons";
import { PanelPortal } from "@/shell";
import { Button } from "@/ui";

import { Badge, EmptyState, RowSkeleton } from "./parts";

/**
 * 内网页（rail「内网」，外壳路由 /intranet）—— objective ② 的第三个「外壳原生渲染」页面。
 *
 * 口径（objective ③ 的登记）：内网是 **ARTEX 独有业务面**，官方 Codex 没有对应页面，
 * 所以这一页不承诺 1:1；承诺的是「用同一套复制件与 token 拼装」——组件、字号、行高都来自官方件。
 *
 * 数据：/api/sessions（webshell 会话）与 /api/intranet/tunnels（隧道）。响应可能是数组，
 * 也可能是 { sessions } / { tunnels } 包装 —— 两种都收，取不到就如实显示空态。
 */

interface ShellSession {
  id: string;
  kind?: string;
  url?: string;
  lang?: string;
  platform?: string;
  host_asset_id?: string;
  status?: string;
  last_beat?: string;
}

interface TunnelInfo {
  id: string;
  kind?: string;
  state?: string;
  listen_host?: string;
  listen_port?: number;
  target_host?: string;
  target_port?: number;
  last_check?: string;
  error?: string;
}

/** 列表响应兼容三种形态：数组 / { items } / { <key>: [] }。 */
function toList<T>(value: unknown, key: string): T[] {
  if (Array.isArray(value)) return value as T[];
  if (value && typeof value === "object") {
    const record = value as Record<string, unknown>;
    if (Array.isArray(record[key])) return record[key] as T[];
    if (Array.isArray(record.items)) return record.items as T[];
  }
  return [];
}

export function IntranetRoute() {
  const sessionsQuery = useArtexQuery<unknown>("/api/sessions");
  const tunnelsQuery = useArtexQuery<unknown>("/api/tunnels");

  const sessions = useMemo(() => toList<ShellSession>(sessionsQuery.data, "sessions"), [sessionsQuery.data]);
  const tunnels = useMemo(() => toList<TunnelInfo>(tunnelsQuery.data, "tunnels"), [tunnelsQuery.data]);

  const loading = sessionsQuery.loading || tunnelsQuery.loading;
  const error = sessionsQuery.error ?? tunnelsQuery.error;
  const alive = sessions.filter((session) => (session.status ?? "") === "alive").length;

  return (
    <div className="cx-page cx-page--intranet">
      <div className="cx-page__toolbar">
        <span className="cx-muted">
          会话 {alive}/{sessions.length} · 隧道 {tunnels.length}
        </span>
        <div className="cx-page__toolbar-trailing">
          <Button
            aria-label="刷新内网数据"
            onClick={() => {
              sessionsQuery.reload();
              tunnelsQuery.reload();
            }}
            size="sm"
            uniform
            variant="ghost"
          >
            <CodexRefresh size={14} />
          </Button>
        </div>
      </div>

      <div className="cx-page__body">
        {loading ? (
          <>
            <span className="cx-muted">正在加载内网数据</span>
            <RowSkeleton rows={5} />
          </>
        ) : null}

        {!loading && error ? (
          <EmptyState
            description={"ARTEX API 返回 " + error.status + (error.message ? "：" + error.message : "") + (error.status === 401 ? "（令牌可能已失效：回到「对话」页会自动续期）" : "")}
            icon={CodexTranslate}
            layout="center"
            title="内网数据加载失败"
            actions={
              <Button onClick={() => { sessionsQuery.reload(); tunnelsQuery.reload(); }} size="sm" variant="surface">
                重试
              </Button>
            }
          />
        ) : null}

        {!loading && !error ? (
          <span className="cx-muted">
            会话与隧道列表在左侧面板；内网是 ARTEX 独有业务面，用同一套复制件拼装（不承诺 1:1）。
          </span>
        ) : null}

        <PanelPortal>
          {loading ? (
            <section className="cx-page__section">
              <h2 className="cx-page__section-title">内网</h2>
              <RowSkeleton rows={4} />
            </section>
          ) : (
          <>
            <section className="cx-page__section">
              <h2 className="cx-page__section-title">
                会话
                <span className="cx-page__section-count">{sessions.length}</span>
              </h2>
              {sessions.length === 0 ? (
                <p className="cx-muted">暂无会话</p>
              ) : (
                <ul className="cx-page__list">
                  {sessions.map((session) => (
                    <li className="cx-row-wrap" key={"s:" + session.id}>
                      <div className="cx-row">
                        <span className="cx-row__main">
                          <span className="cx-row__t">{session.url || session.host_asset_id || session.id}</span>
                          <span className="cx-row__s">{[session.kind, session.platform, session.lang].filter(Boolean).join(" · ")}</span>
                        </span>
                        <Badge tone={(session.status ?? "") === "alive" ? undefined : "muted"}>
                          {(session.status ?? "") === "alive" ? "在线" : session.status || "未知"}
                        </Badge>
                      </div>
                    </li>
                  ))}
                </ul>
              )}
            </section>

            <section className="cx-page__section">
              <h2 className="cx-page__section-title">
                隧道
                <span className="cx-page__section-count">{tunnels.length}</span>
              </h2>
              {tunnels.length === 0 ? (
                <p className="cx-muted">暂无隧道</p>
              ) : (
                <ul className="cx-page__list">
                  {tunnels.map((tunnel) => (
                    <li className="cx-row-wrap" key={"t:" + tunnel.id}>
                      <div className="cx-row">
                        <span className="cx-row__main">
                          <span className="cx-row__t">
                            {tunnel.listen_host || "0.0.0.0"}:{tunnel.listen_port ?? ""}
                            {tunnel.target_host ? " → " + tunnel.target_host + (tunnel.target_port ? ":" + tunnel.target_port : "") : ""}
                          </span>
                          <span className="cx-row__s">{tunnel.kind || "隧道"}</span>
                        </span>
                        <Badge tone={(tunnel.state ?? "") === "error" ? "danger" : "muted"}>
                          {tunnel.state || "未知"}
                        </Badge>
                      </div>
                    </li>
                  ))}
                </ul>
              )}
            </section>
          </>
          )}
        </PanelPortal>
      </div>
    </div>
  );
}
