import { useEffect, useMemo, useRef, useState } from "react";
import { useParams } from "react-router-dom";

import { CodexEllipsis, CodexNewTab, CodexRows, CodexScrollToBottom } from "@/icons";
import { findConversation, listMessages } from "@/lib/conversations";
import { formatTurnDivider } from "@/lib/format";
import type { Message as MessageModel } from "@/lib/types";
import { desktop } from "@/shell/desktop-bridge";
import { WorkspaceHeader } from "@/shell/WorkspaceHeader";
import { ArtifactPanel } from "./ArtifactPanel";
import { Composer } from "./Composer";
import { Message } from "./Message";
// 会话页与首页共用同一个模块级运行时单例：从首页发出第一条 -> 这里已经有流在跑，
// 路由切换不会断流、不丢字（见 src/chat/runtime/README.md）。
import { deriveTitle, useConversationRuntime, useRuntimeConversations } from "./runtime";
import { ChatSkeleton } from "./Skeleton";
import { useComposerSelection } from "./use-chat";
import "./chat.css";

/**
 * 会话态（/c/:conversationId）。
 *
 * 实测（captures/blocks-conversation.json，@1280×816）：
 *   thread-scroll-container  [·,96 935×716]  padding **`32px 0 0`**  overflow-y auto
 *   转录列                   [·,128 **768**×684]  padding **`0 16px 32px`**
 *   消息列表                 [286,128 736×136]  gap **12px**
 *   聊天标题栏               高 **52px**，右侧动作图标（28×28）
 *   输入区浮层               [**186.33**,698 **935.33**×**114**]  bg **rgb(24,24,24)**  padding-bottom **16px**
 *                            （114 = 98 输入面板 + 16；x 随 contentShift 左移 154 = 340.67−154，
 *                              实测出处 blocks-conversation block[46] 与同一段官方 JSX 的 `style: {x: contentX}`）
 *   顶部渐隐                 见 .cx-thread__fade
 *   底部渐隐                 [**196.67**,780 **915.33**×**32**]  sticky bottom-0  pointer-events none
 *                            （宽 915.33 = 935.33 − 2×10：官方滚动容器 electron 档
 *                              `scrollbar-gutter: stable_both-edges` 两侧各扣一条 10px）
 *   右侧浮层                 [968,104 **308×700**]（ArtifactPanel.tsx）
 *
 * ⚠️ 转录列的 x：采集时会话右侧就是那张 [968,104 308×700] 浮层，参考端量到列 x = **270.33**。
 *    机制（不是把列挤窄，也不是把主表面挤窄）：浮层是**绝对定位的覆盖层**，主表面
 *    （_MainContentViewport）始终 935.33；打开浮层时整层内容按官方 contentShift
 *    **左移 154px**（= -(308 + 300 - 300)/2，见 chat.css 里 --cx-content-shift 的注释与出处），
 *    768 的列就在“主表面减去浮层”的剩余区（340.67..968）里居中 → 中心 654.33 ✓。
 *    ★ **默认态 = 关**（Lead 裁决 C，2026-10-11）。上面 270.33 那一态是**有人打开浮层后**的取值：
 *    官方 blocks-conversation.json 的 capture 就是这么采的；而官方**渲染成品**
 *    reference-shots/ref-08-conversation.png（普通会话视图）里**没有浮层**，转录列
 *    [424,128 768×684]、composer [440,698]，居中且**不裁**。
 *    ⇒ 官方默认 = 关（若默认是开，ref-08 不可能不长浮层）；旧的 `useState(true)` 是偏差。
 *    新会话现在渲染成 ref-08 那一态：位移 0，列回落到整幅主表面内居中。
 *    **只有用户主动点 header 的「打开产物面板」**才进入上面 270.33 那一态
 *    （contentShift 左移 154 ⇒ 列 270.33 / 回底钮 638.33，与 capture 逐值一致，**不得改动**）。
 *    用户报告「没收起的时候对话页面收得很少，会被挡住」就是默认开着浮层时列被 overflow-x:hidden
 *    左裁 70.33px 造成的；默认关掉后该症状只在用户主动开面板时出现（那一态与官方 capture 一致）。
 */
interface Turn {
  id: string;
  startedAt: string;
  messages: MessageModel[];
}

/** 按「用户消息开启一轮」切分，用于日期分隔标题 */
function toTurns(messages: MessageModel[]): Turn[] {
  const turns: Turn[] = [];
  for (const message of messages) {
    const current = turns[turns.length - 1];
    if (!current || message.role === "user") {
      turns.push({ id: `turn-${message.id}`, startedAt: message.createdAt, messages: [message] });
    } else {
      current.messages.push(message);
    }
  }
  return turns;
}

export function ConversationRoute() {
  const { conversationId } = useParams();
  const conversation = findConversation(conversationId);
  /**
   * 样例会话的初始消息。
   *
   * ★ 为什么必须有（本轮实测修掉的回归）：运行时只从 localStorage 读消息；读不到就**只**用
   *   `options.initialMessages` 垫底（runtime.ts:192-206「先读持久化，读不到再用调用方给的样例消息」）。
   *   这里原来没传，于是 `/c/c1` 实测 `msgCount = 0`、正文只剩
   *   「这个会话还没有消息。在下面输入框里说点什么。」——而参考端同一个会话**有**两轮消息
   *   （blocks-conversation.json 的 `_transcriptContent_` 768×684、用户气泡 962,180 60×42.75、
   *   「已思考」折叠行、read_file 工具卡），审计 #58/#64/#65 全部是按有消息的那一屏量的。
   *   出处：src/chat/runtime/README.md:61 `initialMessages, // 例如 @/lib 的 useMessages(conversationId)`
   *        + src/chat/runtime/index.ts:10 「想让样例会话先显示内容：给 options.initialMessages」。
   * ⚠️ 持久化优先级不变：本地发过消息的会话仍以 localStorage 为准（runtime 里 stored 优先）。
   */
  const initialMessages = useMemo(() => listMessages(conversationId), [conversationId]);
  const { messages, retry, send, status, stop } = useConversationRuntime(conversationId, { initialMessages });
  // 运行时会话（我们自己发出来的）**不在** @/lib 的 mock 数据源里：只查 findConversation 的话，
  // 每个真会话的 header 标题都永远是「新聊天」（实测 /c/conv-mv29mrd5-71ls52 就是这样，
  // 侧栏「最近」里也看不到它）。这里补一条 runtime 索引，标题规则直接用 store 的 deriveTitle，
  // 与侧栏列表同源，不另造一套截断口径。
  const runtimeRecord = useRuntimeConversations().find((item) => item.id === conversationId);
  const selection = useComposerSelection();
  // 默认关（Lead 裁决 C，理由见文件头 ★）：新会话 = 官方 ref-08 那一态，不裁；
  // 用户主动点 header 的分栏钮才打开（打开后与官方 blocks-conversation capture 逐值一致）。
  const [artifactOpen, setArtifactOpen] = useState(false);
  const [pinnedToBottom, setPinnedToBottom] = useState(true);
  const [scrolled, setScrolled] = useState(false);
  const scrollRef = useRef<HTMLDivElement | null>(null);

  const turns = useMemo(() => toTurns(messages), [messages]);
  const firstUserText = messages.find((message) => message.role === "user")?.content ?? "";
  const title =
    conversation?.title ?? runtimeRecord?.title ?? (firstUserText ? deriveTitle(firstUserText) : "新聊天");
  /** 会话 id 存在但数据还没到（接后端后这一段就是真的 loading 态） */
  // ⚠️ 第三个条件不能省：isLoading 原本只表示「在 mock 数据源里查不到这个会话」，
  // 但从首页新建的运行时会话**本来就不在 mock 里** —— 于是消息已经流式返回了，
  // 页面却一直卡在骨架屏（实测 /c/conv-xxx 的 msgNodes = 0、正文只有「正在加载会话…」）。
  const isLoading = Boolean(conversationId) && !conversation && messages.length === 0;

  // 新消息进入 / 流式增量时贴底（只有本来就贴底才跟随，避免抢用户滚动）
  const lastMessage = messages[messages.length - 1];
  useEffect(() => {
    if (!pinnedToBottom || !lastMessage) return;
    const node = scrollRef.current;
    if (node) node.scrollTop = node.scrollHeight;
  }, [lastMessage, pinnedToBottom]);

  const scrollToBottom = () => {
    setPinnedToBottom(true);
    const node = scrollRef.current;
    if (node) node.scrollTop = node.scrollHeight;
  };

  return (
    <>
      <WorkspaceHeader
        /* 右侧三个控件，左→右：···（会话选项）/ 分栏（产物面板）/ ⊞（新建窗口）。
           顺序出处：Lead 逐像素比对 reference-shots/ref-08-conversation.png
           （从右到左依次是 ⊞、分栏、···）；尺寸与间距沿用 .codex-icon-button 的
           28×28 / r 12.5px / gap 6px（SPEC §3 工作区 header 右侧动作组口径）。 */
        actions={
          <>
            <button aria-label="会话选项" className="codex-icon-button" type="button">
              <CodexEllipsis size={16} />
            </button>
            <button
              aria-label="打开产物面板"
              aria-pressed={artifactOpen}
              className="codex-icon-button"
              onClick={() => setArtifactOpen((open) => !open)}
              type="button"
            >
              <CodexRows size={16} />
            </button>
            <button
              aria-label="新建窗口"
              className="codex-icon-button"
              onClick={() => desktop.newWindow()}
              type="button"
            >
              <CodexNewTab size={16} />
            </button>
          </>
        }
        title={title}
      />
      <div className="cx-conversation" data-artifact={artifactOpen ? "open" : "closed"}>
        <div className="cx-conversation__main">
          <div
            className="cx-thread"
            onScroll={(event) => {
              const el = event.currentTarget;
              setPinnedToBottom(el.scrollHeight - el.scrollTop - el.clientHeight < 24);
              setScrolled(el.scrollTop > 0);
            }}
            ref={scrollRef}
          >
            {/* ── 转录包装层（官方 blocks-conversation.json **block[14]**；JS 出处
                thread-scroll-layout-fb0c6ee4cde8.js **byte 19354**，挂它的 `p.div` 带
                `style: Xt` = 官方 contentShift 的施加点）────────────────────────────
                官方 cls 原文：`[container-type:inline-size] flex min-h-full shrink-0 flex-col
                justify-start overflow-x-clip [container-name:thread-content]`，
                rect [196.667,128 **915.333**×684]（面板开态；未位移时 x = 350.667 = 滚动容器内容盒左边界）。
                它是滚动容器 thread-scroll-container 的子节点，自己 childCount=3：
                  ① div.relative.flex.flex-1.shrink-0.flex-col._transcriptContent_…（block[15]，
                     768×684 = 本工程的 .cx-thread__content）；
                  ② div.pointer-events-none.sticky.bottom-0.z-10.mt-auto.w-full.shrink-0（= 本工程的
                     .cx-thread__end-fade-anchor；官方**没有单独采集它** —— path 由 block[45] 证明其存在，
                     完整类串在 JS byte 20036，见下面锚的注释）；
                  ③ 第三个子节点**未被采集 / 未识别**（只知 childCount=3，不编造）。
                ⚠️ 底部渐隐必须挂在本层**内部**。官方 block[45] 的 path 逐字为：
                  …div.thread-scroll-container.overflow-x-hidden.overflow-y-auto
                    > div.[container-type:inline-size].flex.min-h-full
                      > div.pointer-events-none.sticky.bottom-0
                        > div.pointer-events-none.absolute.inset-x-0
                改前本工程把 fade 挂成 **.cx-thread（滚动容器）的直接子节点** ⇒ sticky 的包含块
                只有一屏高（实测长转录下 .cx-thread__content 恒 **684**，fade 的 y 恒 = 780 − scrollTop：
                scrollH 9806 / scrollTop 9090 时 y = **−8310**）⇒ 一滚就跟着内容滚走、底部渐隐消失。
                挪进本层后包含块随内容长到整个 scrollHeight（官方 `shrink-0` 正是不让它被压回一屏），
                fade 在 scrollTop=0 与 max 两态都贴底 **780**。改前/改后/官方三方真值表见
                chat.css 的 .cx-thread__content-wrap 一节。 */}
            <div className="cx-thread__content-wrap">
              <div className="cx-thread__content">
                <div className="cx-messages">
                  {isLoading ? (
                    <ChatSkeleton />
                  ) : messages.length === 0 ? (
                    <p className="cx-thread__empty">这个会话还没有消息。在下面输入框里说点什么。</p>
                  ) : (
                    turns.map((turn) => {
                      const parts = formatTurnDivider(turn.startedAt).split(" ");
                      const time = parts.pop() ?? "";
                      const day = parts.join(" ");
                      return (
                        <div className="cx-turn" key={turn.id}>
                          <div className="cx-divider">
                            <time className="cx-divider__text">
                              <span className="cx-divider__day">{day}</span> {time}
                            </time>
                          </div>
                          {turn.messages.map((message) => (
                            <Message key={message.id} message={message} onRetry={retry} />
                          ))}
                        </div>
                      );
                    })
                  )}
                </div>
              </div>
              {/* sticky 锚 —— 官方 `div` 的 classList 逐字为
                  `pointer-events-none sticky bottom-0 z-10 mt-auto w-full shrink-0`
                  （thread-scroll-layout-fb0c6ee4cde8.js **byte 20036**，高度是
                  `h-[calc(var(--thread-scroll-padding-bottom)-var(--spacing)*4)]`）；
                  它的 children 就是 `jsx(me,{part:"fade"})`（同一段 JSX 紧随其后）。
                  采集帧实测高 **0**：block[45] y=780 + `-top-8` ⇒ 锚顶 812，
                  block[14] 的 684 高内容盒底边也是 812 ⇒ 锚底 812 ⇒ 高 0。
                  高 0 ⇒ 不占转录列高度 ⇒ 短转录下 .cx-thread__content 仍是 684
                  （未滚动态几何与改前逐值相同）。 */}
              <div className="cx-thread__end-fade-anchor">
              {/* 底部渐隐：官方 [196.667,780 915.333×32]（blocks-conversation block[45]）。
                  宽度 = 滚动容器内容盒（935.333 − 两侧各 10px gutter）；x 随 contentShift 左移 154。
                  ⚠️ gutter **不再是变量**：原 --cx-thread-scrollbar-gutter 已删（2026-10-11 HUNT 组实测更正）。
                     原注释记「本机是 overlay 滚动条 ⇒ 只写 scrollbar-gutter 复现不出 20px」**已被推翻**：
                     规范探针实测 overflow:scroll 的 offsetWidth−clientWidth = 10 ⇒ 不是 overlay；当时那个容器
                     **没有溢出**，没有滚动条，差 0 什么也证明不了。
                     现由 .cx-thread 上的 scrollbar-gutter: stable both-edges 真实占位（见 chat.css 该规则）。 */}
              <div aria-hidden className="cx-thread__end-fade" />
              </div>
            </div>
          </div>

          <div className="cx-conversation__composer">
            {/* 回到底部浮钮（#69）：容器 = 转录列（768，padding 0 16px），
                浮钮 end-1/2 + translate-x-1/2 → **水平居中于转录列**。
                实测印证：参考端 638.333,642 32×32，中心 654.33 = 输入行中心（286.333 + 368）。
                纵向 bottom: calc(100% + 24px)（官方 bottom-[calc(100%+6*var(--spacing))]）
                → 底边 = 输入区顶 698 − 24 = 674，顶边 642 ✓
                参考端始终在 DOM 里（opacity 0 + pointer-events-none 表示隐藏），这里同构。 */}
            <div className="cx-thread__to-bottom-anchor">
              <button
                aria-label="滚动到底部"
                className="cx-thread__to-bottom"
                data-visible={!pinnedToBottom}
                onClick={scrollToBottom}
                type="button"
              >
                <CodexScrollToBottom size={20} />
              </button>
            </div>
            <div className="cx-thread__column">
              <Composer
                mode="conversation"
                onSend={send}
                onStop={stop}
                selection={selection}
                status={status}
              />
            </div>
          </div>
        </div>

        {artifactOpen ? <ArtifactPanel conversation={conversation} /> : null}

        {/* 顶部渐隐（#70）：官方 _MainContentTopFade_yl8z4_2 340.67,**96** 935.33×**40**
            绝对定位挂在**主内容面**上（不是滚动容器内，也不是转录列里）→ 宽度 = 整幅主表面。
            opacity 0 → 1 由「是否已滚动」驱动（官方 transition: opacity .15s）。 */}
        <div aria-hidden className="cx-thread__fade" data-visible={scrolled} />
      </div>
    </>
  );
}
