import { useSyncExternalStore } from "react";

/**
 * 搜索对话层（Ctrl+/ 或面板头的放大镜）的开关状态。
 *
 * 与 use-sidebar.ts 同一套模块级外部 store 写法：任何地方都能开，
 * 不需要 Provider；SearchDialog 挂在 AppShell 上。
 */

type Listener = () => void;

const listeners = new Set<Listener>();
let open = false;

function subscribe(listener: Listener) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function emit() {
  for (const l of listeners) l();
}

export function openSearchDialog() {
  if (open) return;
  open = true;
  emit();
}

export function closeSearchDialog() {
  if (!open) return;
  open = false;
  emit();
}

export function toggleSearchDialog() {
  open = !open;
  emit();
}

const getSnapshot = () => open;

export function useSearchDialog() {
  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

/**
 * 全局快捷键。
 *
 * ⚠️ 这里**曾经绑的是 Ctrl+/，那是错的**，会造成一次按键两个动作：
 * `src/settings/shortcuts.ts` 里按 SPEC §5 也注册了 Ctrl+/（官方「帮助 → 显示键盘快捷键」的键位），
 * 于是焦点在非可编辑区时，**搜索层被打开的同时页面还跳到了 /settings/shortcuts**
 * （行为测试 kb.shortcut.ctrl-slash-focus-consistency 复现）。
 *
 * 官方的分工是（docs/SPEC-OVERLAYS.md）：
 *   openCommandMenu  = CmdOrCtrl+K 与 CmdOrCtrl+Shift+P   → 命令面板
 *   showKeyboardShortcuts = CmdOrCtrl+/                    → 键盘快捷键
 * 所以搜索层改用官方的命令面板键位，把 Ctrl+/ 完整让给「显示键盘快捷键」。
 */
if (typeof window !== "undefined") {
  window.addEventListener("keydown", (event) => {
    const mod = event.ctrlKey || event.metaKey;
    if (!mod) return;
    const key = event.key.toLowerCase();
    // 官方两条键位：Ctrl+K 与 Ctrl+Shift+P
    const isCommandMenu = key === "k" || (event.shiftKey && key === "p");
    if (isCommandMenu) {
      event.preventDefault();
      toggleSearchDialog();
    }
  });
}
