import { useState } from "react";

import { Button } from "@/ui";
import type { SettingsPaneProps } from "./index";
import {
  PaneCard,
  PaneConfirmAction,
  PaneEmpty,
  PaneInputRow,
  PaneRow,
  PaneSection,
  PaneShell,
  PaneSwitch,
  PaneTabs,
  PaneValueText,
} from "./pane-kit";
import { newPaneId, usePaneState } from "./pane-state";

/**
 * Worktrees（官方 slug worktrees，chunk worktrees-settings-page-578b3b6d9fdf.js，47 条）。
 *
 * 页内 tabs：General / Environments（settings.worktrees.tabs，路由 /settings/worktrees 与 ?tab=environments，
 *   出处：settings-tabs-2c61d99f5303.js，SPEC §4.2.17）。
 * 行证据（官方 zh-CN）：
 *   settings.git.worktreeRoot.label / .description
 *   settings.worktrees.autoCleanup.label / .description（推荐大多数用户启用…）
 *     + .confirm.title「禁用工作树自动删除功能？」/ .confirm.confirm「禁用自动删除功能」
 *   settings.worktrees.keepCount.label / .description（保留数量；ChatGPT 会在删除工作树前创建快照）
 *   settings.worktrees.upstreamRefresh.label / .description
 *   settings.worktrees.empty.title「尚无工作树」/ .error.title「无法加载工作树」
 *   settings.worktrees.row.conversations.empty「未找到关联到此工作树的对话」/ .row.title「工作树」
 *   Environments tab 复用 settings.localEnvironments.*（见 environment.tsx）
 *
 * 此页无实测几何，按通用规格推导（SPEC §8.1）。
 */

interface WorktreeRow {
  id: string;
  branch: string;
  path: string;
  conversations: number;
  createdAt: string;
}

interface WorktreesPaneState {
  tab: string;
  worktreeRoot: string;
  autoCleanup: boolean;
  keepCount: number;
  upstreamRefresh: boolean;
  rows: WorktreeRow[];
  loadFailed: boolean;
}

const DEFAULTS: WorktreesPaneState = {
  tab: "general",
  worktreeRoot: "",
  autoCleanup: true,
  keepCount: 5,
  upstreamRefresh: true,
  rows: [],
  loadFailed: false,
};

const DEFAULT_WORKTREE_ROOT = "~/Documents/Codex/worktrees";

export function WorktreesPane({ section }: SettingsPaneProps) {
  const [state, patch, reset] = usePaneState(section, DEFAULTS);
  const [editingRoot, setEditingRoot] = useState(false);

  function createWorktree() {
    const index = state.rows.length + 1;
    patch({
      rows: [
        {
          id: newPaneId(),
          branch: `codex/worktree-${String(index)}`,
          path: `${state.worktreeRoot || DEFAULT_WORKTREE_ROOT}/worktree-${String(index)}`,
          conversations: 0,
          createdAt: "刚刚",
        },
        ...state.rows,
      ],
    });
  }

  return (
    <PaneShell
      section={section}
      title="Worktrees"
      lede="托管工作树的根目录、自动清理与上游刷新策略；Environments 页签配置每个项目的本地环境。"
      actions={
        <>
          <Button size="sm" variant="soft" color="secondary" onClick={reset}>
            恢复默认
          </Button>
          <Button size="sm" variant="soft" color="secondary" onClick={createWorktree}>
            新建工作树
          </Button>
        </>
      }
    >
      <PaneTabs
        ariaLabel="Worktrees 页签"
        value={state.tab}
        onChange={(value) => patch({ tab: value })}
        tabs={[
          { value: "general", label: "General" },
          { value: "environments", label: "Environments" },
        ]}
      />

      {state.loadFailed ? (
        <PaneSection>
          <PaneEmpty
            icon={<span aria-hidden>!</span>}
            title="无法加载工作树"
            description="读取本机工作树列表失败。重试后再看，或先检查仓库是否仍然存在。"
            action={
              <Button size="sm" variant="soft" color="secondary" onClick={() => patch({ loadFailed: false })}>
                重试
              </Button>
            }
          />
        </PaneSection>
      ) : null}

      {state.tab === "general" ? (
        <>
          <PaneSection title="托管工作树">
            <PaneCard>
              <PaneRow
                label="工作树根目录"
                description="ChatGPT 创建托管工作树的目录。留空则使用默认位置"
                control={
                  editingRoot ? (
                    <PaneValueText
                      value={`${(state.worktreeRoot || DEFAULT_WORKTREE_ROOT).slice(0, 24)}…`}
                      title={state.worktreeRoot || DEFAULT_WORKTREE_ROOT}
                      mono
                      actionLabel="完成"
                      onAction={() => setEditingRoot(false)}
                    />
                  ) : (
                    <PaneValueText
                      value={state.worktreeRoot || DEFAULT_WORKTREE_ROOT}
                      mono
                      actionLabel="更改"
                      onAction={() => setEditingRoot(true)}
                    />
                  )
                }
              />
              <PaneInputRow
                label="自动删除限制"
                description="要保留的托管工作树数量；超过后，较旧的工作树会自动被清理。ChatGPT 会在删除工作树前创建快照，因此被清理的工作树应始终可以恢复。"
                ariaLabel="自动删除限制"
                value={String(state.keepCount)}
                onChange={(value) => {
                  const parsed = Number.parseInt(value.replace(/[^0-9]/g, ""), 10);
                  patch({ keepCount: Number.isNaN(parsed) ? 0 : parsed });
                }}
                width={88}
                suffix={<span className="cx-pane__list-meta">个</span>}
              />
              <PaneRow
                label="自动删除旧工作树"
                description="推荐大多数用户启用。仅当你需要手动管理旧工作树和磁盘使用空间时，再关闭此功能。"
                control={
                  <PaneConfirmAction
                    danger
                    confirmLabel="禁用自动删除功能"
                    cancelLabel="取消"
                    title="禁用工作树自动删除功能？"
                    description="关闭后，较早的工作树不会被自动清理，需要你手动删除。"
                    onConfirm={() => patch({ autoCleanup: false })}
                    trigger={
                      <PaneSwitch
                        label="自动删除旧工作树"
                        checked={state.autoCleanup}
                        onChange={(checked) => {
                          if (checked) patch({ autoCleanup: true });
                        }}
                      />
                    }
                  />
                }
              />
              <PaneRow
                label="创建工作树前始终获取上游更新"
                description="Codex 通常会在常规 Git 操作中获取分支更新。此设置还会在创建每个新工作树前获取上游更新。"
                control={
                  <PaneSwitch
                    label="创建工作树前始终获取上游更新"
                    checked={state.upstreamRefresh}
                    onChange={(checked) => patch({ upstreamRefresh: checked })}
                  />
                }
              />
            </PaneCard>
          </PaneSection>

          <PaneSection title="工作树" description="本机托管的全部工作树（含关联对话数）">
            <PaneCard>
              {state.rows.length === 0 ? (
                <PaneEmpty
                  title="尚无工作树"
                  description="在任意对话里切换到工作树模式，或点右上角「新建工作树」后，托管的树会显示在这里。"
                  action={
                    <Button size="sm" variant="soft" color="secondary" onClick={createWorktree}>
                      新建工作树
                    </Button>
                  }
                />
              ) : (
                <div className="cx-pane__list">
                  {state.rows.map((row) => (
                    <div key={row.id} className="cx-pane__list-item">
                      <div className="cx-pane__list-main">
                        <span className="cx-pane__list-title">{row.branch}</span>
                        <span className="cx-pane__list-meta">
                          {row.path} ·{" "}
                          {row.conversations === 0
                            ? "未找到关联到此工作树的对话"
                            : `${String(row.conversations)} 个对话`}
                        </span>
                      </div>
                      <div className="cx-pane__list-actions">
                        <Button size="sm" variant="ghost" color="secondary">
                          新建聊天
                        </Button>
                        <PaneConfirmAction
                          danger
                          confirmLabel="删除"
                          title="删除此工作树？"
                          description="删除后本地目录会被移除；ChatGPT 在删除前会创建快照，通常可以恢复。"
                          onConfirm={() => patch({ rows: state.rows.filter((item) => item.id !== row.id) })}
                          trigger={
                            <Button size="sm" variant="ghost" color="danger">
                              删除
                            </Button>
                          }
                        />
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </PaneCard>
          </PaneSection>
        </>
      ) : (
        <PaneSection
          title="本地环境"
          description="Environments 页签按项目配置设置脚本与清理脚本（settings.localEnvironments.*）"
        >
          <PaneCard>
            <PaneEmpty
              title="选择项目后配置本地环境"
              description="Environments 与「环境」页共用同一份配置；这里先列出已配置的项目。"
            />
          </PaneCard>
        </PaneSection>
      )}
    </PaneShell>
  );
}
