import { Keyboard } from "lucide-react";
import { useEffect, useState } from "react";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogTrigger,
  Button,
  Kbd,
} from "@/ui";

import { SettingsBadge, SettingsButton } from "../controls";
import { SettingsCard, SettingsCardBody, SettingsRow, SettingsSection } from "../SettingsRow";
import {
  normalizeChord,
  SHORTCUT_EDIT_INSTRUCTIONS,
  SHORTCUT_GROUPS,
  SHORTCUT_RESET_ALL,
  SHORTCUT_RESTORE_DEFAULTS,
  shortcutChord,
  useChordCapture,
  useShortcutBindings,
} from "../shortcuts";

/**
 * 键盘快捷键（官方 slug keyboard-shortcuts）。
 *
 * 结构按 docs/SPEC-SETTINGS.md §4.2.8（官方 keyboard-shortcuts-settings-56e0ef891e8c.js）：
 *   3 个分区（消息输入框 / 聊天 / 应用）+ 数字快捷键 + 外链快捷键 + 工具栏（恢复默认 / 全部重置）
 *   + 编辑提示「要更改快捷键，请选中组合键，然后按下新的组合键」+ 重置确认弹窗。
 *
 * ⚠️ 口径差异（SPEC §4.2.8 末段）：官方条目按宿主能力**动态生成**，消息目录里没有行清单；
 *   本工程这 34 条来自应用菜单（SPEC §4/§5），键位是官方菜单原文。页面里已标注这一点。
 * ⚠️ 几何：SPEC **没有**实测快捷键页的任何数值（§8.1 明确列为未实测）；
 *   所以这里只沿用设置页的行/卡片骨架与 @/ui 的 Kbd，不编造官方尺寸。
 */
function ChordChip({ chord }: { chord: string }) {
  const keys = chord.includes("+") ? chord.split("+") : [chord];
  return (
    <span className="cx-settings-shortcuts__keys">
      {keys.map((key, index) => (
        <Kbd key={`${key}-${index}`}>{key}</Kbd>
      ))}
    </span>
  );
}

export function ShortcutsSection() {
  const { map, setChord, resetAll, dirty } = useShortcutBindings();
  const [recordingId, setRecordingId] = useState<string | null>(null);
  const capture = useChordCapture();

  // 逐条录制：点组合键 → 全局捕获 → 写 localStorage（Esc 取消，只按修饰键继续等）
  useEffect(() => {
    if (!recordingId) return;
    const onKeyDown = (event: KeyboardEvent) => {
      event.preventDefault();
      event.stopPropagation();
      if (event.key === "Escape") {
        setRecordingId(null);
        return;
      }
      const chord = normalizeChord(event);
      if (!chord || ["Ctrl", "Alt", "Shift", "Meta"].includes(chord)) return;
      setChord(recordingId, chord);
      setRecordingId(null);
    };
    window.addEventListener("keydown", onKeyDown, true);
    return () => window.removeEventListener("keydown", onKeyDown, true);
  }, [recordingId, setChord]);

  return (
    <>
      <SettingsSection
        tag={<SettingsBadge>行清单 = 应用菜单（SPEC §4/§5）；官方按宿主动态生成</SettingsBadge>}
        title="键盘快捷键"
      >
        <SettingsCard>
          <SettingsCardBody>
            <div className="cx-settings-shortcuts__toolbar">
              <p className="cx-settings-capture__hint">{SHORTCUT_EDIT_INSTRUCTIONS}</p>
              <div className="cx-settings-row__control">
                <SettingsButton disabled={!dirty} onClick={resetAll}>
                  {SHORTCUT_RESTORE_DEFAULTS}
                </SettingsButton>
                <AlertDialog>
                  <AlertDialogTrigger asChild>
                    <SettingsButton disabled={!dirty}>{SHORTCUT_RESET_ALL}</SettingsButton>
                  </AlertDialogTrigger>
                  <AlertDialogContent
                    description="本工程只保存键位改写（localStorage codex.settings.shortcuts）；官方文案 settings.keyboardShortcuts.resetAllConfirm.* 未解析，这里用中性文案。"
                    footer={
                      <>
                        <AlertDialogCancel asChild>
                          <Button size="sm" variant="ghost">
                            取消
                          </Button>
                        </AlertDialogCancel>
                        <AlertDialogAction asChild>
                          <Button onClick={resetAll} size="sm" variant="solid">
                            重置
                          </Button>
                        </AlertDialogAction>
                      </>
                    }
                    title="全部重置为默认值？"
                  />
                </AlertDialog>
              </div>
            </div>
          </SettingsCardBody>
        </SettingsCard>
      </SettingsSection>

      {SHORTCUT_GROUPS.map((group) => (
        <SettingsSection key={group.id} title={group.label}>
          <SettingsCard>
            {group.rows.map((row) => {
              const chord = shortcutChord(row, map);
              const recording = recordingId === row.id;
              const unmeasured = row.chord === "" && row.official;
              return (
                <SettingsRow
                  control={
                    unmeasured ? (
                      <SettingsBadge tone="warn">键位未实测</SettingsBadge>
                    ) : (
                      <button
                        aria-label={`${row.label}：${recording ? "请按下组合键" : chord || "未分配"}`}
                        className="cx-settings-chord"
                        data-hit={capture.matched?.id === row.id ? "" : undefined}
                        data-recording={recording ? "" : undefined}
                        onClick={() => setRecordingId(recording ? null : row.id)}
                        type="button"
                      >
                        {recording ? (
                          <span className="cx-settings-hotkey__hint">按下…</span>
                        ) : chord ? (
                          <ChordChip chord={chord} />
                        ) : (
                          <span className="cx-settings-hotkey__hint">未分配</span>
                        )}
                      </button>
                    )
                  }
                  description={row.note ?? `出处 ${row.source}`}
                  key={row.id}
                  label={row.label}
                />
              );
            })}
          </SettingsCard>
        </SettingsSection>
      ))}

      {/* 附加：真监听录制卡（官方这一页没有这块，是本工程的可操作附加） */}
      <SettingsSection tag={<SettingsBadge tone="warn">附加 · 官方无此块</SettingsBadge>} title="按一下试试">
        <SettingsCard>
          <SettingsCardBody>
            <div className="cx-settings-capture" data-recording={capture.recording ? "" : undefined}>
              <div>
                <div className="cx-settings-row__label">
                  {capture.recording
                    ? "请按下任意组合键…"
                    : capture.matched
                      ? `命中：${capture.matched.label}`
                      : "录制一段组合键"}
                </div>
                <div className="cx-settings-capture__hint">
                  {capture.chord
                    ? `捕获到 ${capture.chord}`
                    : "支持 Ctrl / Alt / Shift / Meta 组合，Esc 结束"}
                </div>
              </div>
              <div className="cx-settings-row__control">
                {capture.chord ? <ChordChip chord={capture.chord} /> : null}
                <Button
                  onClick={capture.recording ? capture.stop : capture.start}
                  size="sm"
                  variant={capture.recording ? "solid" : "soft"}
                >
                  <Keyboard aria-hidden size={14} />
                  {capture.recording ? "停止" : "开始录制"}
                </Button>
              </div>
            </div>
          </SettingsCardBody>
        </SettingsCard>
      </SettingsSection>
    </>
  );
}
