import { useState } from "react";

import { Button } from "@/ui";
import type { SettingsPaneProps } from "./index";
import { PaneBanner, PaneCard, PaneEmpty, PaneRow, PaneSection, PaneShell, PaneSwitch } from "./pane-kit";
import { newPaneId, usePaneState } from "./pane-state";

/**
 * 导入（官方 slug import，chunk import-settings-c0e9f89f807c.js，91 条消息；
 * 另 import-settings-gate-7fb85d759733.js + settings.agent.importSettings.* 27 条，属导入向导）。
 *
 * 元素证据（官方 zh-CN）：
 *   settings.import.attention.title「需要处理」/ .subtitle「完成之前导入项目的设置」
 *   settings.import.attention.mcps.error「无法检查导入的 MCP 服务器」/ .retry「重试」
 *   settings.import.autosync.title「自动同步」/ .label「保持导入同步」
 *     / .description「自动同步已连接来源中的新增和更新内容」
 *     / .allCategories「同步所有类别」/ .allCategoriesDescription「包括今后发现的类别」
 *     / .chatsOnly「仅聊天」/ .afterImport「首次导入后可用」
 *   settings.import.empty.label「从其他 AI 应用导入」/ .description「未找到可导入的设置」
 *   settings.import.error.label「无法检查导入项」/ .description「重试以查找兼容的设置、项目和最近聊天」
 *   settings.import.unsupportedProjects.label「{count} 个项目无法导入」
 *
 * 此页无实测几何，按通用规格推导（SPEC §8.1）。
 * 导入项本身官方无运行时证据（§8.2）→ 默认空态，点「从其他 AI 应用导入」装载演示来源。
 */

interface ImportSource {
  id: string;
  name: string;
  kind: string;
  count: number;
  done: boolean;
}

interface ImportPaneState {
  syncing: boolean;
  scope: string;
  sources: ImportSource[];
  unsupported: number;
  checking: boolean;
  checkFailed: boolean;
}

const DEFAULTS: ImportPaneState = {
  syncing: true,
  scope: "allCategories",
  sources: [],
  unsupported: 0,
  checking: false,
  checkFailed: false,
};

/** 演示来源（官方只确证页面结构与文案，不确证来源清单） */
const DEMO_SOURCES: ImportSource[] = [
  { id: "src-1", name: "Claude Desktop", kind: "MCP 服务器 · 偏好设置", count: 12, done: false },
  { id: "src-2", name: "Cursor", kind: "规则 · 最近聊天", count: 34, done: false },
];

export function ImportPane({ section }: SettingsPaneProps) {
  const [state, patch, reset] = usePaneState(section, DEFAULTS);
  const [scanning, setScanning] = useState(false);

  function scan() {
    setScanning(true);
    patch({ checking: true, checkFailed: false });
    window.setTimeout(() => {
      setScanning(false);
      patch((prev) => ({
        ...prev,
        checking: false,
        sources: prev.sources.length > 0 ? prev.sources : DEMO_SOURCES,
        unsupported: prev.unsupported === 0 ? 1 : prev.unsupported,
      }));
    }, 520);
  }

  const pending = state.sources.filter((source) => !source.done);

  return (
    <PaneShell
      section={section}
      title="导入"
      lede="把其他 AI 应用里的设置、项目与最近聊天导入 Codex；导入后可以保持来源同步。"
      actions={
        <>
          <Button size="sm" variant="soft" color="secondary" onClick={reset}>
            重置
          </Button>
          <Button size="sm" variant="soft" color="secondary" loading={scanning} onClick={scan}>
            重新检查
          </Button>
        </>
      }
    >
      {state.checkFailed ? (
        <PaneBanner
          tone="danger"
          title="无法检查导入项"
          description="重试以查找兼容的设置、项目和最近聊天"
          action={
            <Button size="sm" variant="soft" color="secondary" onClick={scan}>
              重试
            </Button>
          }
        />
      ) : null}

      <PaneSection title="自动同步">
        <PaneCard>
          <PaneRow
            label="保持导入同步"
            description="自动同步已连接来源中的新增和更新内容"
            control={
              <PaneSwitch
                label="保持导入同步"
                checked={state.syncing}
                onChange={(checked) => patch({ syncing: checked })}
                disabled={state.sources.length === 0}
              />
            }
          />
          <PaneRow
            label="同步范围"
            description={state.sources.length === 0 ? "首次导入后可用" : "包括今后发现的类别"}
            control={
              <span className="cx-pane__input-group">
                <Button
                  size="sm"
                  variant="soft"
                  color="secondary"
                  data-selected={state.scope === "allCategories" ? "" : undefined}
                  disabled={state.sources.length === 0}
                  onClick={() => patch({ scope: "allCategories" })}
                >
                  同步所有类别
                </Button>
                <Button
                  size="sm"
                  variant="soft"
                  color="secondary"
                  disabled={state.sources.length === 0}
                  onClick={() => patch({ scope: "chatsOnly" })}
                >
                  仅聊天
                </Button>
              </span>
            }
          />
        </PaneCard>
      </PaneSection>

      <PaneSection
        title="需要处理"
        description={
          state.sources.length === 0 ? "完成之前导入项目的设置" : `${String(pending.length)} 个来源等待确认`
        }
      >
        <PaneCard>
          {state.sources.length === 0 ? (
            <PaneEmpty
              title="从其他 AI 应用导入"
              description="未找到可导入的设置。选择一个来源后，Codex 会扫描它的设置、项目与最近聊天。"
              action={
                <Button size="sm" variant="soft" color="secondary" loading={scanning} onClick={scan}>
                  从其他 AI 应用导入
                </Button>
              }
            />
          ) : (
            <div className="cx-pane__list">
              {state.sources.map((source) => (
                <div key={source.id} className="cx-pane__list-item">
                  <div className="cx-pane__list-main">
                    <span className="cx-pane__list-title">{source.name}</span>
                    <span className="cx-pane__list-meta">
                      {source.kind} · {source.count} 项
                    </span>
                  </div>
                  <div className="cx-pane__list-actions">
                    <Button
                      size="sm"
                      variant="soft"
                      color="secondary"
                      onClick={() =>
                        patch((prev) => ({
                          ...prev,
                          sources: prev.sources.map((item) =>
                            item.id === source.id ? { ...item, done: !item.done } : item,
                          ),
                        }))
                      }
                    >
                      {source.done ? "撤销" : "完成设置"}
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      color="danger"
                      onClick={() =>
                        patch((prev) => ({
                          ...prev,
                          sources: prev.sources.filter((item) => item.id !== source.id),
                        }))
                      }
                    >
                      忽略
                    </Button>
                  </div>
                </div>
              ))}
              <PaneBanner
                tone="warning"
                title={`${String(state.unsupported)} 个项目无法导入`}
                description="这些项目使用了不受支持的项目配置，可以手动复制后继续。"
                action={
                  <Button
                    size="sm"
                    variant="ghost"
                    color="secondary"
                    onClick={() => patch({ unsupported: 0 })}
                  >
                    已了解
                  </Button>
                }
              />
              <PaneBanner
                tone="info"
                title="无法检查导入的 MCP 服务器"
                description="来源应用未在运行，MCP 服务器列表可能不完整。"
                action={
                  <Button
                    size="sm"
                    variant="soft"
                    color="secondary"
                    onClick={() => patch({ unsupported: 1 })}
                  >
                    重试
                  </Button>
                }
              />
            </div>
          )}
        </PaneCard>
      </PaneSection>

      <PaneSection title="项目">
        <PaneCard>
          <PaneRow
            label="导入项目"
            description="把来源应用里的项目登记到 Codex（导入后仍可在项目设置里调整路径）"
            control={
              <Button
                size="sm"
                variant="soft"
                color="secondary"
                onClick={() =>
                  patch((prev) => ({
                    ...prev,
                    sources: [
                      ...prev.sources,
                      {
                        id: newPaneId(),
                        name: `本地项目 ${String(prev.sources.length + 1)}`,
                        kind: "项目 · 工作目录",
                        count: 1,
                        done: false,
                      },
                    ],
                  }))
                }
              >
                添加项目
              </Button>
            }
          />
        </PaneCard>
      </PaneSection>
    </PaneShell>
  );
}
