export interface RailItem {
  id: string;
  label: string;
  /** 目的地；`menu: true` 的条目（如「探索」）是**菜单**、没有目的地 ⇒ 可选（task-40） */
  to?: string;
  /** 常态图标 */
  icon: ComponentType<CodexIconProps>;
  /** 选中态图标（官方为填充变体，如 CodexRailHomeActive） */
  iconActive?: ComponentType<CodexIconProps>;
  /** true = 该条不是跳转，而是开一个 popover 菜单（官方「探索」） */
  menu?: boolean;
}

/** 一定带目的地的条目（探索菜单里的条目）：给消费者一个不需要再判空的具体类型 */
export type RailMenuItem = RailItem & { to: string };

