import { useState } from "react";

import { Button, Input } from "@/ui";
import type { SettingsPaneProps } from "./index";
import {
  PaneCard,
  PaneConfirmAction,
  PaneEmpty,
  PaneInputRow,
  PaneRow,
  PaneSection,
  PaneSelect,
  PaneShell,
  PaneSwitch,
  PaneTextBlock,
  PaneValueText,
} from "./pane-kit";
import { usePaneState } from "./pane-state";

/**
 * Git（官方 slug git-settings，chunk git-settings-ddaef1de04c4.js，55 条消息）。
 *
 * 行证据（官方 zh-CN 语言包，id 逐条对齐；SPEC §4.2.15）：
 *   settings.git.worktreeRoot.label / .description「ChatGPT 创建托管工作树的目录。留空则使用默认位置」
 *   settings.git.branchPrefix.label / .description「ChatGPT 创建新分支时使用的前缀」/ .placeholder「codex/」
 *   settings.git.commitInstructions.label / .description / .placeholder「添加提交信息指引…」
 *   settings.git.prInstructions.label / .description / .placeholder「添加 Pull Request 指引…」
 *   settings.git.pullRequestMergeMethod.label / .description（取值：合并 / 压缩合并）
 *   settings.git.createDraftPullRequest.label / .description
 *   settings.git.forcePush.label / .description「从 ChatGPT 推送时使用 --force-with-lease」
 *   settings.git.reviewMode.label / .description
 *   settings.git.pullRequestWatch.title / .autoMerge.label / .autoMerge.description / .instructions.placeholder
 *   settings.general.reviewDelivery.label / .description
 *
 * 此页无实测几何，按通用规格推导（SPEC §8.1）：卡片 bg rgb(35,35,35) / 圆角 20px / 发丝线；
 * 行 padding 12px 16px；标签 13/500；说明 12/430/65%。
 * 控件当前值官方无运行时证据（§8.2）→ 默认值按文案语义取第一项，持久化在 cx.pane.git。
 */

interface GitPaneState {
  worktreeRoot: string;
  branchPrefix: string;
  commitInstructions: string;
  prInstructions: string;
  mergeMethod: string;
  draftPr: boolean;
  forcePush: boolean;
  disableGitDiff: boolean;
  watchPr: boolean;
  autoMerge: boolean;
  watchInstructions: string;
  reviewDelivery: string;
}

const DEFAULTS: GitPaneState = {
  worktreeRoot: "",
  branchPrefix: "",
  commitInstructions: "",
  prInstructions: "",
  mergeMethod: "merge",
  draftPr: false,
  forcePush: false,
  disableGitDiff: false,
  watchPr: false,
  autoMerge: true,
  watchInstructions: "",
  reviewDelivery: "inline",
};

const MERGE_METHODS = [
  { value: "merge", label: "合并" },
  { value: "squash", label: "压缩合并", description: "把 PR 的所有提交压缩成一个提交" },
];

const REVIEW_DELIVERY = [
  { value: "inline", label: "内联", description: "在当前聊天中启动 /review" },
  { value: "separate", label: "单独", description: "启动单独的审查聊天" },
];

/** 官方只说「留空用默认位置」，未给具体路径（未实测）→ 这里只是占位展示 */
const DEFAULT_WORKTREE_ROOT = "~/Documents/Codex/worktrees";

export function GitPane({ section }: SettingsPaneProps) {
  const [state, patch, reset] = usePaneState(section, DEFAULTS);
  const [editingRoot, setEditingRoot] = useState(false);

  return (
    <PaneShell
      section={section}
      title="Git"
      lede="分支、提交与 Pull Request 的生成偏好；这些说明会追加到 Codex 的提交信息与 PR 提示词里。"
      actions={
        <Button size="sm" variant="soft" color="secondary" onClick={reset}>
          恢复默认
        </Button>
      }
    >
      <PaneSection title="仓库">
        <PaneCard>
          <PaneRow
            label="工作树根目录"
            description="ChatGPT 创建托管工作树的目录。留空则使用默认位置"
            control={
              editingRoot ? (
                <span className="cx-pane__input-group">
                  <Input
                    size="sm"
                    className="cx-pane__input cx-pane__input--w260"
                    aria-label="工作树根目录"
                    value={state.worktreeRoot}
                    placeholder={DEFAULT_WORKTREE_ROOT}
                    onChange={(event) => patch({ worktreeRoot: event.target.value })}
                  />
                  <Button size="sm" variant="soft" color="secondary" onClick={() => setEditingRoot(false)}>
                    完成
                  </Button>
                </span>
              ) : (
                <PaneValueText
                  value={state.worktreeRoot || DEFAULT_WORKTREE_ROOT}
                  mono
                  actionLabel="更改"
                  onAction={() => setEditingRoot(true)}
                />
              )
            }
          />
          <PaneInputRow
            label="分支前缀"
            description="ChatGPT 创建新分支时使用的前缀"
            ariaLabel="分支前缀"
            placeholder="codex/"
            value={state.branchPrefix}
            onChange={(value) => patch({ branchPrefix: value })}
            width={200}
          />
        </PaneCard>
      </PaneSection>

      <PaneSection title="提交与拉取请求">
        <PaneCard>
          <PaneTextBlock
            label="提交说明"
            description="将添加到提交信息生成提示中"
            ariaLabel="提交说明"
            placeholder="添加提交信息指引…"
            rows={3}
            value={state.commitInstructions}
            onChange={(value) => patch({ commitInstructions: value })}
          />
          <PaneTextBlock
            label="Pull Request 说明"
            description="将添加到 PR 标题/描述生成提示中"
            ariaLabel="Pull Request 说明"
            placeholder="添加 Pull Request 指引…"
            rows={3}
            value={state.prInstructions}
            onChange={(value) => patch({ prInstructions: value })}
          />
          <PaneRow
            label="Pull Request 合并方法"
            description="选择 ChatGPT 合并 Pull Request 的方式"
            control={
              <PaneSelect
                ariaLabel="Pull Request 合并方法"
                value={state.mergeMethod}
                onChange={(value) => patch({ mergeMethod: value })}
                options={MERGE_METHODS}
              />
            }
          />
          <PaneRow
            label="创建草稿 Pull Request"
            description="从 ChatGPT 创建 PR 时默认使用草稿 Pull Request"
            control={
              <PaneSwitch
                label="创建草稿 Pull Request"
                checked={state.draftPr}
                onChange={(checked) => patch({ draftPr: checked })}
              />
            }
          />
          <PaneRow
            label="始终强制推送"
            description="从 ChatGPT 推送时使用 --force-with-lease"
            control={
              <PaneConfirmAction
                danger
                confirmLabel="允许强制推送"
                title="允许 Codex 强制推送？"
                description="开启后 Codex 会用 --force-with-lease 覆盖远端分支。lease 校验失败时会中止，但仍可能覆盖他人的提交。"
                onConfirm={() => patch({ forcePush: true })}
                trigger={
                  <PaneSwitch
                    label="始终强制推送"
                    checked={state.forcePush}
                    onChange={(checked) => {
                      if (!checked) patch({ forcePush: false });
                    }}
                  />
                }
              />
            }
          />
        </PaneCard>
      </PaneSection>

      <PaneSection title="代码审查">
        <PaneCard>
          <PaneRow
            label="禁用基于 Git 的差异对比"
            description="在「变更」面板中仅显示「上一轮」差异，并禁用「未暂存」/「已暂存」/「分支」，以避免 Git 操作"
            control={
              <PaneSwitch
                label="禁用基于 Git 的差异对比"
                checked={state.disableGitDiff}
                onChange={(checked) => patch({ disableGitDiff: checked })}
              />
            }
          />
          <PaneRow
            label="审查结果呈现方式"
            description="尽可能在当前聊天中启动 /review，或启动单独的审查聊天"
            control={
              <PaneSelect
                ariaLabel="审查结果呈现方式"
                value={state.reviewDelivery}
                onChange={(value) => patch({ reviewDelivery: value })}
                options={REVIEW_DELIVERY}
              />
            }
          />
        </PaneCard>
      </PaneSection>

      <PaneSection
        title="监控并修复 Pull Request"
        description="Codex 会跟随已开启的 PR，按说明持续修复直到合并。"
      >
        <PaneCard>
          <PaneRow
            label="启用监控"
            description="打开后 Codex 会监控你开启的 Pull Request，并按需推送修复提交"
            control={
              <PaneSwitch
                label="启用监控"
                checked={state.watchPr}
                onChange={(checked) => patch({ watchPr: checked })}
              />
            }
          />
          <PaneRow
            label="准备就绪时自动合并"
            description="继续监控，直到 Pull Request 合并"
            control={
              <PaneSwitch
                label="准备就绪时自动合并"
                checked={state.autoMerge}
                disabled={!state.watchPr}
                onChange={(checked) => patch({ autoMerge: checked })}
              />
            }
          />
          {state.watchPr ? (
            <PaneTextBlock
              label="Pull Request 监控说明"
              description="追加到监控提示中，告诉 Codex 何时该合并或该停下"
              ariaLabel="Pull Request 监控说明"
              placeholder="例如：检查通过后评论 /merge，并批准不相关的 Chromatic 变更…"
              rows={3}
              value={state.watchInstructions}
              onChange={(value) => patch({ watchInstructions: value })}
            />
          ) : (
            <PaneEmpty title="监控已关闭" description="打开「启用监控」后可以填写 PR 监控说明。" />
          )}
        </PaneCard>
      </PaneSection>
    </PaneShell>
  );
}
