import { Button } from "@/ui";
import type { SettingsPaneProps } from "./index";
import {
  PaneCard,
  PaneConfirmAction,
  PaneEmpty,
  PaneRow,
  PaneSection,
  PaneShell,
  PaneSwitch,
  PaneTextBlock,
} from "./pane-kit";
import { usePaneState } from "./pane-state";

/**
 * 个性化（官方 slug personalization，chunk personalization-settings-c89980ee5a5a.js，181 条消息）。
 *
 * 行证据（官方 zh-CN）：
 *   settings.chatGpt.personalization.instructions.description「为 ChatGPT 提供适用于所有聊天的额外指令和背景信息。」
 *     / .disabled「自定义指令已关闭」/ .disabled.description / .enable「启用自定义指令」
 *     / .customInstructions.placeholder「其他行为、风格和语气偏好」
 *   settings.chatGpt.personalization.moreAboutYou.label「关于你的更多信息」
 *   settings.chatGpt.personalization.baseStyle「基础风格和语气」/ .description
 *   settings.chatGpt.personalization.memory.description（配置 ChatGPT 如何管理记忆）
 *     / .memory.saved.enabled.description / .memory.saved.manage.description / .memory.history.enabled.*
 *   settings.memory.enableMemoriesDescription.host「根据 {hostName} 上的聊天创建记忆，并使用这些记忆为今后在 {hostName} 上的聊天提供个性化体验」
 *   settings.memory.allowMemoryGenerationFromToolAssistedTasksDescription「从使用过 MCP 工具或网页搜索的聊天生成记忆」
 *   settings.memory.resetDialogTitle.host「要删除全部 Codex 记忆吗？」/ .resetDialogConfirm「删除」/ .resetDialogCancel「取消」
 *     / .resetMemoriesDescription.host / .resetSuccess.host
 *   settings.chatGpt.personalization.imageGeneration.label「图像生成」/ .description
 *   settings.chatGpt.personalization.advanced.code/connectors/library/web/voice（代码 / 连接器搜索 / 搜索资料库 / 网页搜索 / ChatGPT 语音）
 *   settings.chatGpt.personalization.fastAnswers「快速回答」/ .description
 *   settings.userRules.*（SPEC §4.2.6 登记的行；该组 6 条消息未逐条取证 → 文案按 SPEC 行清单给出）
 *
 * 此页无实测几何，按通用规格推导（SPEC §8.1）；当前值官方无证据（§8.2）。
 */

interface PersonalizationPaneState {
  instructions: string;
  instructionsEnabled: boolean;
  aboutYou: string;
  baseStyle: string;
  baseStyleNote: string;
  memory: boolean;
  memoryFromTools: boolean;
  imageGeneration: boolean;
  fastAnswers: boolean;
  advanced: Record<string, boolean>;
  userRules: { id: string; text: string }[];
}

const DEFAULTS: PersonalizationPaneState = {
  instructions: "",
  instructionsEnabled: true,
  aboutYou: "",
  baseStyle: "default",
  baseStyleNote: "",
  memory: true,
  memoryFromTools: true,
  imageGeneration: true,
  fastAnswers: false,
  advanced: { code: true, connectors: true, library: true, web: true, voice: false },
  userRules: [],
};

const ADVANCED_ROWS = [
  { key: "code", label: "代码", description: "允许 ChatGPT 使用代码解释器执行代码" },
  { key: "connectors", label: "连接器搜索", description: "允许 ChatGPT 自动搜索已连接的来源以查找答案" },
  { key: "library", label: "搜索资料库", description: "允许 ChatGPT 自动搜索资料库中的文件以查找答案" },
  { key: "web", label: "网页搜索", description: "让 ChatGPT 自动搜索网页以查找答案" },
  { key: "voice", label: "ChatGPT 语音", description: "在 ChatGPT 中启用语音" },
];

const BASE_STYLES = [
  { value: "default", label: "默认" },
  { value: "professional", label: "专业" },
  { value: "friendly", label: "友好" },
  { value: "direct", label: "直接" },
];

export function PersonalizationPane({ section }: SettingsPaneProps) {
  const [state, patch, reset] = usePaneState(section, DEFAULTS);

  return (
    <PaneShell
      section={section}
      title="个性化"
      lede="自定义指令、记忆与高级能力开关；这些内容只影响你自己的会话。"
      actions={
        <Button size="sm" variant="soft" color="secondary" onClick={reset}>
          恢复默认
        </Button>
      }
    >
      <PaneSection title="自定义指令">
        <PaneCard>
          <PaneRow
            label="启用自定义指令"
            description="启用已保存的指令和个人信息，以便在聊天中使用"
            control={
              <PaneSwitch
                label="启用自定义指令"
                checked={state.instructionsEnabled}
                onChange={(checked) => patch({ instructionsEnabled: checked })}
              />
            }
          />
          {state.instructionsEnabled ? (
            <PaneTextBlock
              label="自定义指令"
              description="为 ChatGPT 提供适用于所有聊天的额外指令和背景信息。"
              ariaLabel="自定义指令"
              placeholder="其他行为、风格和语气偏好"
              rows={5}
              value={state.instructions}
              onChange={(value) => patch({ instructions: value })}
              footer={<span className="cx-pane__hint">{state.instructions.length} 字</span>}
            />
          ) : (
            <PaneEmpty title="自定义指令已关闭" description="重新打开开关即可编辑并生效。" />
          )}
          <PaneTextBlock
            label="关于你的更多信息"
            description="让 ChatGPT 了解你的背景、称呼偏好与常用技术栈"
            ariaLabel="关于你的更多信息"
            rows={3}
            value={state.aboutYou}
            onChange={(value) => patch({ aboutYou: value })}
          />
        </PaneCard>
      </PaneSection>

      <PaneSection title="风格与语气">
        <PaneCard>
          <PaneRow
            label="基础风格和语气"
            description="设置 ChatGPT 回复你的风格和语气。这不会影响 ChatGPT 的功能。"
            control={
              <span className="cx-pane__input-group">
                <Button
                  size="sm"
                  variant="soft"
                  color="secondary"
                  onClick={() =>
                    patch({
                      baseStyle:
                        BASE_STYLES[
                          (BASE_STYLES.findIndex((item) => item.value === state.baseStyle) + 1) %
                            BASE_STYLES.length
                        ].value,
                    })
                  }
                >
                  {BASE_STYLES.find((item) => item.value === state.baseStyle)?.label ?? "默认"}
                </Button>
                <Button
                  size="sm"
                  variant="ghost"
                  color="secondary"
                  onClick={() => patch({ baseStyle: "default" })}
                >
                  重置
                </Button>
              </span>
            }
          />
          <PaneTextBlock
            label="风格补充说明"
            description="补充你希望固定下来的措辞习惯"
            ariaLabel="风格补充说明"
            rows={2}
            value={state.baseStyleNote}
            onChange={(value) => patch({ baseStyleNote: value })}
          />
          <PaneRow
            label="快速回答"
            description="ChatGPT 有时可以利用其通用知识，快速提供深入的回答。这些回答并非个性化回答，也不会使用你的记忆。"
            control={
              <PaneSwitch
                label="快速回答"
                checked={state.fastAnswers}
                onChange={(checked) => patch({ fastAnswers: checked })}
              />
            }
          />
        </PaneCard>
      </PaneSection>

      <PaneSection title="记忆">
        <PaneCard>
          <PaneRow
            label="启用记忆"
            description="根据本机上的聊天创建记忆，并使用这些记忆为今后的聊天提供个性化体验"
            control={
              <PaneSwitch
                label="启用记忆"
                checked={state.memory}
                onChange={(checked) => patch({ memory: checked })}
              />
            }
          />
          <PaneRow
            label="从使用工具的聊天中生成记忆"
            description="从使用过 MCP 工具或网页搜索的聊天生成记忆"
            control={
              <PaneSwitch
                label="从使用工具的聊天中生成记忆"
                checked={state.memoryFromTools}
                disabled={!state.memory}
                onChange={(checked) => patch({ memoryFromTools: checked })}
              />
            }
          />
          <PaneRow
            label="删除全部 Codex 记忆"
            description="删除本机上的全部 Codex 记忆，之后新会话不会再引用它们"
            control={
              <PaneConfirmAction
                danger
                confirmLabel="删除"
                cancelLabel="取消"
                title="要删除全部 Codex 记忆吗？"
                description="此操作将删除本机的所有 Codex 记忆，无法撤销。"
                onConfirm={() => patch({ memory: false, memoryFromTools: false })}
                trigger={
                  <Button size="sm" variant="soft" color="danger">
                    删除
                  </Button>
                }
              />
            }
          />
        </PaneCard>
      </PaneSection>

      <PaneSection title="能力">
        <PaneCard>
          <PaneRow
            label="图像生成"
            description="在 ChatGPT 中启用图像生成"
            control={
              <PaneSwitch
                label="图像生成"
                checked={state.imageGeneration}
                onChange={(checked) => patch({ imageGeneration: checked })}
              />
            }
          />
          {ADVANCED_ROWS.map((row) => (
            <PaneRow
              key={row.key}
              label={row.label}
              description={row.description}
              control={
                <PaneSwitch
                  label={row.label}
                  checked={state.advanced[row.key] ?? false}
                  onChange={(checked) => patch({ advanced: { ...state.advanced, [row.key]: checked } })}
                />
              }
            />
          ))}
        </PaneCard>
      </PaneSection>

      <PaneSection
        title="用户规则"
        description="为特定话题固定行为（官方 id 前缀 settings.userRules.*，SPEC §4.2.6）"
      >
        <PaneCard>
          {state.userRules.length === 0 ? (
            <PaneEmpty
              title="还没有用户规则"
              description="规则会按顺序匹配，命中后覆盖默认行为。"
              action={
                <Button
                  size="sm"
                  variant="soft"
                  color="secondary"
                  onClick={() => patch({ userRules: [{ id: "rule-1", text: "" }] })}
                >
                  添加规则
                </Button>
              }
            />
          ) : (
            state.userRules.map((rule, index) => (
              <PaneTextBlock
                key={rule.id}
                label={`规则 ${String(index + 1)}`}
                ariaLabel={`规则 ${String(index + 1)}`}
                rows={2}
                value={rule.text}
                onChange={(value) =>
                  patch({
                    userRules: state.userRules.map((item) =>
                      item.id === rule.id ? { ...item, text: value } : item,
                    ),
                  })
                }
                footer={
                  <span className="cx-pane__input-group">
                    <Button
                      size="sm"
                      variant="soft"
                      color="secondary"
                      onClick={() =>
                        patch({
                          userRules: [
                            ...state.userRules,
                            { id: `rule-${String(state.userRules.length + 1)}`, text: "" },
                          ],
                        })
                      }
                    >
                      再添加一条
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      color="danger"
                      onClick={() =>
                        patch({ userRules: state.userRules.filter((item) => item.id !== rule.id) })
                      }
                    >
                      删除
                    </Button>
                  </span>
                }
              />
            ))
          )}
        </PaneCard>
      </PaneSection>
    </PaneShell>
  );
}
