import { useMemo, useState } from "react";

import { useArtexQuery } from "@/api/artex";
import { PanelPortal } from "@/shell";
import { CodexRailScheduled, CodexRefresh } from "@/icons";
import { Button } from "@/ui";

import { Badge, EmptyState, RowSkeleton, SearchField } from "./parts";

/**
 * 任务页（rail「任务」，外壳路由 /tasks）—— objective ② 的第一个「外壳原生渲染」页面。
 *
 * 与 /artex（把控制台 iframe 托管进来）不同：这一页是**外壳自己的代码**在画，
 * 数据由外壳直连 ARTEX API 取得（src/api/artex.ts）。之所以能做到，是三件事凑齐了：
 *   1. 后端 /api/* 的 CORS 是 *（server/server.go 的 cors()，实测 OPTIONS/GET 都带该头）；
 *   2. 访客（控制台）在握手后把 access token 经 codex-host:token 交给外壳（host-store）；
 *   3. 容器挂载时登记 API origin（= 访客 origin，生产态 http://127.0.0.1:8787）。
 *
 * 组件与样式全部复用外壳自己的：.cx-page__* / .cx-row*（pages.css）、@/ui 的 Button、
 * 以及 pages/parts 的 Badge/EmptyState/RowSkeleton/SearchField —— 不新造数值。
 *
 * 数据契约（控制台 src/lib/types.ts:Task）只取本页用到的字段；其余透传不解释，
 * 避免外壳对业务模型做假设。
 */

interface ArtexTask {
  id: string;
  name?: string;
  description?: string;
  goal?: string;
  status?: string;
  pinned?: boolean;
  paused?: boolean;
  queued?: boolean;
  in_flight?: number;
  last_activity?: string;
  goals_total?: number;
  goals_met?: number;
}

interface TasksResponse {
  tasks?: ArtexTask[];
  active?: string;
}

/** ARTEX 任务状态 → 展示文案。未知状态原样显示，绝不猜。 */
const STATUS_LABEL: Record<string, string> = {
  pending: "待开始",
  queued: "排队中",
  running: "进行中",
  paused: "已暂停",
  done: "已完成",
  failed: "已失败",
  archived: "已归档",
};

function statusText(task: ArtexTask): string {
  if (task.in_flight && task.in_flight > 0) return "进行中";
  if (task.paused) return "已暂停";
  if (task.queued) return "排队中";
  const raw = (task.status ?? "").trim();
  if (!raw) return "未知";
  return STATUS_LABEL[raw] ?? raw;
}

function taskTitle(task: ArtexTask): string {
  const named = (task.name ?? "").trim();
  if (named) return named;
  const desc = (task.description ?? task.goal ?? "").trim();
  if (!desc) return "未命名任务";
  return desc.length > 80 ? desc.slice(0, 80) + "…" : desc;
}

function taskMeta(task: ArtexTask): string {
  const parts: string[] = [];
  if (typeof task.goals_total === "number" && task.goals_total > 0) {
    parts.push("目标 " + (task.goals_met ?? 0) + "/" + task.goals_total);
  }
  if (task.last_activity && task.last_activity.trim()) parts.push(task.last_activity.trim());
  return parts.join(" · ");
}

export function TasksRoute() {
  const { data, error, loading, reload } = useArtexQuery<TasksResponse>("/api/tasks");
  const [query, setQuery] = useState("");

  const tasks = data?.tasks ?? [];
  const filtered = useMemo(() => {
    const needle = query.trim().toLowerCase();
    if (!needle) return tasks;
    return tasks.filter((task) => {
      const haystack = (taskTitle(task) + " " + (task.description ?? "") + " " + (task.status ?? "")).toLowerCase();
      return haystack.includes(needle);
    });
  }, [tasks, query]);

  const running = tasks.filter((task) => statusText(task) === "进行中").length;

  return (
    <div className="cx-page cx-page--tasks">
      <div className="cx-page__toolbar">
        <SearchField onChange={setQuery} placeholder="搜索任务" value={query} />
        <div className="cx-page__toolbar-trailing">
          <span className="cx-muted">
            {tasks.length} 个任务{running > 0 ? " · " + running + " 个进行中" : ""}
          </span>
          <Button aria-label="刷新任务" onClick={reload} size="sm" uniform variant="ghost">
            <CodexRefresh size={14} />
          </Button>
        </div>
      </div>

      <div className="cx-page__body">
        {loading ? (
          <>
            <span className="cx-muted">正在加载任务</span>
            <RowSkeleton rows={5} />
          </>
        ) : null}

        {!loading && error ? (
          <EmptyState
            description={
              error.status === 0
                ? "外壳还没拿到控制台的访问令牌（访客未附着或未登录）。"
                : "ARTEX API 返回 " + error.status + (error.message ? "：" + error.message : "") +
                  (error.status === 401 ? "（令牌可能已失效：回到「对话」页会自动续期）" : "")
            }
            icon={CodexRailScheduled}
            layout="center"
            title="任务加载失败"
            actions={
              <Button onClick={reload} size="sm" variant="surface">
                重试
              </Button>
            }
          />
        ) : null}

        {!loading && !error && filtered.length === 0 ? (
          <EmptyState
            description={query ? "没有符合「" + query + "」的任务。" : "还没有任务：在对话里下达目标就会创建任务。"}
            icon={CodexRailScheduled}
            layout="center"
            title={query ? "没有匹配的任务" : "暂无任务"}
          />
        ) : null}

        {!loading && !error && filtered.length > 0 ? (
          <span className="cx-muted">从左侧选择任务查看详情（列表在面板里 —— 与官方 /scheduled 同一种信息架构）。</span>
        ) : null}

        {/* 面板侧永远渲染（含空态）：只渲染有数据时，面板会整块空白，用户会以为坏了。 */}
        <PanelPortal>
          {loading ? (
            <section className="cx-page__section">
              <h2 className="cx-page__section-title">任务</h2>
              <RowSkeleton rows={4} />
            </section>
          ) : (
          <section className="cx-page__section">
            <h2 className="cx-page__section-title">
              任务
              <span className="cx-page__section-count">{filtered.length}</span>
            </h2>
            {filtered.length === 0 ? (
              <p className="cx-muted">暂无任务</p>
            ) : null}
            <ul className="cx-page__list">
              {filtered.map((task) => (
                <li className="cx-row-wrap" key={task.id}>
                  <div className="cx-row" data-selected={task.id === data?.active ? "true" : undefined}>
                    <span aria-hidden className="cx-row__icon">
                      <CodexRailScheduled size={20} />
                    </span>
                    <span className="cx-row__main">
                      <span className="cx-row__t">
                        {task.pinned ? "📌 " : ""}
                        {taskTitle(task)}
                      </span>
                      {taskMeta(task) ? <span className="cx-row__s">{taskMeta(task)}</span> : null}
                    </span>
                    <Badge tone={statusText(task) === "已失败" ? "danger" : undefined}>{statusText(task)}</Badge>
                  </div>
                </li>
              ))}
            </ul>
          </section>
          )}
        </PanelPortal>
      </div>
    </div>
  );
}