import { useMemo, useState } from "react";

import { useArtexQuery } from "@/api/artex";
import { PanelPortal } from "@/shell";
import { CodexRailReview, CodexRefresh } from "@/icons";
import { Button } from "@/ui";

import { Badge, EmptyState, RowSkeleton, SearchField } from "./parts";

/**
 * 发现页（rail「发现」，外壳路由 /findings）—— objective ② 的第二个「外壳原生渲染」页面。
 *
 * 与 /tasks 同一套路：外壳自己的组件与样式画页面，数据走 src/api/artex.ts 直连 ARTEX API
 * （/api/exploration/findings，契约见控制台 src/lib/types.ts:Finding）。
 * token 由静默宿主容器提供（HostAuthFrame），后端 CORS 已放行 Authorization。
 *
 * 只取本页用到的字段；未知严重度/状态原样显示，不猜。
 */

interface ArtexFinding {
  id: string;
  finding_id?: string;
  vulnclass?: string;
  name?: string;
  severity?: string;
  status?: string;
  summary?: string;
  task_id?: string;
  task_description?: string;
  ts?: string;
  assets?: unknown[];
}

const SEVERITY_LABEL: Record<string, string> = {
  critical: "严重",
  high: "高危",
  medium: "中危",
  low: "低危",
  info: "提示",
};

const STATUS_LABEL: Record<string, string> = {
  open: "待处理",
  confirmed: "已确认",
  fixed: "已修复",
  false_positive: "误报",
  ignored: "已忽略",
};

function severityText(finding: ArtexFinding): string {
  const raw = (finding.severity ?? "").trim();
  if (!raw) return "未分级";
  return SEVERITY_LABEL[raw] ?? raw;
}

function severityTone(finding: ArtexFinding): string | undefined {
  const raw = (finding.severity ?? "").trim();
  if (raw === "critical" || raw === "high") return "danger";
  if (raw === "low" || raw === "info") return "muted";
  return undefined;
}

function statusText(finding: ArtexFinding): string {
  const raw = (finding.status ?? "").trim();
  if (!raw) return "未知";
  return STATUS_LABEL[raw] ?? raw;
}

function findingTitle(finding: ArtexFinding): string {
  const named = (finding.name ?? "").trim();
  if (named) return named;
  const cls = (finding.vulnclass ?? "").trim();
  if (cls) return cls;
  const summary = (finding.summary ?? "").trim();
  if (summary) return summary.length > 80 ? summary.slice(0, 80) + "…" : summary;
  return "未命名发现";
}

function findingMeta(finding: ArtexFinding): string {
  const parts: string[] = [];
  const task = (finding.task_description ?? "").trim();
  if (task) parts.push(task.length > 40 ? task.slice(0, 40) + "…" : task);
  if (Array.isArray(finding.assets) && finding.assets.length > 0) parts.push(finding.assets.length + " 个资产");
  if (finding.ts && finding.ts.trim()) parts.push(finding.ts.trim());
  return parts.join(" · ");
}

export function FindingsRoute() {
  const { data, error, loading, reload } = useArtexQuery<ArtexFinding[]>("/api/exploration/findings");
  const [query, setQuery] = useState("");

  const findings = Array.isArray(data) ? data : [];
  const filtered = useMemo(() => {
    const needle = query.trim().toLowerCase();
    if (!needle) return findings;
    return findings.filter((finding) => {
      const haystack = [findingTitle(finding), finding.summary ?? "", finding.vulnclass ?? "", severityText(finding)]
        .join(" ")
        .toLowerCase();
      return haystack.includes(needle);
    });
  }, [findings, query]);

  const critical = findings.filter((finding) => severityText(finding) === "严重" || severityText(finding) === "高危").length;

  return (
    <div className="cx-page cx-page--findings">
      <div className="cx-page__toolbar">
        <SearchField onChange={setQuery} placeholder="搜索发现" value={query} />
        <div className="cx-page__toolbar-trailing">
          <span className="cx-muted">
            {findings.length} 个发现{critical > 0 ? " · " + critical + " 个严重/高危" : ""}
          </span>
          <Button aria-label="刷新发现" onClick={reload} size="sm" uniform variant="ghost">
            <CodexRefresh size={14} />
          </Button>
        </div>
      </div>

      <div className="cx-page__body">
        {loading ? (
          <>
            <span className="cx-muted">正在加载发现</span>
            <RowSkeleton rows={5} />
          </>
        ) : null}

        {!loading && error ? (
          <EmptyState
            description={"ARTEX API 返回 " + error.status + (error.message ? "：" + error.message : "") + (error.status === 401 ? "（令牌可能已失效：回到「对话」页会自动续期）" : "")}
            icon={CodexRailReview}
            layout="center"
            title="发现加载失败"
            actions={
              <Button onClick={reload} size="sm" variant="surface">
                重试
              </Button>
            }
          />
        ) : null}

        {!loading && !error && filtered.length === 0 ? (
          <EmptyState
            description={query ? "没有符合「" + query + "」的发现。" : "还没有发现：跑一次任务后结果会汇总到这里。"}
            icon={CodexRailReview}
            layout="center"
            title={query ? "没有匹配的发现" : "暂无发现"}
          />
        ) : null}

        {!loading && !error && filtered.length > 0 ? (
          <span className="cx-muted">从左侧选择发现查看详情（列表在面板里 —— 与官方 /scheduled 同一种信息架构）。</span>
        ) : null}

        {/* 面板侧永远渲染（含空态）：只渲染有数据时，面板会整块空白，用户会以为坏了。 */}
        <PanelPortal>
          {loading ? (
            <section className="cx-page__section">
              <h2 className="cx-page__section-title">发现</h2>
              <RowSkeleton rows={4} />
            </section>
          ) : (
          <section className="cx-page__section">
            <h2 className="cx-page__section-title">
              发现
              <span className="cx-page__section-count">{filtered.length}</span>
            </h2>
            {filtered.length === 0 ? (
              <p className="cx-muted">暂无发现</p>
            ) : null}
            <ul className="cx-page__list">
              {filtered.map((finding) => (
                <li className="cx-row-wrap" key={finding.id}>
                  <div className="cx-row">
                    <span aria-hidden className="cx-row__icon">
                      <CodexRailReview size={20} />
                    </span>
                    <span className="cx-row__main">
                      <span className="cx-row__t">{findingTitle(finding)}</span>
                      {findingMeta(finding) ? <span className="cx-row__s">{findingMeta(finding)}</span> : null}
                    </span>
                    <Badge tone={severityTone(finding)}>{severityText(finding)}</Badge>
                    <Badge tone="muted">{statusText(finding)}</Badge>
                  </div>
                </li>
              ))}
            </ul>
          </section>
          )}
        </PanelPortal>
      </div>
    </div>
  );
}