/**
 * 宿主页面（路由 /artex）：把 guest 应用放进外壳主表面。
 *
 * 这一层只做两件事：解析地址、决定渲染「未配置」还是「宿主容器」。
 * 真实的 iframe / 通道 / 生命周期都在 HostFrame 里，页面不重复实现。
 */
import { useMemo } from "react";
import { useLocation } from "react-router-dom";

import { HostFrame } from "./HostFrame";
import { resolveHostTarget } from "./host-config";

export function ArtexHostPage() {
  const { search } = useLocation();
  const target = useMemo(() => resolveHostTarget(search), [search]);

  /*
    这里**不再套 PageSurface**（2026-10-13 修）：主表面由 AppShell 按路由档位统一提供
    （见 page-layouts.ts 的 "host" 档），本页再套一层会把 --codex-surface-inset 让位
    重复消费一次 —— 实测 iframe 从 935×716 被压成 647×716、左侧空出 288px 死区，
    而官方首页主内容面就是 936×768（[340,44,936,768]）。
    本页只负责「解析地址 → 决定渲染未配置态还是宿主容器」。
  */
  return target == null ? <HostUnconfigured /> : <HostFrame key={target.origin} target={target} />;
}

/** 地址缺失/非法时的落地面：说清怎么配，而不是留一个白屏。 */
function HostUnconfigured() {
  return (
    <div className="codex-host">
      <div className="codex-host__overlay" role="status">
        <p className="codex-host__overlay-title">没有配置被托管的本地应用</p>
        <p className="codex-host__overlay-body">
          用 {"`/artex?artex=http://127.0.0.1:3007`"} 指定地址，或设置构建变量 {"`VITE_ARTEX_HOST_URL`"}。
        </p>
      </div>
    </div>
  );
}