import { Button, Input } from "@/ui";
import type { SettingsPaneProps } from "./index";
import { PaneBanner, PaneCard, PaneEmpty, PaneRow, PaneSection, PaneShell, PaneSwitch } from "./pane-kit";
import { newPaneId, usePaneState } from "./pane-state";

/**
 * 连接（官方 slug connections，chunk remote-connections-settings-1b78040bf991.js，241 条消息）。
 *
 * 行证据（官方 zh-CN）：
 *   settings.remoteConnections.localHost.remoteControl.label「允许发现并控制此设备」
 *     / .description「ChatGPT 账户下的已授权设备可以发现并控制此设备」
 *   settings.remoteConnections.localHost.keepLive.label「让这台 Mac 保持唤醒状态」
 *     / .description「当电脑接通电源且启用远程访问时，防止其进入睡眠状态」
 *   settings.remoteConnections.localHost.otherSettings.title「其他设置」
 *   settings.remoteConnections.accessOtherDevices.header.title「可通过这台 Mac 控制的设备」
 *     / .devices.title 同字符串 / .empty「尚未添加设备」/ .setup.description「从这台计算机访问和控制其他设备」
 *   settings.remoteConnections.remoteControlClients.devices.title「可控制这台 Mac 的设备」
 *     / .empty「添加设备以远程控制这台 Mac」/ .setup.description「通过手机或其他设备控制这台 Mac」
 *     / .loadError.title「无法加载设备列表」
 *   settings.remoteConnections.ssh.header.title「来自这台 Mac 的 SSH 连接」/ .empty「通过 SSH 连接到远程设备」
 *   settings.remoteConnections.wsl.header.title「WSL 连接」
 *   settings.remoteConnections.discoveryDialog.title「添加 SSH 连接」/ .empty「未发现 SSH 连接」
 *   settings.remoteConnections.manualPairingDialog.title「添加设备」/ .remoteControlDiscoveryDialog.title「添加设备」
 *     / .empty「没有可用的已登录设备」
 *   settings.remoteConnections.auth.title「需要登录」/ .description「验证此远程机器上的 Codex CLI 以继续」
 *   settings.remoteConnections.deviceConnections.empty「未找到设备连接。添加新连接即可开始使用」
 *
 * 此页无实测几何，按通用规格推导（SPEC §8.1）；设备清单官方无运行时证据（§8.2）。
 * 官方文案里的「Mac」按 1:1 原文保留（本机是 Windows，但取证不改编文案）。
 */

interface DeviceRow {
  id: string;
  name: string;
  detail: string;
}

interface ConnectionsPaneState {
  remoteControl: boolean;
  keepLive: boolean;
  requiresAuth: boolean;
  controlledDevices: DeviceRow[];
  controllers: DeviceRow[];
  ssh: DeviceRow[];
  wsl: DeviceRow[];
  pairingCode: string;
  discoveryEmpty: boolean;
  loadFailed: boolean;
}

const DEFAULTS: ConnectionsPaneState = {
  remoteControl: false,
  keepLive: false,
  requiresAuth: true,
  controlledDevices: [],
  controllers: [],
  ssh: [],
  wsl: [],
  pairingCode: "",
  discoveryEmpty: false,
  loadFailed: false,
};

export function ConnectionsPane({ section }: SettingsPaneProps) {
  const [state, patch, reset] = usePaneState(section, DEFAULTS);

  function addDevice(kind: "controlled" | "controller" | "ssh" | "wsl") {
    const label = state.pairingCode.trim() || `设备 ${String(Date.now() % 1000)}`;
    const row: DeviceRow = { id: newPaneId(), name: label, detail: "刚刚添加" };
    if (kind === "controlled") patch({ controlledDevices: [...state.controlledDevices, row] });
    if (kind === "controller") patch({ controllers: [...state.controllers, row] });
    if (kind === "ssh") patch({ ssh: [...state.ssh, row] });
    if (kind === "wsl") patch({ wsl: [...state.wsl, row] });
    patch({ pairingCode: "" });
  }

  return (
    <PaneShell
      section={section}
      title="连接"
      lede="本机的远程控制开关、可互相控制的设备清单，以及 SSH / WSL 连接。"
      actions={
        <Button size="sm" variant="soft" color="secondary" onClick={reset}>
          重置
        </Button>
      }
    >
      {state.requiresAuth ? (
        <PaneBanner
          tone="warning"
          title="需要登录"
          description="验证此远程机器上的 Codex CLI 以继续"
          action={
            <Button size="sm" variant="soft" color="secondary" onClick={() => patch({ requiresAuth: false })}>
              已完成验证
            </Button>
          }
        />
      ) : null}

      {state.loadFailed ? (
        <PaneBanner
          tone="danger"
          title="无法加载设备列表"
          description="读取授权设备失败，可能是网络或登录态问题。"
          action={
            <Button size="sm" variant="soft" color="secondary" onClick={() => patch({ loadFailed: false })}>
              重试
            </Button>
          }
        />
      ) : null}

      <PaneSection title="其他设置">
        <PaneCard>
          <PaneRow
            label="允许发现并控制此设备"
            description="ChatGPT 账户下的已授权设备可以发现并控制此设备"
            control={
              <PaneSwitch
                label="允许发现并控制此设备"
                checked={state.remoteControl}
                onChange={(checked) => patch({ remoteControl: checked })}
              />
            }
          />
          <PaneRow
            label="让这台 Mac 保持唤醒状态"
            description="当电脑接通电源且启用远程访问时，防止其进入睡眠状态"
            control={
              <PaneSwitch
                label="让这台 Mac 保持唤醒状态"
                checked={state.keepLive}
                disabled={!state.remoteControl}
                onChange={(checked) => patch({ keepLive: checked })}
              />
            }
          />
        </PaneCard>
      </PaneSection>

      <PaneSection title="可通过这台 Mac 控制的设备" description="从这台计算机访问和控制其他设备">
        <PaneCard>
          <div className="cx-pane__toolbar">
            <Input
              size="sm"
              className="cx-pane__input cx-pane__input--w200"
              aria-label="配对码或设备名"
              placeholder="配对码或设备名"
              value={state.pairingCode}
              onChange={(event) => patch({ pairingCode: event.target.value })}
            />
            <span className="cx-pane__toolbar-group">
              <Button size="sm" variant="soft" color="secondary" onClick={() => addDevice("controlled")}>
                添加设备
              </Button>
              <Button size="sm" variant="ghost" color="secondary" onClick={() => patch({ loadFailed: true })}>
                模拟加载失败
              </Button>
            </span>
          </div>
          {state.controlledDevices.length === 0 ? (
            <PaneEmpty
              title="尚未添加设备"
              description="添加设备后，可以从这台电脑直接打开并控制它的会话。"
            />
          ) : (
            <div className="cx-pane__list">
              {state.controlledDevices.map((device) => (
                <div key={device.id} className="cx-pane__list-item">
                  <div className="cx-pane__list-main">
                    <span className="cx-pane__list-title">{device.name}</span>
                    <span className="cx-pane__list-meta">{device.detail}</span>
                  </div>
                  <div className="cx-pane__list-actions">
                    <Button
                      size="sm"
                      variant="ghost"
                      color="danger"
                      onClick={() =>
                        patch((prev) => ({
                          ...prev,
                          controlledDevices: prev.controlledDevices.filter((item) => item.id !== device.id),
                        }))
                      }
                    >
                      移除
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </PaneCard>
      </PaneSection>

      <PaneSection title="可控制这台 Mac 的设备" description="通过手机或其他设备控制这台 Mac">
        <PaneCard>
          <div className="cx-pane__toolbar">
            <span className="cx-pane__list-meta">配对环境：已登录的 ChatGPT 账户</span>
            <span className="cx-pane__toolbar-group">
              <Button
                size="sm"
                variant="soft"
                color="secondary"
                onClick={() =>
                  state.remoteControl ? addDevice("controller") : patch({ remoteControl: true })
                }
              >
                添加设备
              </Button>
            </span>
          </div>
          {state.controllers.length === 0 ? (
            <PaneEmpty
              title="添加设备以远程控制这台 Mac"
              description={
                state.remoteControl ? "没有可用的已登录设备。" : "先允许发现并控制此设备，然后添加设备。"
              }
            />
          ) : (
            <div className="cx-pane__list">
              {state.controllers.map((device) => (
                <div key={device.id} className="cx-pane__list-item">
                  <div className="cx-pane__list-main">
                    <span className="cx-pane__list-title">{device.name}</span>
                    <span className="cx-pane__list-meta">{device.detail}</span>
                  </div>
                  <div className="cx-pane__list-actions">
                    <Button
                      size="sm"
                      variant="ghost"
                      color="danger"
                      onClick={() =>
                        patch((prev) => ({
                          ...prev,
                          controllers: prev.controllers.filter((item) => item.id !== device.id),
                        }))
                      }
                    >
                      移除
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </PaneCard>
      </PaneSection>

      <PaneSection title="来自这台 Mac 的 SSH 连接" description="通过 SSH 连接到远程设备">
        <PaneCard>
          <div className="cx-pane__toolbar">
            <span className="cx-pane__list-meta">
              {state.discoveryEmpty ? "未发现 SSH 连接" : "已扫描本机 ~/.ssh/config"}
            </span>
            <span className="cx-pane__toolbar-group">
              <Button size="sm" variant="soft" color="secondary" onClick={() => addDevice("ssh")}>
                添加 SSH 连接
              </Button>
              <Button
                size="sm"
                variant="ghost"
                color="secondary"
                onClick={() => patch({ discoveryEmpty: !state.discoveryEmpty })}
              >
                {state.discoveryEmpty ? "恢复扫描结果" : "模拟未发现"}
              </Button>
            </span>
          </div>
          {state.ssh.length === 0 ? (
            <PaneEmpty
              title="通过 SSH 连接到远程设备"
              description={
                state.discoveryEmpty
                  ? "未发现 SSH 连接。请先在 ~/.ssh/config 里配置主机。"
                  : "扫描到的 SSH 主机会显示在这里。"
              }
            />
          ) : (
            <div className="cx-pane__list">
              {state.ssh.map((device) => (
                <div key={device.id} className="cx-pane__list-item">
                  <div className="cx-pane__list-main">
                    <span className="cx-pane__list-title">{device.name}</span>
                    <span className="cx-pane__list-meta">{device.detail}</span>
                  </div>
                  <div className="cx-pane__list-actions">
                    <Button
                      size="sm"
                      variant="ghost"
                      color="danger"
                      onClick={() =>
                        patch((prev) => ({ ...prev, ssh: prev.ssh.filter((item) => item.id !== device.id) }))
                      }
                    >
                      断开
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </PaneCard>
      </PaneSection>

      <PaneSection title="WSL 连接">
        <PaneCard>
          {state.wsl.length === 0 ? (
            <PaneEmpty
              title="未找到设备连接。添加新连接即可开始使用"
              description="安装 WSL 发行版后，这里会列出可在 Codex 里打开的发行版。"
              action={
                <Button size="sm" variant="soft" color="secondary" onClick={() => addDevice("wsl")}>
                  添加 WSL 连接
                </Button>
              }
            />
          ) : (
            <div className="cx-pane__list">
              {state.wsl.map((device) => (
                <div key={device.id} className="cx-pane__list-item">
                  <div className="cx-pane__list-main">
                    <span className="cx-pane__list-title">{device.name}</span>
                    <span className="cx-pane__list-meta">{device.detail}</span>
                  </div>
                  <div className="cx-pane__list-actions">
                    <Button
                      size="sm"
                      variant="ghost"
                      color="danger"
                      onClick={() =>
                        patch((prev) => ({ ...prev, wsl: prev.wsl.filter((item) => item.id !== device.id) }))
                      }
                    >
                      移除
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </PaneCard>
      </PaneSection>
    </PaneShell>
  );
}
