import { useEffect, useState } from "react";

import {
  API_CONFIG_FIELDS,
  type ApiConfigField,
  type ConnectionTestResult,
  createApiClient,
  type ModelListResult,
  type ResolvedApiConfig,
  resetApiConfig,
  updateApiConfig,
  useApiConfig,
  validateApiConfig,
} from "@/api";
import { Input, Textarea } from "@/ui";

import {
  SettingsBadge,
  SettingsButton,
  SettingsField,
  SettingsSecretInput,
  SettingsSwitch,
} from "../controls";
import { SettingsCard, SettingsCardBody, SettingsRow, SettingsSection } from "../SettingsRow";

/**
 * 自定义 API —— **本还原工程新增页**（官方设置面没有这个分区，见 SPEC §6 对账表「附加」）。
 *
 * 它是一条**真链路**，不是展示页：
 *   读   useApiConfig()      —— @/api/config 的模块级 store（localStorage: codex.api）
 *   写   updateApiConfig()   —— 保存草稿（含请求头整体替换）
 *   校验 validateApiConfig() —— baseUrl / model / apiKey 的前端拦截，逐字段显示 error/warn
 *   打点 createApiClient(draft).testConnection() —— 先 GET /models，不通再退一步 1 token 对话探活
 *   拉模型 createApiClient(draft).listModels() —— 成功后点模型名即可写回 model 字段
 * 隐私：全部字段只写本机 localStorage（key = codex.api），除了你自己填的端点以外不发往任何地方。
 */

function describeTest(result: ConnectionTestResult): { tone: "ok" | "bad"; title: string; detail: string } {
  if (result.ok) {
    const models =
      result.mode === "models" ? `${result.models.length} 个模型` : "对话端点可用（/models 不可用）";
    return {
      tone: "ok",
      title: result.mode === "models" ? "连接成功 · /models 可用" : "连接成功 · 仅对话端点",
      detail: `耗时 ${result.latencyMs} ms · ${models}`,
    };
  }
  return {
    tone: "bad",
    title: `连接失败 · ${result.error?.kind ?? "unknown"}`,
    detail: `${result.error?.message ?? "未知错误"}（耗时 ${result.latencyMs} ms）`,
  };
}

/** 自定义请求头编辑器（pairs 顺序保持用户输入顺序；key 为空的行直接丢弃） */
function HeaderEditor({
  headers,
  onChange,
}: {
  headers: Record<string, string>;
  onChange: (next: Record<string, string>) => void;
}) {
  const entries = Object.entries(headers);
  const rewrite = (index: number, key: string, value: string) => {
    const next: [string, string][] = entries.map((entry, i) => (i === index ? [key, value] : entry));
    onChange(Object.fromEntries(next.filter(([name]) => name.trim() !== "")));
  };
  return (
    <div className="cx-settings-headers">
      {entries.length === 0 ? <p className="cx-settings-field__help">还没有自定义请求头。</p> : null}
      {entries.map(([key, value], index) => (
        <div className="cx-settings-headers__row" key={index}>
          <Input
            aria-label="请求头名称"
            onChange={(event) => rewrite(index, event.target.value, value)}
            placeholder="api-key"
            value={key}
          />
          <Input
            aria-label="请求头取值"
            onChange={(event) => rewrite(index, key, event.target.value)}
            placeholder="取值"
            value={value}
          />
          <SettingsButton onClick={() => onChange(Object.fromEntries(entries.filter((_, i) => i !== index)))}>
            删除
          </SettingsButton>
        </div>
      ))}
      <SettingsButton onClick={() => onChange({ ...headers, "": "" })}>添加请求头</SettingsButton>
    </div>
  );
}

export function ApiSection() {
  const stored = useApiConfig();
  const [draft, setDraft] = useState<ResolvedApiConfig>(stored);
  const [test, setTest] = useState<ConnectionTestResult | null>(null);
  const [testing, setTesting] = useState(false);
  const [models, setModels] = useState<ModelListResult | null>(null);
  const [loadingModels, setLoadingModels] = useState(false);

  // store 变了（保存 / 重置 / 其它标签页）就同步草稿
  useEffect(() => setDraft(stored), [stored]);

  const issues = validateApiConfig(draft);
  const issueFor = (key: keyof ResolvedApiConfig, level: "error" | "warn") =>
    issues.find((issue) => issue.field === key && issue.level === level)?.message;
  const dirty = JSON.stringify(draft) !== JSON.stringify(stored);

  const patch = (next: Partial<ResolvedApiConfig>) => setDraft((prev) => ({ ...prev, ...next }));

  const runTest = async () => {
    setTesting(true);
    try {
      // 用**草稿**打，不用已保存的配置：填完就能试，不用先保存
      const result = await createApiClient(draft).testConnection();
      setTest(result);
    } finally {
      setTesting(false);
    }
  };

  const runListModels = async () => {
    setLoadingModels(true);
    try {
      const result = await createApiClient(draft).listModels();
      setModels(result);
      // 拉到了就顺手更新测试结论的模型数，两处显示不打架
      setTest((prev) =>
        prev?.ok && result.ok ? { ...prev, models: result.models, latencyMs: result.latencyMs } : prev,
      );
    } finally {
      setLoadingModels(false);
    }
  };

  const renderField = (field: ApiConfigField) => {
    const value = draft[field.key];
    const id = `api-field-${field.key}`;
    switch (field.kind) {
      case "password":
        return (
          <SettingsField
            error={issueFor(field.key, "error")}
            help={field.help}
            htmlFor={id}
            key={field.key}
            label={field.label}
            warn={issueFor(field.key, "warn")}
          >
            <SettingsSecretInput
              id={id}
              label={field.label}
              onChange={(next) => patch({ apiKey: next })}
              placeholder={field.placeholder}
              value={typeof value === "string" ? value : ""}
            />
          </SettingsField>
        );
      case "textarea":
        return (
          <SettingsField
            error={issueFor(field.key, "error")}
            help={field.help}
            htmlFor={id}
            key={field.key}
            label={field.label}
            warn={issueFor(field.key, "warn")}
          >
            <Textarea
              aria-label={field.label}
              id={id}
              onChange={(event) => patch({ [field.key]: event.target.value } as Partial<ResolvedApiConfig>)}
              placeholder={field.placeholder}
              rows={3}
              value={typeof value === "string" ? value : ""}
            />
          </SettingsField>
        );
      case "switch":
        return (
          <SettingsField
            error={issueFor(field.key, "error")}
            help={field.help}
            key={field.key}
            label={field.label}
            warn={issueFor(field.key, "warn")}
          >
            <SettingsSwitch
              checked={Boolean(value)}
              label={field.label}
              onChange={(checked) => patch({ [field.key]: checked } as Partial<ResolvedApiConfig>)}
            />
          </SettingsField>
        );
      case "headers":
        return (
          <SettingsField
            error={issueFor(field.key, "error")}
            help={field.help}
            key={field.key}
            label={field.label}
            warn={issueFor(field.key, "warn")}
          >
            <HeaderEditor headers={draft.headers} onChange={(next) => patch({ headers: next })} />
          </SettingsField>
        );
      case "number":
        return (
          <SettingsField
            error={issueFor(field.key, "error")}
            help={field.help}
            htmlFor={id}
            key={field.key}
            label={field.label}
            warn={issueFor(field.key, "warn")}
          >
            <Input
              aria-label={field.label}
              id={id}
              inputMode="numeric"
              onChange={(event) => {
                const raw = event.target.value.trim();
                // 留空 = 完全不发送该字段（temperature / maxTokens），或回落默认值（两个超时）
                const numeric = raw === "" ? null : Number(raw);
                if (numeric !== null && !Number.isFinite(numeric)) return;
                patch(
                  field.key === "timeoutMs" || field.key === "idleTimeoutMs"
                    ? ({ [field.key]: numeric ?? 0 } as Partial<ResolvedApiConfig>)
                    : ({ [field.key]: numeric } as Partial<ResolvedApiConfig>),
                );
              }}
              placeholder={field.placeholder}
              type="text"
              value={value === null || value === undefined ? "" : String(value)}
            />
          </SettingsField>
        );
      default:
        return (
          <SettingsField
            error={issueFor(field.key, "error")}
            help={field.help}
            htmlFor={id}
            key={field.key}
            label={field.label}
            warn={issueFor(field.key, "warn")}
          >
            <Input
              aria-label={field.label}
              id={id}
              onChange={(event) => patch({ [field.key]: event.target.value } as Partial<ResolvedApiConfig>)}
              placeholder={field.placeholder}
              value={typeof value === "string" ? value : ""}
            />
          </SettingsField>
        );
    }
  };

  const basicFields = API_CONFIG_FIELDS.filter((field) => !field.advanced);
  const advancedFields = API_CONFIG_FIELDS.filter((field) => field.advanced);

  return (
    <>
      <SettingsSection
        tag={<SettingsBadge tone="warn">附加 · 官方无此分区（SPEC §6 对账表）</SettingsBadge>}
        title="自定义 API"
      >
        <SettingsCard>
          <SettingsCardBody>
            <p className="cx-settings-note">
              这里的每一项都只写本机 <code>localStorage</code>（键 <code>codex.api</code>），
              <strong>不会上传到任何地方</strong>；除了你自己填的端点地址，本页不发任何网络请求。
              对话（src/chat/runtime）每次发送时读的就是这份配置，改完立即生效。
            </p>
            {issues.length > 0 ? (
              <ul className="cx-settings-issues">
                {issues.map((issue) => (
                  <li data-level={issue.level} key={issue.field + issue.message}>
                    {issue.level === "error" ? "错误" : "提示"}：{issue.message}
                  </li>
                ))}
              </ul>
            ) : (
              <p className="cx-settings-note" data-tone="ok">
                校验通过：地址与模型名都填好了。
              </p>
            )}
          </SettingsCardBody>
        </SettingsCard>
      </SettingsSection>

      <SettingsSection title="连接">
        <SettingsCard>
          <SettingsCardBody>
            <div className="cx-settings-fields">{basicFields.map(renderField)}</div>
          </SettingsCardBody>
        </SettingsCard>
      </SettingsSection>

      <SettingsSection
        tag={<SettingsBadge>工程自定字段（@/api/config.ts 的 API_CONFIG_FIELDS）</SettingsBadge>}
        title="高级"
      >
        <SettingsCard>
          <SettingsCardBody>
            <div className="cx-settings-fields">{advancedFields.map(renderField)}</div>
          </SettingsCardBody>
        </SettingsCard>
      </SettingsSection>

      <SettingsSection title="测试与模型">
        <SettingsCard>
          <SettingsRow
            control={
              <SettingsButton disabled={testing} onClick={runTest}>
                {testing ? "测试中…" : "测试连接"}
              </SettingsButton>
            }
            description="先 GET /models；不支持 /models 的兼容服务会退一步做一次 1 token 的对话探活"
            label="测试连接"
          />
          <SettingsRow
            control={
              <SettingsButton disabled={loadingModels} onClick={runListModels}>
                {loadingModels ? "拉取中…" : "拉取模型列表"}
              </SettingsButton>
            }
            description="成功后下面会列出模型，点一个即可写回「模型」字段"
            label="模型列表"
          />
          {test ? (
            <SettingsCardBody>
              <div className="cx-settings-test" data-tone={describeTest(test).tone}>
                <div className="cx-settings-test__title">{describeTest(test).title}</div>
                <div className="cx-settings-test__detail">{describeTest(test).detail}</div>
              </div>
            </SettingsCardBody>
          ) : null}
          {models ? (
            <SettingsCardBody>
              {models.ok ? (
                <>
                  <p className="cx-settings-note">
                    拉到 {models.models.length} 个模型（耗时 {models.latencyMs} ms）。点一个写入「模型」字段：
                  </p>
                  <div className="cx-settings-models">
                    {models.models.map((model) => (
                      <button
                        className="cx-settings-model"
                        data-selected={draft.model === model.id ? "" : undefined}
                        key={model.id}
                        onClick={() => patch({ model: model.id })}
                        type="button"
                      >
                        {model.id}
                      </button>
                    ))}
                  </div>
                </>
              ) : (
                <div className="cx-settings-test" data-tone="bad">
                  <div className="cx-settings-test__title">拉取失败 · {models.error?.kind ?? "unknown"}</div>
                  <div className="cx-settings-test__detail">
                    {models.error?.message ?? "未知错误"}（耗时 {models.latencyMs} ms）
                  </div>
                </div>
              )}
            </SettingsCardBody>
          ) : null}
          <SettingsRow
            control={
              <>
                <SettingsButton disabled={!dirty} onClick={() => updateApiConfig(draft)}>
                  保存
                </SettingsButton>
                <SettingsButton
                  onClick={() => {
                    resetApiConfig();
                    setTest(null);
                    setModels(null);
                  }}
                >
                  清空
                </SettingsButton>
              </>
            }
            description="保存写 localStorage（codex.api）；清空恢复默认空配置。草稿未保存时「测试连接」用的仍是草稿。"
            label="保存配置"
          />
        </SettingsCard>
      </SettingsSection>
    </>
  );
}
