import { Button, Slider } from "@/ui";
import type { SettingsPaneProps } from "./index";
import { PaneCard, PaneEmpty, PaneRow, PaneSection, PaneSelect, PaneShell, PaneSwitch } from "./pane-kit";
import { usePaneState } from "./pane-state";

/**
 * Mini 与虚拟宠物（官方 slug pets，chunk pets-settings-route-d7a08048b9e7.js，53 条消息）。
 *
 * 行证据（官方 zh-CN）：
 *   settings.mini.pets.title「我的虚拟宠物」/ settings.pets.pickPet.title「选择一只虚拟宠物」
 *     / .pickPet.miniDescription「Mini 管理对话，并提示需要关注的事项」
 *   settings.mini.pets.none.title「无」/ .barOnly.description「轻量级 Codex 小伙伴」
 *   settings.pets.appearance.title「外观」
 *   settings.pets.size「虚拟宠物大小」/ .description「调整虚拟宠物大小」/ .reset「重置」
 *   settings.pets.visibility「可见性」/ .description「选择让 Mini 常驻桌面还是按需显示」
 *     / .alwaysVisible「始终可见」+ .alwaysVisible.description「在桌面上始终显示 Mini」
 *     / .onDemand「按需显示」+ .onDemand.descriptionWithoutShortcut「通过菜单显示，点击其他位置时隐藏。」
 *   settings.mini.show「显示 Mini」/ settings.mini.hide「隐藏 Mini」
 *   settings.mini.descriptionWithoutShortcut「虚拟宠物可让你快速访问 ChatGPT」
 *   settings.pets.custom.title「自定义虚拟宠物」/ .custom.create.label「创建你的专属虚拟宠物」
 *     / .custom.create.title「创建」/ .custom.openFolder「打开文件夹」/ .refresh「刷新」
 *     / .preview.customize.title「自定义虚拟宠物」
 *
 * 此页无实测几何，按通用规格推导（SPEC §8.1）；外观取值官方未取证（§8.2）→ 选项标注为推导。
 */

interface MiniPaneState {
  pet: string;
  appearance: string;
  size: number;
  visibility: string;
  showMini: boolean;
  customName: string;
}

const DEFAULTS: MiniPaneState = {
  pet: "barOnly",
  appearance: "default",
  size: 1,
  visibility: "onDemand",
  showMini: true,
  customName: "",
};

const PETS = [
  { value: "none", label: "无" },
  { value: "barOnly", label: "轻量级 Codex 小伙伴", description: "Mini 管理对话，并提示需要关注的事项" },
  { value: "custom", label: "自定义虚拟宠物", description: "使用你自己的宠物资源包" },
];

/** 外观取值官方未取证（§8.2）→ 三个选项为演绎值，仅用于本地自洽 */
const APPEARANCES = [
  { value: "default", label: "默认" },
  { value: "warm", label: "暖色" },
  { value: "cool", label: "冷色" },
];

const VISIBILITY = [
  { value: "alwaysVisible", label: "始终可见", description: "在桌面上始终显示 Mini" },
  { value: "onDemand", label: "按需显示", description: "通过菜单显示，点击其他位置时隐藏。" },
];

export function MiniPetsPane({ section }: SettingsPaneProps) {
  const [state, patch, reset] = usePaneState(section, DEFAULTS);
  const scale = 0.6 + state.size * 0.4;

  return (
    <PaneShell
      section={section}
      title="Mini 与虚拟宠物"
      lede="虚拟宠物可让你快速访问 ChatGPT；Mini 管理对话，并提示需要关注的事项。"
      actions={
        <Button size="sm" variant="soft" color="secondary" onClick={reset}>
          恢复默认
        </Button>
      }
    >
      <PaneSection title="我的虚拟宠物">
        <PaneCard>
          <PaneRow
            label="选择一只虚拟宠物"
            description="虚拟宠物显示在桌面角落，可随时隐藏"
            control={
              <PaneSelect
                ariaLabel="选择一只虚拟宠物"
                value={state.pet}
                onChange={(value) => patch({ pet: value })}
                options={PETS}
              />
            }
          />
          <PaneRow
            label="外观"
            description="切换宠物的配色方案（外观取值官方未取证，此处为演绎值）"
            control={
              <span className="cx-pane__chips">
                {APPEARANCES.map((item) => (
                  <button
                    key={item.value}
                    type="button"
                    className="cx-pane__chip"
                    data-selected={state.appearance === item.value ? "" : undefined}
                    onClick={() => patch({ appearance: item.value })}
                  >
                    {item.label}
                  </button>
                ))}
              </span>
            }
          />
          <PaneRow
            block
            label="虚拟宠物大小"
            description="调整虚拟宠物大小"
            control={
              <span className="cx-pane__input-group" style={{ width: "100%" }}>
                <Slider
                  aria-label="虚拟宠物大小"
                  min={0.5}
                  max={2}
                  step={0.5}
                  value={[state.size]}
                  onValueChange={(value) => patch({ size: value[0] ?? 1 })}
                />
                <span className="cx-pane__list-meta">{state.size.toFixed(1)}×</span>
                <Button size="sm" variant="ghost" color="secondary" onClick={() => patch({ size: 1 })}>
                  重置
                </Button>
              </span>
            }
          />
          <PaneRow
            label="可见性"
            description="选择让 Mini 常驻桌面还是按需显示"
            control={
              <PaneSelect
                ariaLabel="可见性"
                value={state.visibility}
                onChange={(value) => patch({ visibility: value })}
                options={VISIBILITY}
              />
            }
          />
          <PaneRow
            label={state.showMini ? "隐藏 Mini" : "显示 Mini"}
            description="立即隐藏或显示桌面上的虚拟宠物"
            control={
              <PaneSwitch
                label={state.showMini ? "隐藏 Mini" : "显示 Mini"}
                checked={state.showMini}
                onChange={(checked) => patch({ showMini: checked })}
              />
            }
          />
        </PaneCard>
      </PaneSection>

      <PaneSection title="预览">
        <PaneCard>
          <PaneRow
            block
            label="虚拟宠物预览"
            description={
              "当前：" +
              (PETS.find((item) => item.value === state.pet)?.label ?? "无") +
              " · " +
              state.appearance +
              " · " +
              state.size.toFixed(1) +
              "×"
            }
            control={
              <div className="cx-pane__preview" data-appearance={state.appearance}>
                {state.pet === "none" || !state.showMini ? (
                  <PaneEmpty
                    title="未显示虚拟宠物"
                    description="选择一只宠物并打开「显示 Mini」后，预览会出现在这里。"
                  />
                ) : (
                  <div
                    aria-label="虚拟宠物预览"
                    role="img"
                    style={{
                      width: 72,
                      height: 72,
                      transform: `scale(${scale.toFixed(2)})`,
                      borderRadius: "42% 58% 55% 45% / 48% 43% 57% 52%",
                      background:
                        state.appearance === "warm"
                          ? "color-mix(in oklab, var(--color-text-caution) 70%, transparent)"
                          : state.appearance === "cool"
                            ? "color-mix(in oklab, var(--color-text-info) 70%, transparent)"
                            : "color-mix(in oklab, var(--color-text) 60%, transparent)",
                    }}
                  />
                )}
              </div>
            }
          />
        </PaneCard>
      </PaneSection>

      <PaneSection title="自定义虚拟宠物">
        <PaneCard>
          <PaneRow
            label="创建你的专属虚拟宠物"
            description="从图片文件夹生成一只自定义宠物；创建后可以在「我的虚拟宠物」里选择它"
            control={
              <Button
                size="sm"
                variant="soft"
                color="secondary"
                onClick={() => patch({ pet: "custom", customName: state.customName || "我的宠物" })}
              >
                创建
              </Button>
            }
          />
          <PaneRow
            label="打开文件夹"
            description="打开虚拟宠物资源目录，直接放入或替换素材"
            control={
              <Button
                size="sm"
                variant="ghost"
                color="secondary"
                onClick={() => patch({ appearance: "default" })}
              >
                打开文件夹
              </Button>
            }
          />
          <PaneRow
            label="刷新"
            description="重新扫描虚拟宠物目录（正在加载自定义虚拟宠物…）"
            control={
              <Button size="sm" variant="ghost" color="secondary" onClick={() => patch({ customName: "" })}>
                刷新
              </Button>
            }
          />
          {state.customName ? (
            <PaneRow
              label={state.customName}
              description="自定义虚拟宠物已就绪，可在「我的虚拟宠物」里选中"
              control={<span className="cx-pane__chip">自定义</span>}
            />
          ) : null}
        </PaneCard>
      </PaneSection>
    </PaneShell>
  );
}
