/** 行 3 的「更改」：官方是原生文件夹选择器（未实测控件名），这里用输入框改写路径 */
function FolderDialog({ value, onChange }: { value: string; onChange: (next: string) => void }) {
  const [draft, setDraft] = useState(value);
  return (
    <Dialog onOpenChange={(open) => open && setDraft(value)}>
      <DialogTrigger asChild>
        <SettingsButton>更改</SettingsButton>
      </DialogTrigger>
      <DialogContent
        description="在项目外启动的任务默认存储数据的位置（官方为文件选择器，本工程用路径输入框）"
        footer={
          <>
            <DialogClose asChild>
              <Button size="sm" variant="ghost">
                取消
              </Button>
            </DialogClose>
            <DialogClose asChild>
              <Button onClick={() => onChange(draft.trim())} size="sm" variant="solid">
                保存
              </Button>
            </DialogClose>
          </>
        }
        title="无项目任务文件夹"
      >
        <Input
          aria-label="无项目任务文件夹路径"
          onChange={(event) => setDraft(event.target.value)}
          placeholder={DEFAULT_PROJECTLESS_CHAT_FOLDER}
          value={draft}
        />
      </DialogContent>
    </Dialog>
  );
}

/**
 * 行 2「完整访问权限」开关的**确认弹窗**（官方 general-settings-c429ae79df7c.js 里的 `bo` 组件）。
 *
 * 官方行为（同一 chunk）：`onChange = e => { if (e) { setOpen(true); return } setEnabled(false) }`
 *   —— **开启必须先过确认弹窗，关闭直接生效**。弹窗确认后才把这一项设为开。
 * 官方文案逐条（id 与 zh-CN 译文一一对应，出处 zh-CN-b05cfd55c534.js）：
 *   · `settings.agent.permissionsMode.fullAccess.confirm.title` = 「要启用完整访问权限吗？」
 *   · `…confirm.body` = 「选中后，ChatGPT 可以访问互联网，并在无需请求批准的情况下读取和编辑文件，包括执行可能具有破坏性的命令」
 *   · `…confirm.availabilityDescription` = 「开启后会将“完整访问权限”添加到权限菜单中，但不会开启“完整访问权限”。<a>了解更多</a>」
 *   · `…confirm.cancel` = 「取消」/ `…confirm.confirm` = 「确认」
 * ⚠️ 官方标题左侧还有一个图标（chunk 里的组件名 `hi`，class `icon-sm`）——**官方名未解析**，
 *    故这里不加图标（宁缺勿造）。正文两段式（body + availability）照官方顺序。
 */
function FullAccessConfirmDialog({
  open,
  onOpenChange,
  onConfirm,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onConfirm: () => void;
}) {
  return (
    <Dialog onOpenChange={onOpenChange} open={open}>
      <DialogContent
        description="选中后，ChatGPT 可以访问互联网，并在无需请求批准的情况下读取和编辑文件，包括执行可能具有破坏性的命令"
        footer={
          <>
            <DialogClose asChild>
              <Button color="secondary" size="sm" variant="ghost">
                取消
              </Button>
            </DialogClose>
            <Button color="primary" onClick={onConfirm} size="sm" variant="solid">
              确认
            </Button>
          </>
        }
        title="要启用完整访问权限吗？"
      >
        <p>
          开启后会将“完整访问权限”添加到权限菜单中，但不会开启“完整访问权限”。
          <a
            className="cx-settings-link"
            href="https://developers.openai.com/codex/"
            rel="noreferrer"
            target="_blank"
          >
            了解更多
          </a>
        </p>
      </DialogContent>
    </Dialog>
  );
}

