const params = new URLSearchParams(location.search);
const live = params.get("live") ?? "all";
const show = (name: string) => live === "all" || live === name;
/** live=<某个弹层> 时只渲染那一节：Radix 弹层锚在触发器旁，滚动会让固定层对不上，聚焦模式免掉这一层麻烦 */
const specimensOnly = live === "none" || live === "all";
/**
 * 弹层标本是否**默认展开**。
 *
 * 应用页面（/controls）默认 = false：Radix 弹层 portal 到 body，若一进页面就有
 * 对话框 / 菜单 / 下拉全部展开，会把下面的标本整片盖住 —— 用户要求「布局整齐、
 * 可滚动浏览、有可操作性」，所以页面里它们**点开才出现**（触发按钮本身就是标本）。
 * dev 自测台要复现「全部展开」的旧形态时加查询参数 open=1（量测脚本用）。
 */
const autoOpen = params.get("open") === "1";

function Cell({ label, bench, children }: { label: string; bench?: string; children: ReactNode }) {
  return (
    <div className="bench-cell">
      <span className="bench-label">{label}</span>
      <div className="bench-stage" data-bench={bench}>
        {children}
      </div>
    </div>
  );
}

function Section({ title, children }: { title: string; children: ReactNode }) {
  return (
    <section className="bench-section">
      <h2>{title}</h2>
      <div className="bench-row">{children}</div>
    </section>
  );
}

