import { Button } from "@/ui";
import type { SettingsPaneProps } from "./index";
import {
  PaneCard,
  PaneConfirmAction,
  PaneRow,
  PaneSection,
  PaneSelect,
  PaneShell,
  PaneSwitch,
  PaneTabs,
  PaneTextBlock,
  PaneValueText,
} from "./pane-kit";
import { usePaneState } from "./pane-state";

/**
 * 配置（官方 slug agent，导航第 6 项「配置」，图标 terminal-shield-light-16，SPEC §3）。
 * 本页挂在 pane 契约的 profile 键上（键名由 index.ts 固定，SPEC 里的官方 slug 是 agent）。
 *
 * 行证据（官方 zh-CN，来自 app-primary + general-settings 两个 chunk 的 settings.agent.*）：
 *   settings.agent.agentDefaults.sectionTitle「智能体默认设置」
 *   settings.agent.permissionsMode.default.description（默认权限）
 *   settings.agent.permissionsMode.fullAccess.confirm.title「要启用完整访问权限吗？」/ .body / .confirm「确认」/ .cancel「取消」
 *   settings.agent.speed.label「速度」/ .description「选择 ChatGPT 在聊天、子智能体和压缩中的运行速度」
 *     / .fast.description「速度更快，用量更高」
 *   settings.agent.configuration.approval.label「批准策略」+ option.untrusted「不可信」/ option.onFailure「失败时」
 *     / option.onRequest「按请求」/ option.never「从不请求审批」
 *   settings.agent.configuration.sandbox.label「沙盒设置」+ option.readOnly「只读」
 *     / option.workspaceWrite「工作空间写入」/ option.fullAccess「完整访问权限」
 *   settings.agent.configuration.network.label「允许网络访问」
 *   settings.agent.configuration.reasoningSummary.label「推理摘要」+ option.auto/concise/detailed/none（自动/简洁/详细/无）
 *   settings.agent.configuration.modelVerbosity.label「输出详细程度」+ option.low/medium/high（低/中/高）
 *   settings.agent.configuration.webSearch.label「网页搜索」+ option.disabled/cached/indexed/live（禁用/缓存/索引/实时）
 *   settings.agent.configuration.scope.user「用户配置」/ .projectGroup「项目配置」/ .globalGroup「全局配置」
 *     / .managed「管理员配置」
 *   settings.agent.customConfig.sectionTitle「自定义 config.toml 设置」
 *   settings.agent.dependencies.sectionTitle「工作空间依赖项」/ .enabled.label「Codex 依赖项」
 *     / .bundleVersion.label「当前版本：」/ .diagnose.label「诊断 Codex 工作空间中的问题」
 *     / .reset.label「重置并安装工作空间」
 *
 * 此页无实测几何，按通用规格推导（SPEC §8.1）；控件当前值官方无证据（§8.2），
 * 默认值按官方文案语义取保守项，持久化在 cx.pane.profile。
 */

interface ConfigPaneState {
  defaultPermissions: boolean;
  fullAccess: boolean;
  scope: string;
  speed: string;
  approval: string;
  sandbox: string;
  network: boolean;
  reasoningSummary: string;
  verbosity: string;
  webSearch: string;
  dependencies: boolean;
  configToml: string;
  diagnoseRun: boolean;
}

const DEFAULTS: ConfigPaneState = {
  defaultPermissions: true,
  fullAccess: false,
  scope: "user",
  speed: "default",
  approval: "onRequest",
  sandbox: "workspaceWrite",
  network: true,
  reasoningSummary: "auto",
  verbosity: "medium",
  webSearch: "cached",
  dependencies: true,
  configToml: "",
  diagnoseRun: false,
};

const SCOPES = [
  { value: "user", label: "用户配置" },
  { value: "project", label: "项目配置" },
  { value: "global", label: "全局配置" },
  { value: "managed", label: "管理员配置" },
];

const SPEEDS = [
  { value: "default", label: "标准" },
  { value: "fast", label: "快速", description: "速度更快，用量更高" },
];

const APPROVALS = [
  { value: "untrusted", label: "不可信" },
  { value: "onFailure", label: "失败时" },
  { value: "onRequest", label: "按请求" },
  { value: "never", label: "从不请求审批" },
];

const SANDBOXES = [
  { value: "readOnly", label: "只读" },
  { value: "workspaceWrite", label: "工作空间写入" },
  { value: "fullAccess", label: "完整访问权限" },
];

const REASONING = [
  { value: "auto", label: "自动", description: "让模型选择摘要详细程度" },
  { value: "concise", label: "简洁", description: "显示简要推理摘要" },
  { value: "detailed", label: "详细", description: "显示更详细的推理摘要" },
  { value: "none", label: "无", description: "不显示推理摘要" },
];

const VERBOSITY = [
  { value: "low", label: "低", description: "保持回复简洁" },
  { value: "medium", label: "中", description: "兼顾细节与简洁" },
  { value: "high", label: "高", description: "在回复中包含更多细节" },
];

const WEB_SEARCH = [
  { value: "disabled", label: "禁用", description: "不允许网页搜索" },
  { value: "cached", label: "缓存", description: "使用 OpenAI 维护的搜索索引" },
  { value: "indexed", label: "索引", description: "允许访问已索引的外部网页" },
  { value: "live", label: "实时", description: "允许不受限制地访问当前网页" },
];

export function ConfigPane({ section }: SettingsPaneProps) {
  const [state, patch, reset] = usePaneState(section, DEFAULTS);

  return (
    <PaneShell
      section={section}
      title="配置"
      lede="Codex 智能体的默认权限、模型行为与工作空间依赖项；这里的改动对之后的新会话生效。"
      actions={
        <Button size="sm" variant="soft" color="secondary" onClick={reset}>
          恢复默认
        </Button>
      }
    >
      <PaneSection title="权限">
        <PaneCard>
          <PaneRow
            label="默认权限"
            description="默认情况下，ChatGPT 可以读取和编辑其工作空间中的文件。需要时，它可以请求额外访问权限"
            control={
              <PaneSwitch
                label="默认权限"
                checked={state.defaultPermissions}
                onChange={(checked) => patch({ defaultPermissions: checked })}
              />
            }
          />
          <PaneRow
            label="完整访问权限"
            description="开启后 ChatGPT 无需批准即可编辑电脑上的任意文件，并运行可访问网络的命令。此选项只是把它加入权限菜单，不会自动开启。"
            control={
              <PaneConfirmAction
                confirmLabel="确认"
                cancelLabel="取消"
                title="要启用完整访问权限吗？"
                description="选中后，ChatGPT 可以访问互联网，并在无需请求批准的情况下读取和编辑文件，包括执行可能具有破坏性的命令。"
                onConfirm={() => patch({ fullAccess: true })}
                trigger={
                  <PaneSwitch
                    label="完整访问权限"
                    checked={state.fullAccess}
                    onChange={(checked) => {
                      if (!checked) patch({ fullAccess: false });
                    }}
                  />
                }
              />
            }
          />
        </PaneCard>
      </PaneSection>

      <PaneSection
        title="智能体默认设置"
        description="配置范围决定这组默认值写进哪一层配置。"
        actions={
          <PaneTabs
            ariaLabel="配置范围"
            tabs={SCOPES}
            value={state.scope}
            onChange={(value) => patch({ scope: value })}
          />
        }
      >
        <PaneCard>
          <PaneRow
            label="速度"
            description="选择 ChatGPT 在聊天、子智能体和压缩中的运行速度"
            control={
              <PaneSelect
                ariaLabel="速度"
                value={state.speed}
                onChange={(value) => patch({ speed: value })}
                options={SPEEDS}
              />
            }
          />
          <PaneRow
            label="批准策略"
            description="决定 Codex 什么时候需要你确认命令"
            control={
              <PaneSelect
                ariaLabel="批准策略"
                value={state.approval}
                onChange={(value) => patch({ approval: value })}
                options={APPROVALS}
              />
            }
          />
          <PaneRow
            label="沙盒设置"
            description="限制 Codex 能写入的范围"
            control={
              <PaneSelect
                ariaLabel="沙盒设置"
                value={state.sandbox}
                onChange={(value) => patch({ sandbox: value })}
                options={SANDBOXES}
              />
            }
          />
          <PaneRow
            label="允许网络访问"
            description="允许沙盒内的命令访问网络"
            control={
              <PaneSwitch
                label="允许网络访问"
                checked={state.network}
                disabled={state.sandbox === "readOnly"}
                onChange={(checked) => patch({ network: checked })}
              />
            }
          />
          <PaneRow
            label="推理摘要"
            description="控制推理过程在对话里的展开程度"
            control={
              <PaneSelect
                ariaLabel="推理摘要"
                value={state.reasoningSummary}
                onChange={(value) => patch({ reasoningSummary: value })}
                options={REASONING}
              />
            }
          />
          <PaneRow
            label="输出详细程度"
            description="控制模型回复的默认篇幅"
            control={
              <PaneSelect
                ariaLabel="输出详细程度"
                value={state.verbosity}
                onChange={(value) => patch({ verbosity: value })}
                options={VERBOSITY}
              />
            }
          />
          <PaneRow
            label="网页搜索"
            description="选择 Codex 使用哪种网页搜索通道"
            control={
              <PaneSelect
                ariaLabel="网页搜索"
                value={state.webSearch}
                onChange={(value) => patch({ webSearch: value })}
                options={WEB_SEARCH}
              />
            }
          />
        </PaneCard>
      </PaneSection>

      <PaneSection title="工作空间依赖项">
        <PaneCard>
          <PaneRow
            label="Codex 依赖项"
            description="在打开的每个工作空间里同步安装 Codex 需要的运行时依赖"
            control={
              <PaneSwitch
                label="Codex 依赖项"
                checked={state.dependencies}
                onChange={(checked) => patch({ dependencies: checked })}
              />
            }
          />
          <PaneRow
            label="当前版本："
            description="本机已安装的依赖包版本（官方 bundleVersion.label，未实测具体值）"
            control={<PaneValueText value="未实测" mono />}
          />
          <PaneRow
            label="诊断 Codex 工作空间中的问题"
            description="检查依赖、权限与配置文件，并输出一份诊断结果"
            control={
              <Button
                size="sm"
                variant="soft"
                color="secondary"
                onClick={() => patch({ diagnoseRun: !state.diagnoseRun })}
              >
                {state.diagnoseRun ? "已完成诊断" : "开始诊断"}
              </Button>
            }
          />
          <PaneRow
            label="重置并安装工作空间"
            description="清空当前工作空间的依赖安装状态，然后重新安装"
            control={
              <PaneConfirmAction
                danger
                confirmLabel="重置并安装"
                title="重置并安装工作空间？"
                description="这会删除已安装的依赖目录并重新安装，期间工作空间内的命令可能不可用。"
                onConfirm={() => patch({ dependencies: true })}
                trigger={
                  <Button size="sm" variant="soft" color="danger">
                    重置并安装
                  </Button>
                }
              />
            }
          />
        </PaneCard>
      </PaneSection>

      <PaneSection title="自定义 config.toml 设置">
        <PaneCard>
          <PaneTextBlock
            label="config.toml 片段"
            description="直接追加到 Codex 的 config.toml；与上面的图形化设置冲突时以此处为准"
            ariaLabel="config.toml 片段"
            placeholder="[model_providers.local]&#10;name = &quot;本地&quot;"
            rows={6}
            value={state.configToml}
            onChange={(value) => patch({ configToml: value })}
            footer={
              <span className="cx-pane__hint">
                {state.configToml.split("\n").length} 行 · 保存后对新会话生效
              </span>
            }
          />
        </PaneCard>
      </PaneSection>
    </PaneShell>
  );
}
