import { useState } from "react";

import { Button, Input } from "@/ui";
import type { SettingsPaneProps } from "./index";
import { PaneCard, PaneConfirmAction, PaneEmpty, PaneRow, PaneSection, PaneShell } from "./pane-kit";
import { newPaneId, usePaneState } from "./pane-state";

/**
 * Archived chats（官方 slug archived-chats / 注册表里同时存在 data-controls，
 * chunk data-controls-settings-894f4c14b14c.js，40 条消息）。
 *
 * 证据（官方 zh-CN）：
 *   settings.chatGpt.dataControls.archivedChats「已归档的聊天」
 *   settings.chatGpt.dataControls.archiveAll「归档所有聊天」
 *     + .archiveConfirmTitle「归档所有聊天？」/ .archiveConfirmDescription「你可以在“数据管理”中管理已归档的聊天。」
 *   settings.dataControls.archivedChats.deleteConfirm.title「删除已归档的聊天？」（SPEC §4.2.3）
 *   settings.dataControls.archivedChats.deleteProjectConfirm.title「删除该项目中的所有聊天？」（同上）
 *   settings.dataControls.archivedChats.deleteAllConfirm.title「删除所有已归档本地聊天？」（同上）
 *   settings.chatGpt.dataControls.export.label「导出数据」/ .export.dialog.title「要请求导出数据吗？」
 *
 * 页面主体是列表 + 删除（53 条 archivedChats.* 消息），行数随列表长度动态 → 官方行数未实测
 * （SPEC §4.2.3）。此页无实测几何，按通用规格推导（§8.1）。
 * 列表初值官方无证据（§8.2）→ 默认空列表 + 空态；「添加已归档聊天」用于演示列表态。
 */

interface ArchivedChat {
  id: string;
  title: string;
  project: string;
  archivedAt: string;
}

interface ArchivedPaneState {
  chats: ArchivedChat[];
  query: string;
}

const DEFAULTS: ArchivedPaneState = { chats: [], query: "" };

const DEMO_CHATS: ArchivedChat[] = [
  { id: "chat-1", title: "重构设置页导航", project: "codex-desktop-src", archivedAt: "2 天前" },
  { id: "chat-2", title: "修复 CDP 截图脚本", project: "artex", archivedAt: "上周" },
];

export function ArchivedChatsPane({ section }: SettingsPaneProps) {
  const [state, patch, reset] = usePaneState(section, DEFAULTS);
  const [showAll, setShowAll] = useState(false);

  const keyword = state.query.trim().toLowerCase();
  const visible = keyword
    ? state.chats.filter((chat) => `${chat.title} ${chat.project}`.toLowerCase().includes(keyword))
    : state.chats;

  return (
    <PaneShell
      section={section}
      title="Archived chats"
      lede="已归档的聊天不会出现在侧栏，但内容仍保留在本机；可以在这里恢复或彻底删除。"
      actions={
        <>
          <Button size="sm" variant="soft" color="secondary" onClick={reset}>
            重置
          </Button>
          <Button
            size="sm"
            variant="soft"
            color="secondary"
            onClick={() => patch({ chats: state.chats.length > 0 ? state.chats : DEMO_CHATS })}
          >
            添加已归档聊天
          </Button>
        </>
      }
    >
      <PaneSection title="已归档的聊天" description={`${String(state.chats.length)} 个会话`}>
        <PaneCard>
          <div className="cx-pane__toolbar">
            <Input
              size="sm"
              className="cx-pane__input cx-pane__input--w240"
              aria-label="搜索已归档的聊天"
              placeholder="搜索已归档的聊天"
              value={state.query}
              onChange={(event) => patch({ query: event.target.value })}
            />
            <div className="cx-pane__toolbar-group">
              <PaneConfirmAction
                confirmLabel="归档所有聊天"
                title="归档所有聊天？"
                description="你可以在“数据管理”中管理已归档的聊天。"
                onConfirm={() => setShowAll(true)}
                trigger={
                  <Button size="sm" variant="soft" color="secondary">
                    归档所有聊天
                  </Button>
                }
              />
              <PaneConfirmAction
                danger
                confirmLabel="删除全部"
                title="删除所有已归档本地聊天？"
                description="此操作删除本机保存的全部已归档聊天，无法撤销。"
                onConfirm={() => patch({ chats: [] })}
                trigger={
                  <Button size="sm" variant="soft" color="danger" disabled={state.chats.length === 0}>
                    删除全部
                  </Button>
                }
              />
            </div>
          </div>
          {showAll ? (
            <PaneRow
              label="全部聊天已归档"
              description="侧栏里的历史会话已移入已归档列表，可以随时恢复。"
              control={
                <Button size="sm" variant="ghost" color="secondary" onClick={() => setShowAll(false)}>
                  撤销
                </Button>
              }
            />
          ) : null}
          {visible.length === 0 ? (
            <PaneEmpty
              title={keyword ? "未找到已归档的聊天" : "没有已归档的聊天"}
              description={
                keyword
                  ? "换一个关键词，或清空搜索框查看全部已归档聊天。"
                  : "在侧栏里对任意会话选择「归档」，它就会出现在这里。"
              }
            />
          ) : (
            <div className="cx-pane__list">
              {visible.map((chat) => (
                <div key={chat.id} className="cx-pane__list-item">
                  <div className="cx-pane__list-main">
                    <span className="cx-pane__list-title">{chat.title}</span>
                    <span className="cx-pane__list-meta">
                      {chat.project} · 归档于 {chat.archivedAt}
                    </span>
                  </div>
                  <div className="cx-pane__list-actions">
                    <Button
                      size="sm"
                      variant="ghost"
                      color="secondary"
                      onClick={() => patch({ chats: state.chats.filter((item) => item.id !== chat.id) })}
                    >
                      恢复
                    </Button>
                    <PaneConfirmAction
                      danger
                      confirmLabel="删除"
                      title="删除已归档的聊天？"
                      description="删除后此会话的内容会从本机移除，无法撤销。"
                      onConfirm={() => patch({ chats: state.chats.filter((item) => item.id !== chat.id) })}
                      trigger={
                        <Button size="sm" variant="ghost" color="danger">
                          删除
                        </Button>
                      }
                    />
                  </div>
                </div>
              ))}
            </div>
          )}
        </PaneCard>
      </PaneSection>

      <PaneSection title="数据管理">
        <PaneCard>
          <PaneRow
            label="导出数据"
            description="把聊天记录与设置打包导出，用于备份或迁移到别的机器"
            control={
              <PaneConfirmAction
                confirmLabel="请求导出"
                title="要请求导出数据吗？"
                description="导出在后台进行，完成后会通知你下载位置。"
                onConfirm={() =>
                  patch((prev) => ({
                    ...prev,
                    chats: prev.chats.length > 0 ? prev.chats : DEMO_CHATS,
                  }))
                }
                trigger={
                  <Button size="sm" variant="soft" color="secondary">
                    导出数据
                  </Button>
                }
              />
            }
          />
          <PaneRow
            label="归档策略"
            description="归档的聊天默认保留在本机；关闭后会随项目一起删除关联会话"
            control={
              <Button
                size="sm"
                variant="soft"
                color="secondary"
                onClick={() =>
                  patch((prev) => ({
                    ...prev,
                    chats: [
                      ...prev.chats,
                      { id: newPaneId(), title: "手动归档的聊天", project: "artex", archivedAt: "刚刚" },
                    ],
                  }))
                }
              >
                新增一条
              </Button>
            }
          />
        </PaneCard>
      </PaneSection>
    </PaneShell>
  );
}
