import { Button, Input } from "@/ui";
import type { SettingsPaneProps } from "./index";
import {
  PaneBanner,
  PaneCard,
  PaneConfirmAction,
  PaneEmpty,
  PaneRow,
  PaneSection,
  PaneSelect,
  PaneShell,
  PaneSwitch,
} from "./pane-kit";
import { newPaneId, usePaneState } from "./pane-state";

/**
 * 电脑操控（官方 slug computer-use，chunk computer-use-settings-af5844c05ce8.js，128 条消息）。
 *
 * 行证据（官方 zh-CN / SPEC §4.2.10）：
 *   settings.computerUse.subtitle「管理 ChatGPT 如何使用你电脑上的其他应用程序」
 *   settings.computerUse.install.title「控制」/ .install.empty「Computer Use 插件不可用」
 *   settings.computerUse.anyApp.title「任意应用」/ .description「允许 ChatGPT 控制你电脑上的应用」
 *   settings.computerUse.allowedApps.title「始终允许的应用」
 *   settings.computerUse.backgroundAuth.label「锁屏操作」
 *     / .description「允许 ChatGPT 在 Mac 锁定时使用此 Mac。<a>了解更多</a>」
 *   settings.computerUse.browser.description「使用浏览器扩展程序加强控制」
 *   settings.computerUse.moreBrowsers.title「更多浏览器」/ .description「为更多浏览器设置扩展程序」
 *   settings.computerUse.safari.description「Safari 扩展支持即将推出」
 *   settings.computerUse.messages.description「允许 ChatGPT 读取和发送消息」
 *     / .messages.readAccess.title「读取权限」/ .empty「暂无」/ .addDialog.title「添加聊天」
 *     / .sendAccess.title「发送权限」/ .allowedChats.empty「暂无」
 *     / .chatSearch.placeholder「搜索聊天」/ .chatSearch.empty「未找到聊天」
 *   settings.computerUse.microsoftWord.description / .microsoftExcel.description / .microsoftPowerPoint.description
 *   settings.computerUse.chrome.permissions.title「权限（Chrome）」/ .chrome.policy.browserPermissions.title「浏览器权限（策略）」（SPEC §4.2.10）
 *
 * 此页无实测几何，按通用规格推导（SPEC §8.1）；应用/聊天清单官方无运行时证据（§8.2）。
 */

interface ChatRow {
  id: string;
  name: string;
  detail: string;
}

interface ComputerUsePaneState {
  pluginInstalled: boolean;
  anyApp: boolean;
  allowedApps: { id: string; name: string; path: string }[];
  lockScreen: boolean;
  browserControl: boolean;
  safari: boolean;
  word: boolean;
  excel: boolean;
  powerPoint: boolean;
  messagesEnabled: boolean;
  readAccess: ChatRow[];
  sendAccess: ChatRow[];
  chatQuery: string;
  chromePermission: string;
  chromePolicy: string;
}

const DEFAULTS: ComputerUsePaneState = {
  pluginInstalled: true,
  anyApp: false,
  allowedApps: [],
  lockScreen: false,
  browserControl: true,
  safari: false,
  word: true,
  excel: true,
  powerPoint: false,
  messagesEnabled: false,
  readAccess: [],
  sendAccess: [],
  chatQuery: "",
  chromePermission: "ask",
  chromePolicy: "ask",
};

const PERMISSIONS = [
  { value: "allow", label: "允许" },
  { value: "ask", label: "每次询问" },
  { value: "block", label: "阻止" },
];

const DEMO_APPS = [
  { id: "app-1", name: "Terminal", path: "C:\\Windows\\System32\\cmd.exe" },
  { id: "app-2", name: "Visual Studio Code", path: "C:\\Program Files\\Microsoft VS Code\\Code.exe" },
];

const DEMO_CHATS: ChatRow[] = [
  { id: "c-1", name: "重构设置页导航", detail: "允许读取最近 7 天的消息" },
  { id: "c-2", name: "发布前回归", detail: "允许发送消息" },
];

export function ComputerUsePane({ section }: SettingsPaneProps) {
  const [state, patch, reset] = usePaneState(section, DEFAULTS);
  const keyword = state.chatQuery.trim().toLowerCase();
  const found = DEMO_CHATS.filter((chat) => chat.name.toLowerCase().includes(keyword));

  return (
    <PaneShell
      section={section}
      title="电脑操控"
      lede="管理 ChatGPT 如何使用你电脑上的其他应用程序：逐应用授权、锁屏行为，以及消息读取与发送权限。"
      actions={
        <Button size="sm" variant="soft" color="secondary" onClick={reset}>
          重置
        </Button>
      }
    >
      {!state.pluginInstalled ? (
        <PaneBanner
          tone="warning"
          title="Computer Use 插件不可用"
          description="安装并启用 Computer Use 插件后才能控制桌面应用。"
          action={
            <Button
              size="sm"
              variant="soft"
              color="secondary"
              onClick={() => patch({ pluginInstalled: true })}
            >
              重新检测
            </Button>
          }
        />
      ) : null}

      <PaneSection title="控制">
        <PaneCard>
          <PaneRow
            label="任意应用"
            description="允许 ChatGPT 控制你电脑上的应用"
            control={
              <PaneSwitch
                label="任意应用"
                checked={state.anyApp}
                disabled={!state.pluginInstalled}
                onChange={(checked) => patch({ anyApp: checked })}
              />
            }
          />
          <PaneRow
            label="锁屏操作"
            description="允许 ChatGPT 在 Mac 锁定时使用此 Mac。"
            control={
              <PaneSwitch
                label="锁屏操作"
                checked={state.lockScreen}
                disabled={!state.pluginInstalled}
                onChange={(checked) => patch({ lockScreen: checked })}
              />
            }
          />
          <PaneRow
            label="浏览器"
            description="使用浏览器扩展程序加强控制"
            control={
              <PaneSwitch
                label="浏览器"
                checked={state.browserControl}
                disabled={!state.pluginInstalled}
                onChange={(checked) => patch({ browserControl: checked })}
              />
            }
          />
          <PaneRow
            label="更多浏览器"
            description="为更多浏览器设置扩展程序"
            control={
              <PaneConfirmAction
                confirmLabel="打开设置"
                title="安装更多浏览器扩展程序？"
                description="扩展程序让 ChatGPT 可以读取当前页面并模拟点击；安装后仍需在浏览器里授权。"
                onConfirm={() => patch({ browserControl: true, safari: true })}
                trigger={
                  <Button size="sm" variant="soft" color="secondary" disabled={!state.pluginInstalled}>
                    设置扩展程序
                  </Button>
                }
              />
            }
          />
          <PaneRow
            label="Safari"
            description="Safari 扩展支持即将推出"
            control={<PaneSwitch label="Safari" checked={state.safari} disabled onChange={() => undefined} />}
          />
        </PaneCard>
      </PaneSection>

      <PaneSection title="Office 加载项">
        <PaneCard>
          <PaneRow
            label="Microsoft Word"
            description="允许 ChatGPT 使用 Microsoft Word 加载项，以获得更多控制权限"
            control={
              <PaneSwitch
                label="Microsoft Word"
                checked={state.word}
                onChange={(checked) => patch({ word: checked })}
              />
            }
          />
          <PaneRow
            label="Microsoft Excel"
            description="允许 ChatGPT 使用 Microsoft Excel 加载项以获得更多控制权限"
            control={
              <PaneSwitch
                label="Microsoft Excel"
                checked={state.excel}
                onChange={(checked) => patch({ excel: checked })}
              />
            }
          />
          <PaneRow
            label="Microsoft PowerPoint"
            description="允许 ChatGPT 使用 Microsoft PowerPoint 加载项以获得更多控制权"
            control={
              <PaneSwitch
                label="Microsoft PowerPoint"
                checked={state.powerPoint}
                onChange={(checked) => patch({ powerPoint: checked })}
              />
            }
          />
        </PaneCard>
      </PaneSection>

      <PaneSection title="始终允许的应用">
        <PaneCard>
          {state.allowedApps.length === 0 ? (
            <PaneEmpty
              title="还没有始终允许的应用"
              description="把常用应用加入白名单后，ChatGPT 无需每次询问即可操作它们。"
              action={
                <Button
                  size="sm"
                  variant="soft"
                  color="secondary"
                  onClick={() => patch({ allowedApps: DEMO_APPS })}
                >
                  添加应用
                </Button>
              }
            />
          ) : (
            <div className="cx-pane__list">
              {state.allowedApps.map((app) => (
                <div key={app.id} className="cx-pane__list-item">
                  <div className="cx-pane__list-main">
                    <span className="cx-pane__list-title">{app.name}</span>
                    <span className="cx-pane__list-meta">{app.path}</span>
                  </div>
                  <div className="cx-pane__list-actions">
                    <Button
                      size="sm"
                      variant="ghost"
                      color="danger"
                      onClick={() =>
                        patch((prev) => ({
                          ...prev,
                          allowedApps: prev.allowedApps.filter((item) => item.id !== app.id),
                        }))
                      }
                    >
                      移除
                    </Button>
                  </div>
                </div>
              ))}
              <PaneRow
                label="添加应用"
                description="从本机已安装的应用里选择"
                control={
                  <Button
                    size="sm"
                    variant="soft"
                    color="secondary"
                    onClick={() =>
                      patch((prev) => ({
                        ...prev,
                        allowedApps: [
                          ...prev.allowedApps,
                          { id: newPaneId(), name: "新应用", path: "选择可执行文件…" },
                        ],
                      }))
                    }
                  >
                    添加
                  </Button>
                }
              />
            </div>
          )}
        </PaneCard>
      </PaneSection>

      <PaneSection title="消息" description="允许 ChatGPT 读取和发送消息">
        <PaneCard>
          <PaneRow
            label="允许读取和发送消息"
            description="开启后可以为具体聊天授予读取或发送权限"
            control={
              <PaneSwitch
                label="允许读取和发送消息"
                checked={state.messagesEnabled}
                onChange={(checked) => patch({ messagesEnabled: checked })}
              />
            }
          />
          <PaneRow
            label="读取权限"
            description="ChatGPT 使用此聊天中的消息前会先询问"
            control={
              <span className="cx-pane__input-group">
                <Input
                  size="sm"
                  className="cx-pane__input cx-pane__input--w160"
                  aria-label="搜索聊天"
                  placeholder="搜索聊天"
                  value={state.chatQuery}
                  disabled={!state.messagesEnabled}
                  onChange={(event) => patch({ chatQuery: event.target.value })}
                />
                <Button
                  size="sm"
                  variant="soft"
                  color="secondary"
                  disabled={!state.messagesEnabled}
                  onClick={() =>
                    patch((prev) => ({
                      ...prev,
                      readAccess:
                        found.length === 0
                          ? prev.readAccess
                          : prev.readAccess.some((item) => item.id === found[0].id)
                            ? prev.readAccess
                            : [...prev.readAccess, found[0]],
                    }))
                  }
                >
                  添加聊天
                </Button>
              </span>
            }
          />
          {state.readAccess.length === 0 ? (
            <PaneEmpty
              title={state.messagesEnabled ? "暂无" : "先开启上方开关"}
              description={state.messagesEnabled ? "搜索聊天后添加，即可授予读取权限。" : undefined}
            />
          ) : (
            state.readAccess.map((chat) => (
              <PaneRow
                key={chat.id}
                label={chat.name}
                description={chat.detail}
                control={
                  <Button
                    size="sm"
                    variant="ghost"
                    color="danger"
                    onClick={() =>
                      patch((prev) => ({
                        ...prev,
                        readAccess: prev.readAccess.filter((item) => item.id !== chat.id),
                      }))
                    }
                  >
                    移除权限
                  </Button>
                }
              />
            ))
          )}
          <PaneRow
            label="发送权限"
            description="ChatGPT 会在向此聊天发送消息前询问"
            control={
              <Button
                size="sm"
                variant="soft"
                color="secondary"
                disabled={!state.messagesEnabled}
                onClick={() =>
                  patch((prev) => ({
                    ...prev,
                    sendAccess: [
                      ...prev.sendAccess,
                      { id: newPaneId(), name: "新聊天", detail: "允许发送消息" },
                    ],
                  }))
                }
              >
                添加聊天
              </Button>
            }
          />
          {state.sendAccess.length === 0 ? (
            <PaneEmpty title="暂无" description="授权发送后，这里会列出允许发送消息的聊天。" />
          ) : (
            state.sendAccess.map((chat) => (
              <PaneRow
                key={chat.id}
                label={chat.name}
                description={chat.detail}
                control={
                  <Button
                    size="sm"
                    variant="ghost"
                    color="danger"
                    onClick={() =>
                      patch((prev) => ({
                        ...prev,
                        sendAccess: prev.sendAccess.filter((item) => item.id !== chat.id),
                      }))
                    }
                  >
                    移除权限
                  </Button>
                }
              />
            ))
          )}
        </PaneCard>
      </PaneSection>

      <PaneSection title="权限（Chrome）">
        <PaneCard>
          <PaneRow
            label="权限（Chrome）"
            description="Chrome 扩展读取页面与实际操作时的默认策略"
            control={
              <PaneSelect
                ariaLabel="权限（Chrome）"
                value={state.chromePermission}
                onChange={(value) => patch({ chromePermission: value })}
                options={PERMISSIONS}
              />
            }
          />
          <PaneRow
            label="浏览器权限（策略）"
            description="管理员策略下发时的行为（由策略决定，本地不可覆盖）"
            control={
              <PaneSelect
                ariaLabel="浏览器权限（策略）"
                value={state.chromePolicy}
                onChange={(value) => patch({ chromePolicy: value })}
                options={PERMISSIONS}
              />
            }
          />
        </PaneCard>
      </PaneSection>
    </PaneShell>
  );
}
