import { Button } from "@/ui";
import type { SettingsPaneProps } from "./index";
import {
  PaneBanner,
  PaneCard,
  PaneEmpty,
  PaneKeyValueList,
  PaneRow,
  PaneSection,
  PaneShell,
  PaneTextBlock,
} from "./pane-kit";
import { newPaneId, usePaneState } from "./pane-state";

/**
 * 环境（官方 slug local-environments，chunk local-environments-settings-content-e1b8d83a5962.js，
 * 105 条消息；另 local-environments-settings-page-a36c9363b99e.js / local-environment-editor-e91c708eaaf9.js）。
 *
 * 元素证据（官方 zh-CN）：
 *   settings.localEnvironments.workspaceSelect.title「选择项目」
 *   settings.localEnvironments.workspaceSelect.descriptionWithLink「本地环境用于指导 ChatGPT 如何为项目设置工作树」
 *   settings.localEnvironments.workspaceSelect.empty「尚无项目。添加一个项目以配置本地环境。」
 *   settings.localEnvironments.actions.title「操作」
 *   settings.localEnvironments.environment.setup.description「此脚本会在创建工作树时运行」
 *   settings.localEnvironments.environment.cleanup.title「清理脚本」（SPEC §4.2.16：清理工作树之前在项目根目录下运行）
 *   settings.localEnvironments.environment.setup.envVars.title「设置脚本环境变量」
 *   settings.localEnvironments.environment.create / .edit.title「编辑本地环境」
 *   settings.localEnvironments.unavailable.title「本地环境不可用」/ .body（SPEC §4.2.16）
 *   settings.localEnvironments.environment.empty「此项目尚未配置本地环境」
 *   settings.localEnvironments.environment.script.empty「未配置脚本」
 *   settings.localEnvironments.environment.platformScript.empty「未为此平台配置脚本」
 *
 * 此页无实测几何，按通用规格推导（SPEC §8.1）。
 * 项目列表官方无运行时证据（§8.2）→ 默认用演示项目；用户可移除/恢复。
 */

interface EnvVar {
  id: string;
  key: string;
  value: string;
}

interface EnvironmentPaneState {
  project: string;
  setupScript: string;
  cleanupScript: string;
  envVars: EnvVar[];
  unavailable: boolean;
}

const DEFAULTS: EnvironmentPaneState = {
  project: "artex",
  setupScript: "",
  cleanupScript: "",
  envVars: [],
  unavailable: false,
};

/** 演示项目（官方 workspaceSelect 只确证「选择项目」与空态文案，未给项目清单） */
const _PROJECTS = [
  { value: "artex", label: "artex" },
  { value: "codex-desktop-src", label: "codex-desktop-src" },
  { value: "none", label: "不选择项目" },
];

export function EnvironmentPane({ section }: SettingsPaneProps) {
  const [state, patch, reset] = usePaneState(section, DEFAULTS);
  const hasProject = state.project !== "none";

  return (
    <PaneShell
      section={section}
      title="环境"
      lede="本地环境用于指导 ChatGPT 如何为项目设置工作树：创建时跑设置脚本，清理前跑清理脚本。"
      actions={
        <Button size="sm" variant="soft" color="secondary" onClick={reset}>
          恢复默认
        </Button>
      }
    >
      <PaneSection title="项目">
        <PaneCard>
          <PaneRow
            label="选择项目"
            description="本地环境用于指导 ChatGPT 如何为项目设置工作树"
            control={
              <span className="cx-pane__input-group">
                {hasProject ? (
                  <>
                    <span className="cx-pane__chip">{state.project}</span>
                    <Button
                      size="sm"
                      variant="ghost"
                      color="secondary"
                      onClick={() => patch({ unavailable: !state.unavailable })}
                    >
                      {state.unavailable ? "恢复可用" : "模拟不可用"}
                    </Button>
                  </>
                ) : null}
              </span>
            }
          />
        </PaneCard>
      </PaneSection>

      {!hasProject ? (
        <PaneSection>
          <PaneCard>
            <PaneEmpty
              title="尚无项目。添加一个项目以配置本地环境。"
              description="在左侧选择项目后，这里会显示该项目的设置脚本、清理脚本与环境变量。"
            />
          </PaneCard>
        </PaneSection>
      ) : state.unavailable ? (
        <PaneSection>
          <PaneBanner
            tone="danger"
            title="本地环境不可用"
            description="我们无法加载此项目的本地环境设置。项目可能已被移动或权限不足。"
            action={
              <Button
                size="sm"
                variant="soft"
                color="secondary"
                onClick={() => patch({ unavailable: false })}
              >
                重试
              </Button>
            }
          />
        </PaneSection>
      ) : (
        <>
          <PaneSection title="操作" description="脚本在项目根目录下执行，可以用工作树路径相关的环境变量。">
            <PaneCard>
              {state.setupScript.length === 0 && state.cleanupScript.length === 0 ? (
                <PaneBanner
                  tone="info"
                  title="此项目尚未配置本地环境"
                  description="未配置脚本时，ChatGPT 会使用仓库里的常规约定创建工作树。"
                />
              ) : null}
              <PaneTextBlock
                label="设置脚本"
                description="此脚本会在创建工作树时运行"
                ariaLabel="设置脚本"
                placeholder={state.setupScript.length === 0 ? "未配置脚本" : ""}
                rows={4}
                value={state.setupScript}
                onChange={(value) => patch({ setupScript: value })}
              />
              <PaneTextBlock
                label="清理脚本"
                description="清理工作树之前在项目根目录下运行"
                ariaLabel="清理脚本"
                placeholder={state.cleanupScript.length === 0 ? "未配置脚本" : ""}
                rows={3}
                value={state.cleanupScript}
                onChange={(value) => patch({ cleanupScript: value })}
              />
            </PaneCard>
          </PaneSection>

          <PaneSection title="设置脚本环境变量">
            <PaneCard>
              <PaneRow
                block
                label="设置脚本环境变量"
                description="这些变量只注入到设置脚本（settings.localEnvironments.environment.setup.envVars.title）"
                control={
                  <PaneKeyValueList
                    entries={state.envVars}
                    keyLabel="环境变量名"
                    valueLabel="环境变量值"
                    addLabel="添加环境变量"
                    emptyLabel="还没有环境变量"
                    onChange={(entries) => patch({ envVars: entries })}
                  />
                }
              />
            </PaneCard>
          </PaneSection>

          <PaneSection title="编辑">
            <PaneCard>
              <PaneRow
                label="编辑本地环境"
                description="保存后立即对之后创建的工作树生效（settings.localEnvironments.edit.title）"
                control={
                  <Button
                    size="sm"
                    variant="soft"
                    color="secondary"
                    onClick={() =>
                      patch({ envVars: [...state.envVars, { id: newPaneId(), key: "", value: "" }] })
                    }
                  >
                    添加一行变量
                  </Button>
                }
              />
            </PaneCard>
          </PaneSection>
        </>
      )}
    </PaneShell>
  );
}
