import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { useState } from "react";
import { BrowserRouter, Navigate, Route, Routes } from "react-router-dom";
import { ThemeProvider } from "@/app/theme-provider";
import { SettingsShortcutHost } from "@/settings";
import { AppShell } from "@/shell";
// 路由出口统一从 @/shell/routes 取（那是 Lead 独占的接线文件；
// @/shell 的 barrel 归外壳组维护，避免两边同时改一个文件）。
import {
  ArtexHostRoute,
  ChatRoute,
  ControlsRoute,
  ConversationRoute,
  NotFoundRoute,
  PluginsRouteView,
  ReviewRouteView,
  ScheduledRouteView,
  SettingsRoute,
  SettingsSectionRoute,
  FindingsRouteView,
  IntranetRouteView,
  TasksRouteView,
} from "@/shell/routes";
// ⚠️ 用 @/ui 的 Toaster，不用 sonner 原生的。
// ★ task-46：官方这层容器必须真的渲染 —— 官方 `.codex-toast-area` 是
//   `position: fixed; inset: 0; z-index: 60; pointer-events: none`（SPEC-OVERLAYS §9.1 实测）；
//   不渲染它，sonner 宿主就直接挂在根上、带自己的 inline `z-index: 999999999`（实测），
//   等于用一个「谁都能被盖住/谁都能盖住别人」的层替代官方那层受控容器。
//   接上后大 z-index 仍留在宿主上，但被 60 那层的 stacking context 关在里面（实测见 docs/CONTROLS-SELFCHECK.md §10）。
// 官方 toaster 是**右上、距顶 56px、inset-inline 24px、max-width 320px**
// （[data-sonner-toaster][data-x-position=right]），而 sonner 默认是 top-center ——
// 这里曾经写成 position="top-center" + 自加 class，与官方不符；
// @/ui 的 Toaster 默认已是 top-right 并带官方几何 CSS。
import { ToastArea, Toaster } from "@/ui";

/**
 * 应用根：Provider 组合 + 路由。
 *
 * 路由划分对齐 Codex Desktop 的三个顶层面：
 *   /new                  新建对话（首页态）
 *   /c/:conversationId    会话态
 *   /settings/:section    设置页
 */
export function App() {
  const [queryClient] = useState(
    () =>
      new QueryClient({
        defaultOptions: {
          queries: { staleTime: 30_000, refetchOnWindowFocus: false, retry: 1 },
        },
      }),
  );

  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider>
        <BrowserRouter>
          {/* 设置快捷键（Ctrl+, 打开设置 / Ctrl+/ 打开快捷键分区）注册在路由上下文内 */}
          <SettingsShortcutHost />
          <Routes>
            <Route element={<AppShell />} path="/">
              <Route index element={<Navigate replace to="/new" />} />
              <Route element={<ChatRoute />} path="new" />
              <Route element={<ConversationRoute />} path="c/:conversationId" />
              {/* rail 的其余四项。官方 rail 实测序：首页 / 定时任务 / 插件 / 探索 ── 代码审查。
                  ⚠️ /explore **不是页面**：官方就是重定向 ——
                  `app-initial-25361a10f2bf.js` 偏移 **11,851,996**（第 **164,633** 行）：
                  `<Route path='/explore' element={<Navigate to='/' replace/>}/>`；
                  官方目的地注册表里没有 explore（导轨第 4 项的身份是 i18n `sidebarCustomization.moreMenu`，
                  即「菜单」）。证据：docs/RECON-EXPLORE-ROUTE.md（task-39）。
                  以前这里挂的是一个完整页面 ⇒ 手输 URL 会看到一个官方并不存在的页面。 */}
              <Route element={<ScheduledRouteView />} path="scheduled" />
              <Route element={<ScheduledRouteView />} path="automations" />
              <Route element={<PluginsRouteView />} path="plugins" />
              <Route element={<PluginsRouteView />} path="skills" />
              <Route element={<Navigate replace to="/" />} path="explore" />
              <Route element={<ReviewRouteView />} path="review" />
          {/* 任务：外壳原生页（rails「任务」的 kind 已翻成 shell） */}
          <Route element={<TasksRouteView />} path="tasks" />
          <Route element={<FindingsRouteView />} path="findings" />
          <Route element={<IntranetRouteView />} path="intranet" />
              <Route element={<ReviewRouteView />} path="pull-requests" />
              {/* 设置页自带分区导航（读 :section），两种路径都指向同一组件 */}
              <Route element={<SettingsRoute />} path="settings" />
              <Route element={<SettingsSectionRoute />} path="settings/:section" />
              {/* 控件库（/controls）：设置里「控件库」入口的落地页（task-38 用户需求） */}
              <Route element={<ControlsRoute />} path="controls" />
              {/* 宿主容器（/artex）：把本地应用托进外壳（src/shell/host/）。
                  地址由 ?artex=<url> / VITE_ARTEX_HOST_URL / 环境默认值 三级解析，见 host-config.ts。 */}
              <Route element={<ArtexHostRoute />} path="artex" />
              <Route element={<NotFoundRoute />} path="*" />
            </Route>
          </Routes>
        </BrowserRouter>
        <ToastArea>
          <Toaster className="codex-sonner-toaster" />
        </ToastArea>
      </ThemeProvider>
    </QueryClientProvider>
  );
}
