import { Button, Input } from "@/ui";
import type { SettingsPaneProps } from "./index";
import {
  PaneBanner,
  PaneCard,
  PaneEmpty,
  PaneRow,
  PaneSection,
  PaneSelect,
  PaneShell,
  PaneSwitch,
  PaneTextBlock,
} from "./pane-kit";
import { usePaneState } from "./pane-state";

/**
 * 代码审查（官方 slug code-review，chunk settings-d8b4a0d22da7.js，100 条消息）。
 *
 * 分组证据（SPEC §4.2.14）：个人偏好 · 代码仓库 · 个人安全检查偏好。
 * 行证据（官方 zh-CN）：
 *   settings.codeReview.personal.title「个人偏好」
 *     / .autoReview.label「自动代码审查」/ .description「自动审查已启用代码审查的仓库中的 Pull Request」
 *     / .trigger.label「审核触发条件」/ .description「选择 ChatGPT 何时审查你的 Pull Request」
 *     / .exhaustive.label「全面代码审查」/ .description「继续查找结果，直到 ChatGPT 不再发现新问题」
 *     / .credits.label「将额度用于审查」/ .description「达到速率限制后，允许消耗额度进行审查」
 *   settings.codeReview.repositories.title「代码仓库」/ .description「选择一个代码仓库，为其配置自动审查」
 *     / .empty「未找到代码仓库」/ .search.label / .placeholder「搜索代码仓库」
 *   settings.codeReview.repository.subtitle「管理 Codex 审查此代码仓库的方式」
 *     / .instructions.title「代码审查说明」/ .description「在此代码仓库的 AGENTS.md 中添加代码审查指南」
 *     / .autoSeverity.description「选择 Codex 在自动审查中应报告的最低严重级别」
 *     / .manualSeverity.description「选择通过 @codex 请求审查时 Codex 应报告的最低严重级别」
 *     / .pathRules.description「覆盖特定代码仓库路径的报告严重级别」/ .newPath.placeholder「src/」
 *     / .threatPath.description / .placeholder「docs/threat-model.md」
 *     / .blockingSeverity.description / .mergeProtection.description（GitHub 检查阻断合并）
 *   settings.codeReview.security.subtitle「控制 Codex 默认如何对你的 Pull Request 进行安全审查」
 *     / .autoReview.label「自动安全审查」/ .description
 *     / .autoSeverity.label「自动审查报告的最低严重级别」/ .description
 *     / .manualSeverity.label「人工审核报告的最低严重级别」/ .description
 *     / .credits.label「将额度用于安全审查」/ .description
 *     / .billingNotice.title「安全审查的计费方式即将调整」
 *   触发条件取值（官方 select 选项）：遵循个人偏好 / 打开 PR 时 / 每次推送时 / 智能检测（实验性）/ 每次运行代码审查时
 *
 * 此页无实测几何，按通用规格推导（SPEC §8.1）。
 * 仓库清单与严重级别取值官方无运行时证据（§8.2）→ 仓库用演示值，严重级别四档为演绎值。
 */

interface PathRule {
  id: string;
  path: string;
  severity: string;
}

interface CodeReviewPaneState {
  autoReview: boolean;
  trigger: string;
  exhaustive: boolean;
  credits: boolean;
  repository: string;
  repoQuery: string;
  instructions: string;
  autoSeverity: string;
  manualSeverity: string;
  pathRules: PathRule[];
  threatPath: string;
  blockingEnabled: boolean;
  blockingSeverity: string;
  securityAutoReview: boolean;
  securityCredits: boolean;
  securityAutoSeverity: string;
  securityManualSeverity: string;
  billingNoticeDismissed: boolean;
}

const DEFAULTS: CodeReviewPaneState = {
  autoReview: false,
  trigger: "personal",
  exhaustive: false,
  credits: false,
  repository: "codex-desktop-src",
  repoQuery: "",
  instructions: "",
  autoSeverity: "medium",
  manualSeverity: "low",
  pathRules: [],
  threatPath: "",
  blockingEnabled: false,
  blockingSeverity: "high",
  securityAutoReview: false,
  securityCredits: false,
  securityAutoSeverity: "medium",
  securityManualSeverity: "low",
  billingNoticeDismissed: false,
};

const TRIGGERS = [
  { value: "personal", label: "遵循个人偏好" },
  { value: "pr_open", label: "打开 PR 时" },
  { value: "every_push", label: "每次推送时" },
  { value: "smart_detect", label: "智能检测（实验性）" },
  { value: "code_review", label: "每次运行代码审查时" },
];

/** 严重级别取值官方未实测（§8.2）→ 四档为演绎值 */
const SEVERITIES = [
  { value: "low", label: "低" },
  { value: "medium", label: "中" },
  { value: "high", label: "高" },
  { value: "critical", label: "严重" },
];

const REPOSITORIES = [
  { value: "codex-desktop-src", label: "codex-desktop-src" },
  { value: "artex", label: "artex" },
  { value: "none", label: "不选择仓库" },
];

export function CodeReviewPane({ section }: SettingsPaneProps) {
  const [state, patch, reset] = usePaneState(section, DEFAULTS);
  const hasRepo = state.repository !== "none";

  return (
    <PaneShell
      section={section}
      title="代码审查"
      lede="Codex 自动审查 Pull Request 的触发条件、仓库级说明，以及安全审查的最低严重级别。"
      actions={
        <Button size="sm" variant="soft" color="secondary" onClick={reset}>
          恢复默认
        </Button>
      }
    >
      <PaneSection title="个人偏好">
        <PaneCard>
          <PaneRow
            label="自动代码审查"
            description="自动审查已启用代码审查的仓库中的 Pull Request"
            control={
              <PaneSwitch
                label="自动代码审查"
                checked={state.autoReview}
                onChange={(checked) => patch({ autoReview: checked })}
              />
            }
          />
          <PaneRow
            label="审核触发条件"
            description="选择 ChatGPT 何时审查你的 Pull Request"
            control={
              <PaneSelect
                ariaLabel="审核触发条件"
                value={state.trigger}
                onChange={(value) => patch({ trigger: value })}
                options={TRIGGERS}
              />
            }
          />
          <PaneRow
            label="全面代码审查"
            description="继续查找结果，直到 ChatGPT 不再发现新问题"
            control={
              <PaneSwitch
                label="全面代码审查"
                checked={state.exhaustive}
                disabled={!state.autoReview}
                onChange={(checked) => patch({ exhaustive: checked })}
              />
            }
          />
          <PaneRow
            label="将额度用于审查"
            description="达到速率限制后，允许消耗额度进行审查"
            control={
              <PaneSwitch
                label="将额度用于审查"
                checked={state.credits}
                disabled={!state.autoReview}
                onChange={(checked) => patch({ credits: checked })}
              />
            }
          />
        </PaneCard>
      </PaneSection>

      <PaneSection title="代码仓库" description="选择一个代码仓库，为其配置自动审查">
        <PaneCard>
          <PaneRow
            label="代码仓库"
            description="管理 Codex 审查此代码仓库的方式"
            control={
              <span className="cx-pane__input-group">
                <Input
                  size="sm"
                  className="cx-pane__input cx-pane__input--w180"
                  aria-label="搜索代码仓库"
                  placeholder="搜索代码仓库"
                  value={state.repoQuery}
                  onChange={(event) => patch({ repoQuery: event.target.value })}
                />
                <PaneSelect
                  ariaLabel="代码仓库"
                  value={state.repository}
                  onChange={(value) => patch({ repository: value })}
                  options={
                    state.repoQuery.trim()
                      ? REPOSITORIES.filter((item) =>
                          item.label.toLowerCase().includes(state.repoQuery.trim().toLowerCase()),
                        )
                      : REPOSITORIES
                  }
                />
              </span>
            }
          />
          {!hasRepo ? (
            <PaneEmpty title="未找到代码仓库" description="选择仓库后才能编辑仓库级审查说明与严重级别。" />
          ) : (
            <>
              <PaneTextBlock
                label="代码审查说明"
                description="在此代码仓库的 AGENTS.md 中添加代码审查指南"
                ariaLabel="代码审查说明"
                placeholder="例如：不要重复指出格式问题；安全相关改动必须给出利用路径"
                rows={4}
                value={state.instructions}
                onChange={(value) => patch({ instructions: value })}
              />
              <PaneRow
                label="自动审查最低严重级别"
                description="选择 Codex 在自动审查中应报告的最低严重级别"
                control={
                  <PaneSelect
                    ariaLabel="自动审查最低严重级别"
                    value={state.autoSeverity}
                    onChange={(value) => patch({ autoSeverity: value })}
                    options={SEVERITIES}
                  />
                }
              />
              <PaneRow
                label="人工审查最低严重级别"
                description="选择通过 @codex 请求审查时 Codex 应报告的最低严重级别"
                control={
                  <PaneSelect
                    ariaLabel="人工审查最低严重级别"
                    value={state.manualSeverity}
                    onChange={(value) => patch({ manualSeverity: value })}
                    options={SEVERITIES}
                  />
                }
              />
              <PaneRow
                label="路径级严重级别"
                description="覆盖特定代码仓库路径的报告严重级别"
                control={
                  <Button
                    size="sm"
                    variant="soft"
                    color="secondary"
                    onClick={() =>
                      patch({
                        pathRules: [
                          ...state.pathRules,
                          {
                            id: `path-${String(state.pathRules.length + 1)}`,
                            path: "src/",
                            severity: "high",
                          },
                        ],
                      })
                    }
                  >
                    添加路径规则
                  </Button>
                }
              />
              {state.pathRules.map((rule) => (
                <PaneRow
                  key={rule.id}
                  label={<span className="cx-pane__value--mono">{rule.path}</span>}
                  description="该路径下的问题按指定级别上报"
                  control={
                    <span className="cx-pane__input-group">
                      <Input
                        size="sm"
                        className="cx-pane__input cx-pane__input--w160"
                        aria-label="路径"
                        value={rule.path}
                        placeholder="src/"
                        onChange={(event) =>
                          patch((prev) => ({
                            ...prev,
                            pathRules: prev.pathRules.map((item) =>
                              item.id === rule.id ? { ...item, path: event.target.value } : item,
                            ),
                          }))
                        }
                      />
                      <PaneSelect
                        ariaLabel="路径严重级别"
                        value={rule.severity}
                        onChange={(value) =>
                          patch((prev) => ({
                            ...prev,
                            pathRules: prev.pathRules.map((item) =>
                              item.id === rule.id ? { ...item, severity: value } : item,
                            ),
                          }))
                        }
                        options={SEVERITIES}
                      />
                      <Button
                        size="sm"
                        variant="ghost"
                        color="danger"
                        onClick={() =>
                          patch((prev) => ({
                            ...prev,
                            pathRules: prev.pathRules.filter((item) => item.id !== rule.id),
                          }))
                        }
                      >
                        删除
                      </Button>
                    </span>
                  }
                />
              ))}
              <PaneTextBlock
                label="威胁模型路径"
                description="文件路径以代码仓库根目录为基准。若未指定，Codex 会在每次审查时生成威胁模型。"
                ariaLabel="威胁模型路径"
                placeholder="docs/threat-model.md"
                rows={1}
                value={state.threatPath}
                onChange={(value) => patch({ threatPath: value })}
              />
            </>
          )}
        </PaneCard>
      </PaneSection>

      <PaneSection title="个人安全检查偏好" description="控制 Codex 默认如何对你的 Pull Request 进行安全审查">
        <PaneCard>
          <PaneRow
            label="自动安全审查"
            description="自动对已启用的代码仓库中的拉取请求进行安全审查"
            control={
              <PaneSwitch
                label="自动安全审查"
                checked={state.securityAutoReview}
                onChange={(checked) => patch({ securityAutoReview: checked })}
              />
            }
          />
          <PaneRow
            label="自动审查报告的最低严重级别"
            description="选择自动审查报告的最低严重级别"
            control={
              <PaneSelect
                ariaLabel="自动审查报告的最低严重级别"
                value={state.securityAutoSeverity}
                onChange={(value) => patch({ securityAutoSeverity: value })}
                options={SEVERITIES}
              />
            }
          />
          <PaneRow
            label="人工审核报告的最低严重级别"
            description="选择使用 @codex 请求审查时报告的最低严重级别"
            control={
              <PaneSelect
                ariaLabel="人工审核报告的最低严重级别"
                value={state.securityManualSeverity}
                onChange={(value) => patch({ securityManualSeverity: value })}
                options={SEVERITIES}
              />
            }
          />
          <PaneRow
            label="将额度用于安全审查"
            description="安全审查会使用此账户的 Codex 共享配额。开启此选项后，将在配额用尽后使用额度。"
            control={
              <PaneSwitch
                label="将额度用于安全审查"
                checked={state.securityCredits}
                onChange={(checked) => patch({ securityCredits: checked })}
              />
            }
          />
          <PaneRow
            label="阻断合并的严重级别"
            description="当安全审查报告的问题严重程度达到或超过此级别时，GitHub 检查将不通过；要阻止合并还需在 GitHub 中把该检查设为必需检查。"
            control={
              <span className="cx-pane__input-group">
                <PaneSwitch
                  label="启用阻断级别"
                  checked={state.blockingEnabled}
                  onChange={(checked) => patch({ blockingEnabled: checked })}
                />
                <PaneSelect
                  ariaLabel="阻断合并的严重级别"
                  value={state.blockingSeverity}
                  onChange={(value) => patch({ blockingSeverity: value })}
                  options={SEVERITIES}
                  disabled={!state.blockingEnabled}
                />
              </span>
            }
          />
          {state.billingNoticeDismissed ? null : (
            <PaneBanner
              tone="info"
              title="安全审查的计费方式即将调整"
              description="调整后安全审查会单独计量；当前仍计入共享配额。"
              action={
                <Button
                  size="sm"
                  variant="ghost"
                  color="secondary"
                  onClick={() => patch({ billingNoticeDismissed: true })}
                >
                  知道了
                </Button>
              }
            />
          )}
        </PaneCard>
      </PaneSection>
    </PaneShell>
  );
}
