import { Button } from "@/ui";
import type { SettingsPaneProps } from "./index";
import {
  PaneBanner,
  PaneCard,
  PaneConfirmAction,
  PaneEmpty,
  PaneRow,
  PaneSection,
  PaneSelect,
  PaneShell,
  PaneSwitch,
  PaneTabs,
} from "./pane-kit";
import { newPaneId, usePaneState } from "./pane-state";

/**
 * 插件（官方 slug plugins-settings，chunk plugins-settings-5b90886f487e.js 87KB + skills-page-*）。
 *
 * 行证据（官方 zh-CN）：
 *   settings.mcp.apps.title「MCP 应用」/ settings.mcp.empty「未连接 MCP 服务器」
 *   settings.mcp.apps.data.label「应用数据」/ .description「清除所有 MCP 应用的站点数据和缓存」
 *     / .clearData「清除所有应用数据」/ .clearData.success「已清除 MCP 应用数据」/ .clearData.error「无法清除 MCP 应用数据」
 *   settings.mcp.detail.transport.label「类型」（stdio / http）+ .detail.command「启动命令」/ .detail.http.url「URL」
 *   settings.mcp.detail.name「名称」/ .detail.envVars「环境变量」/ .detail.save「保存」/ .detail.saveError
 *   settings.mcp.server.clientRegistration.label「OAuth 客户端注册：{auto/CIMD/DCR}」（自动 / CIMD / DCR）
 *   skills.appsPage.loadError.title「无法加载应用」/ .marketplace.loadError.title「无法加载插件市场」
 *     / .marketplace.partialLoadError.title「部分插件市场无法加载」
 *     / .marketplace.removeDialog.title「是否移除"{marketplaceName}"？」
 *     / .pluginsUnsupportedHost.title「此主机不支持插件」/ .pluginsUnsupportedHost.description「选择其他主机以浏览和管理插件」
 *   页内 tabs：插件 / 技能（SPEC §4.2.9：plugins 页与 skills-page-* 共用）
 *
 * 此页无实测几何，按通用规格推导（SPEC §8.1）；插件/技能清单官方无运行时证据（§8.2）。
 */

interface PluginEntry {
  id: string;
  name: string;
  detail: string;
  enabled: boolean;
  kind: "plugin" | "skill";
}

interface McpServer {
  id: string;
  name: string;
  transport: string;
  endpoint: string;
}

interface PluginsPaneState {
  tab: string;
  entries: PluginEntry[];
  servers: McpServer[];
  clientRegistration: string;
  marketplaceError: string;
  dataCleared: boolean;
}

const DEFAULTS: PluginsPaneState = {
  tab: "plugins",
  entries: [],
  servers: [],
  clientRegistration: "auto",
  marketplaceError: "",
  dataCleared: false,
};

const DEMO_ENTRIES: PluginEntry[] = [
  { id: "p-1", name: "GitHub", detail: "仓库、Issue 与 PR", enabled: true, kind: "plugin" },
  { id: "p-2", name: "Linear", detail: "议题同步", enabled: false, kind: "plugin" },
  { id: "s-1", name: "pdf 解析", detail: "读取 PDF 并抽取表格", enabled: true, kind: "skill" },
  { id: "s-2", name: "docx 报告", detail: "生成 Word 文档", enabled: true, kind: "skill" },
];

const DEMO_SERVERS: McpServer[] = [
  {
    id: "m-1",
    name: "filesystem",
    transport: "stdio",
    endpoint: "npx -y @modelcontextprotocol/server-filesystem",
  },
  { id: "m-2", name: "sentry", transport: "http", endpoint: "https://mcp.sentry.dev/mcp" },
];

const CLIENT_REGISTRATION = [
  { value: "auto", label: "自动" },
  { value: "cimd", label: "CIMD" },
  { value: "dcr", label: "DCR" },
];

const TRANSPORTS = [
  { value: "stdio", label: "类型：stdio" },
  { value: "http", label: "类型：http" },
];

export function PluginsPane({ section }: SettingsPaneProps) {
  const [state, patch, reset] = usePaneState(section, DEFAULTS);

  function setEntry(id: string, update: Partial<PluginEntry>) {
    patch((prev) => ({
      ...prev,
      entries: prev.entries.map((item) => (item.id === id ? { ...item, ...update } : item)),
    }));
  }

  const rows = state.entries.filter((entry) => entry.kind === state.tab);

  return (
    <PaneShell
      section={section}
      title="插件"
      lede="插件与技能扩展 Codex 的能力；MCP 应用页签管理外部服务器、类型与 OAuth 客户端注册方式。"
      actions={
        <>
          <Button size="sm" variant="soft" color="secondary" onClick={reset}>
            重置
          </Button>
          <Button
            size="sm"
            variant="soft"
            color="secondary"
            onClick={() => patch({ entries: state.entries.length > 0 ? state.entries : DEMO_ENTRIES })}
          >
            加载已安装列表
          </Button>
        </>
      }
    >
      <PaneTabs
        ariaLabel="插件页签"
        tabs={[
          { value: "plugins", label: "插件" },
          { value: "skill", label: "技能" },
          { value: "mcp", label: "MCP 应用" },
        ]}
        value={state.tab}
        onChange={(value) => patch({ tab: value })}
      />

      {state.marketplaceError ? (
        <PaneBanner
          tone="danger"
          title="部分插件市场无法加载"
          description={state.marketplaceError}
          action={
            <Button
              size="sm"
              variant="soft"
              color="secondary"
              onClick={() => patch({ marketplaceError: "" })}
            >
              重试
            </Button>
          }
        />
      ) : null}

      {state.tab === "mcp" ? (
        <>
          <PaneSection title="MCP 应用" description={`${String(state.servers.length)} 个服务器已连接`}>
            <PaneCard>
              {state.servers.length === 0 ? (
                <PaneEmpty
                  title="未连接 MCP 服务器"
                  description="添加一个服务器后，它的工具会出现在对话的工具列表里。"
                  action={
                    <Button
                      size="sm"
                      variant="soft"
                      color="secondary"
                      onClick={() => patch({ servers: DEMO_SERVERS })}
                    >
                      连接服务器
                    </Button>
                  }
                />
              ) : (
                <div className="cx-pane__list">
                  {state.servers.map((server) => (
                    <div key={server.id} className="cx-pane__list-item">
                      <div className="cx-pane__list-main">
                        <span className="cx-pane__list-title">{server.name}</span>
                        <span className="cx-pane__list-meta">{server.endpoint}</span>
                      </div>
                      <div className="cx-pane__list-actions">
                        <PaneSelect
                          ariaLabel={`${server.name} 类型`}
                          value={server.transport}
                          onChange={(value) =>
                            patch((prev) => ({
                              ...prev,
                              servers: prev.servers.map((item) =>
                                item.id === server.id ? { ...item, transport: value } : item,
                              ),
                            }))
                          }
                          options={TRANSPORTS}
                        />
                        <Button
                          size="sm"
                          variant="ghost"
                          color="danger"
                          onClick={() =>
                            patch((prev) => ({
                              ...prev,
                              servers: prev.servers.filter((item) => item.id !== server.id),
                            }))
                          }
                        >
                          移除
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </PaneCard>
          </PaneSection>

          <PaneSection title="OAuth 客户端注册">
            <PaneCard>
              <PaneRow
                label="OAuth 客户端注册"
                description="决定 MCP 服务器如何注册客户端：自动 / CIMD / DCR"
                control={
                  <PaneSelect
                    ariaLabel="OAuth 客户端注册"
                    value={state.clientRegistration}
                    onChange={(value) => patch({ clientRegistration: value })}
                    options={CLIENT_REGISTRATION}
                  />
                }
              />
              <PaneRow
                label="应用数据"
                description="清除所有 MCP 应用的站点数据和缓存"
                control={
                  <PaneConfirmAction
                    confirmLabel="清除所有应用数据"
                    title="清除所有应用数据？"
                    description="清理后需要重新登录依赖 OAuth 的 MCP 服务器。"
                    onConfirm={() => patch({ dataCleared: true })}
                    trigger={
                      <Button size="sm" variant="soft" color="secondary">
                        清除
                      </Button>
                    }
                  />
                }
              />
              {state.dataCleared ? (
                <PaneBanner
                  tone="success"
                  title="已清除 MCP 应用数据"
                  description="站点数据与缓存已清空。"
                  action={
                    <Button
                      size="sm"
                      variant="ghost"
                      color="secondary"
                      onClick={() => patch({ dataCleared: false })}
                    >
                      关闭
                    </Button>
                  }
                />
              ) : null}
            </PaneCard>
          </PaneSection>
        </>
      ) : (
        <PaneSection
          title={state.tab === "plugins" ? "已安装插件" : "技能"}
          description={
            rows.length === 0
              ? "无法加载应用"
              : `${String(rows.filter((row) => row.enabled).length)} / ${String(rows.length)} 已启用`
          }
        >
          <PaneCard>
            {rows.length === 0 ? (
              <PaneEmpty
                title={state.tab === "plugins" ? "还没有安装插件" : "还没有安装技能"}
                description={
                  state.tab === "plugins"
                    ? "从插件市场安装后，插件会出现在这里，可以逐个启用或移除。"
                    : "技能来自已安装的插件与本地目录；安装后可以在这里启停。"
                }
                action={
                  <Button
                    size="sm"
                    variant="soft"
                    color="secondary"
                    onClick={() => patch({ entries: DEMO_ENTRIES, marketplaceError: "" })}
                  >
                    {state.tab === "plugins" ? "浏览插件市场" : "扫描本地技能"}
                  </Button>
                }
              />
            ) : (
              <div className="cx-pane__list">
                {rows.map((row) => (
                  <PaneRow
                    key={row.id}
                    label={row.name}
                    description={row.detail}
                    control={
                      <span className="cx-pane__input-group">
                        <PaneSwitch
                          label={`${row.name} 启用`}
                          checked={row.enabled}
                          onChange={(checked) => setEntry(row.id, { enabled: checked })}
                        />
                        <PaneConfirmAction
                          danger
                          confirmLabel="移除"
                          title={`是否移除"${row.name}"？`}
                          description="移除后该来源提供的工具与技能会立即不可用。"
                          onConfirm={() =>
                            patch((prev) => ({
                              ...prev,
                              entries: prev.entries.filter((item) => item.id !== row.id),
                            }))
                          }
                          trigger={
                            <Button size="sm" variant="ghost" color="danger">
                              移除
                            </Button>
                          }
                        />
                      </span>
                    }
                  />
                ))}
                <PaneRow
                  label="添加本地插件"
                  description="从本地目录或 Git 仓库添加插件源"
                  control={
                    <Button
                      size="sm"
                      variant="soft"
                      color="secondary"
                      onClick={() =>
                        patch((prev) => ({
                          ...prev,
                          entries: [
                            ...prev.entries,
                            {
                              id: newPaneId(),
                              name: "本地插件",
                              detail: "手动添加的来源",
                              enabled: false,
                              kind: prev.tab === "plugins" ? "plugin" : "skill",
                            },
                          ],
                        }))
                      }
                    >
                      添加来源
                    </Button>
                  }
                />
              </div>
            )}
          </PaneCard>
        </PaneSection>
      )}
    </PaneShell>
  );
}
